// live/text_notes_ru.js: the notes found on the floors; generated by tools/notes_build.py from docs/notes/*.json, edit those.
(function (root) {
  (root.TEXT || (root.TEXT = {})).notes = [{"id":"cellar_001","kind":"note","title":"Записка в щели","text":"Кто бы ни держал соседний отсек, простите меня. За щелью в стене стоит ваша плошка с солью, я дотянулась до неё и взяла горсть. Моя соль вышла, лавка закрыта до пятницы, а муж и трое детей просят супа. Верну вам с горкой, честное слово, я не из тех, кто берёт без спроса. Гвен Марлоу, шестой подвал.","chain":"salt_loan","part":1},{"id":"cellar_002","kind":"note","title":"Список к свадьбе","text":"Том, вот что надо к свадьбе нашей Розы, и не перепутай. Купи шесть мер муки и изюма, сколько дадут. Скатерть я возьму у Гертруды и на этот раз верну её чистой, я ей поклялась. Жениха надо побрить, мальчик он хороший, но сам не догадается. Дядю Альберта мы не зовём, но ты же знаешь, какой он, всё равно придёт, так что хлеба бери ещё на двоих. Наша девочка выходит замуж, Том. Я плачу над этим списком, не смейся."},{"id":"cellar_003","kind":"note","title":"Наряд подмастерью","text":"Перси, сегодня сходи к Хобарту на Мельничную и поставь ему замок на подвальную дверь, снаружи, как теперь все ставят. Бери большой, он заплатит. Петли тоже смажь, его жена жаловалась, что дверь скрипит. Пирог на столе отнесёшь ему, это заказчику, и я его измерил, так что не вздумай отщипнуть. И надень шарф, на улице сыро, а лечить тебя мне не на что.","chain":"hobart_locks","part":1},{"id":"cellar_004","kind":"note","title":"Трактирный счёт","text":"Таверна «Три гуся», счёт господину Пику. Вы выпили пять кружек эля, а потом ещё пять. За беспокойство от вашего пения с вас две монеты, за сломанную скамью одна, за кружку, которая ушла с вами домой, полмонеты. Кружку прошу вернуть, она была у нас одна с ручкой, и жена моя по ней плачет. Пели вы, кстати, неплохо, пока не начали про козу. Хозяин Бен."},{"id":"cellar_005","kind":"note","title":"Продажа дома","text":"Продаётся дом на Кожевенной. Стены крепкие, печь новая, колодец во дворе, до рынка два шага. Цена ниже, чем вы думаете. Мы с женой прожили здесь сорок два года, и я бы никогда его не продал, будь она жива. Смотреть приходите только днём. Ключ возьмёте у соседки, потому что я там больше не ночую и вам не советую."},{"id":"cellar_006","kind":"note","title":"Школьная пропись","text":"Перепиши десять раз: я не буду кидать репу в мастера Кроуфорда. Я не буду кидать репу в мастера Кроуфорда. Я не буду кидать репу в мастера Кроуфорда. Я не буду кидать репу в мастера. Мастер Кроуфорд, я устал, дальше там всё то же самое, честное слово. Мама говорит, что вы хороший человек и что в ухо я попал вам нечаянно. Я попал нарочно, но вы правда хороший."},{"id":"cellar_007","kind":"note","title":"Молитва на ночь","text":"боже мама сказала что написанное доходит до тебя быстрей. сделай чтобы папа перестал кашлять. сделай чтобы Нэн отдала мою ленту только ругать её не надо она моя сестра. и пусть тот кто ходит у нас под полом ходит потише а то он будит малинького. аминь"},{"id":"cellar_008","kind":"note","title":"Записка в щели","text":"Соседка, соль я вернула, как обещала, и с горкой. Спасибо вам за яйцо, я его не просила, но оно крупное и свежее, и мы съели его за завтраком. Как вас зовут? Мне неловко писать вам, как чужой, мы ведь теперь почти родня по соли. Муж уверяет, что за этой стеной одна земля, а он сам клал тут полки, так что я уже не знаю, кому верить. Гвен.","chain":"salt_loan","part":2},{"id":"cellar_009","kind":"note","title":"Черновик эпитафии","text":"Мастеру камнерезу от вдовы Флинт. Прошу написать так: здесь лежит Бартоломью Флинт, кровельщик, упал только один раз. Он двадцать лет хвастался, что ни разу не падал, и я хочу, чтобы последнее слово осталось за мной. Заплатить я могу четыре монеты. Если буквы выйдут дороже, уберите слово кровельщик, все и так знали, кем он был. Мне его очень не хватает, но больше у меня нет."},{"id":"cellar_010","kind":"note","title":"Рецепт мази","text":"Милая Джейн, ты просила написать, чем я лечу паучьи укусы. Возьми ложку гусиного жира и истолки в нём подорожник. Мажь на ночь и завязывай чистой тряпкой. Если к утру укус перешёл на другое место, мазь уже не поможет, тогда зови лекаря Тиббета и заплати ему вперёд, иначе он не придёт, ты же знаешь, какой он жадина. Береги детей и пиши мне почаще. Твоя тётя Энн."},{"id":"cellar_011","kind":"note","title":"Правила приказчику","text":"Тоби, сыр режь при покупателе, чтобы никто не говорил, будто мы его подменяем. В долг Морганам не давай, и тем Морганам, что из соседнего дома, тоже. Если спросят, свежий ли сыр, отвечай, что принесли утром, а какое это было утро, уточнять необязательно. Дверцу в подпол на ночь запирай на крючок. Крючок у нас с этой стороны, а вчера утром он был откинут, и сделал это не я. И ешь как следует, ты совсем худой."},{"id":"cellar_012","kind":"note","title":"Наряд подмастерью","text":"Перси, Хобарт приходил опять и просит второй замок на ту же дверь, пониже первого. У человека завелись либо деньги, либо крысы. Деньги он отдал вперёд, чего за ним раньше не водилось, и руки у него тряслись, пока он их отсчитывал. Ты с ним поласковей, мы с ним в детстве вместе воровали яблоки. Возьми средний замок и новые винты, старые ты опять потерял, растяпа.","chain":"hobart_locks","part":2},{"id":"cellar_013","kind":"note","title":"Очередь к колодцу","text":"Очередь к колодцу для тех, кто опять забыл. В понедельник воду берут Тэннеры, во вторник Холлы, в среду снова Тэннеры, раз уж Холлы вечно забывают про свой день. В четверг идут Рэдли. В пятницу никто не ходит, потому что ведро по пятницам поднимается тяжелее, чем опускали, и мы все это видели. В субботу берут Холлы, и пусть наконец принесут свою верёвку. Марта Холл, это про тебя, я всё помню."},{"id":"cellar_014","kind":"note","title":"Любовная записка","text":"Эдвин, матушка уезжает в среду на весь день. Принеси, пожалуйста, того сыра, что мы ели на ярмарке. Это я всерьёз, сыр мне очень понравился. Можешь и сам прийти. Я уже три дня только об этом и думаю, о сыре, разумеется."},{"id":"cellar_015","kind":"note","title":"Записанная шутка","text":"Записываю шутку мельника, чтобы рассказать на празднике. Приходит сборщик податей к вдове и спрашивает, что у неё есть в подвале. Она отвечает: паутина. Он спрашивает, сколько. Она говорит: забирайте всю. Когда рассказывал мельник, мы с сёстрами смеялись до слёз, а теперь я записала и вижу, что вышло неверно. Там ещё был осёл. Придётся зайти к мельнику и спросить, а мне только того и надо."},{"id":"cellar_016","kind":"note","title":"Записка Гарольду","text":"Гарольд, сердце моё, не сердись. Я продала твои старые сапоги, потому что они текли, и на эти деньги взяла тебе новые, получше. Новые оказались малы, и я их тоже продала, правда, дешевле. Суп стоит на печи, ешь, пока горячий. Я вернусь от сестры к вечеру, и мы вместе подумаем, в чём тебе завтра идти на работу. Твоя Бетси, которая тебя любит и надеется на то же самое."},{"id":"cellar_017","kind":"note","title":"Приказ цеха","text":"Цех свечников приказывает больше не хранить воск под амбаром Дарби. Свечи третьей партии горят как положено, только пламя у них клонится к полу, хотя сквозняка там нет. Партию продайте в соседний приход, они там ни на что не жалуются. Подмастерье Гектор пусть воск не пробует, ему это говорили уже дважды. Гектор, это я пишу тебе лично: твоя мать просила за тобой приглядывать, а ты мне очень усложняешь дело."},{"id":"cellar_018","kind":"note","title":"Записка в щели","text":"Милая соседка, вашим вторым яйцом наелись все пятеро и ещё оставили на завтра. Сегодня я нашла в щели третье, побольше, и оно было тёплое. Щель за эту неделю стала шире, иначе как бы оно пролезло, зато теперь я могу передать вам пирог с луком и шарф, у вас там наверняка зябко. Шарф старый, не обижайтесь, его вязала ещё моя мать. Мне приятно, что у меня есть вы. Гвен.","chain":"salt_loan","part":3},{"id":"cellar_019","kind":"note","title":"Из дневника","text":"Сегодня мне исполнилось тринадцать, и тётя подарила мне напёрсток. На рынке Джон Арден смотрел на меня, а может быть, на морковь у меня за спиной. Я потом нарочно ходила проверить, и морковь там правда лежала. Но я всё равно решила, что смотрел он на меня, а морковь пускай думает что хочет."},{"id":"cellar_020","kind":"note","title":"Просьба соседям","text":"Соседи, кто взял лестницу со двора Пайков, верните её, пожалуйста. Погреб у нас без ступеней, и наш сын сидит там уже второй день. Хлеб мы спускаем ему на бечёвке, а самого его на ней не вытащишь, парень он крупный. Он кричит снизу, что можно не спешить, потому что там тихо и никто не заставляет колоть дрова. Мать извелась, а отец говорит, что давно не слышал от него столько слов подряд. Марта Пайк."},{"id":"cellar_021","kind":"note","title":"Договор","text":"Мы, Стэнли Рот и тёща его Берта, договорились при свидетеле о следующем. Она больше не заходит в мастерскую, а он не поёт за столом. Оба признают, что друг друга не выносят, и оба обещают не огорчать Молли, которую любят одну на двоих. Свидетель просит в другой раз его не звать, он ещё от прошлого договора не отошёл."},{"id":"cellar_022","kind":"note","title":"Наряд подмастерью","text":"Перси, поставь Хобарту третий замок, у самого порога, ниже ставить уже некуда, так ему и скажи. Дверь открывать он не велел, поэтому работай с этой стороны. Если изнутри тебя попросят подать инструмент, не подавай и не отвечай, кто бы ни просил, хоть бы и голосом его жены. Я за тебя боюсь, мальчик. Клещи у нас одни, и ты у меня тоже один.","chain":"hobart_locks","part":3},{"id":"cellar_023","kind":"note","title":"Книга повитухи","text":"Роды у Мэгги Дин прошли за четыре часа с небольшим, мальчик родился здоровый, и я, как всегда, расплакалась. Плату взяла курицей. Мэгги просит записать, что, пока она кричала, в подвале кто-то пел колыбельную. Я спускалась туда с лампой и никого не нашла. Записала, как она просила, за сорок лет я научилась не спорить с роженицами. Курица несётся плохо."},{"id":"cellar_024","kind":"note","title":"Записка у порога","text":"Госпожа Ив, я оставляю пирог у двери, вы уже неделю мне не открываете. Прошлый противень я забрала, он был вылизан дочиста, хотя раньше вы всегда оставляли корки. Вы здоровы? Утром я стучала и слышала, как кто-то отходит от двери на цыпочках, и отходил он очень долго, а у вас ведь всего одна комната. Откройте мне, пожалуйста. Мы с вами тридцать лет ругаемся через забор, и я ещё не закончила."},{"id":"cellar_025","kind":"note","title":"Перепись двора","text":"В доме Хоука живут муж, жена, трое детей, тёща и козёл, причём тёща просит записать козла последним. В доме Броков живут муж, жена и двое детей. Броки говорят, что в подвале у них живёт ещё один, а кем он им приходится, сказать не могут. Хозяйка каждый вечер ставит ему у люка тарелку, и утром тарелка пустая. Подать за него я брать не стал. Кто ест и никому не мешает, тот, по-моему, уже родственник."},{"id":"cellar_026","kind":"note","title":"Табличка на лестнице","text":"Детям спускаться только со взрослыми. Взрослым только вдвоём. Вдвоём только днём. Днём у нас работа, так что сидите наверху, дорогие мои, мне так спокойнее. Ваша бабушка."},{"id":"cellar_027","kind":"note","title":"Долговая книга","text":"Уилкинс должен мне три монеты. Вдова Нэш должна одну, и я её об этом не спрашиваю. Мельник должен шесть, с него надо спрашивать дважды. Кузен Арчи взял одиннадцать и уехал. Кузен Арчи вернулся и занял ещё четыре. Это я сам себе пишу: больше ему не давать. Правда, родни у меня, кроме него, не осталось, и обнимает он всегда так, что я сам лезу за кошельком."},{"id":"cellar_028","kind":"note","title":"Рекомендация","text":"Дорис Кин служила у нас четыре года, и мы расстаёмся с ней со слезами. Она честна, встаёт рано и хорошо управляется с бельём, а наш младший при ней перестал бояться темноты. За всё это время она ни разу не спустилась в подвал, и за это мы ей особенно признательны. Отпускаем её с жалованьем за месяц и просим новых хозяев её беречь. Госпожа Уайт."},{"id":"cellar_029","kind":"note","title":"Записка в щели","text":"Пирог вы взяли, а шарф вернули вдвое длиннее. Вяжете вы ровнее моей матери, и нитка у вас серая, хорошая, только немного липнет к пальцам. Простите моего мужа, он всё-таки замазал щель глиной и всю неделю ходит сам не свой. Мне вас не хватает, правда. Сегодня утром у нас на столе лежало ещё одно яйцо, хотя щели больше нет, и дети просят яичницу. Записку кладу у стены наудачу. Гвен.","chain":"salt_loan","part":4},{"id":"cellar_030","kind":"note","title":"Список приданого","text":"Приданое Энни Брук, записываю сам, чтобы сватья потом не говорила лишнего. Даём две простыни, одна с дырой, зато вышитая. Даём четыре ложки и бабушкин стул, за который Энни держалась, когда училась ходить. Корова остаётся у нас, про корову разговора не было. А дочь мы отдаём самую лучшую, и пусть ваш сын это запомнит."},{"id":"cellar_031","kind":"note","title":"Каракули","text":"ханна дура. сказала что паук был с тарелку. а я видел он был с таз. ханна его вобще не видела потому что зажмурилась она трусиха. я видел и не убежал. потом убежал. но ханну я сначала утащил за руку так что пускай спасибо скажет"},{"id":"cellar_032","kind":"note","title":"Совет хозяйке","text":"Милая Сара, ты теперь хозяйка в своём доме, так что вот тебе мой совет. Пауков не гони, бери стаканом, подсунь снизу лист бумаги, вынеси во двор и скажи спасибо. Твоя бабка их не терпела, и мухи у неё ели хлеб прямо со стола. Последнего паука из подвала я выносила сама, двумя руками, и спасибо сказала два раза. Приезжай к нам на праздник, я по тебе скучаю. Мама."},{"id":"cellar_033","kind":"note","title":"Накладная","text":"Госпоже Ройс доставлены бочонок масла, два куля муки и ящик свечей. Я сгрузил всё у люка, как она велела, а сама она ко мне так и не вышла. Накладную я спустил в люк на верёвочке, и она вернулась с подписью: восемь крестиков по кругу. Раньше госпожа Ройс всегда выносила мне молока и спрашивала про мою Эмму. Я, возчик Дэйл, за такую подпись не отвечаю и ездить туда больше не стану, хотя мне её жаль."},{"id":"cellar_034","kind":"note","title":"Наряд подмастерью","text":"Перси, я сам ходил к Хобарту. Все три замка лежат на верхней ступеньке, снятые чисто, и винты сложены в плошку. Такой работы я от тебя шесть лет жду. Дома никого нет, дверь стоит настежь. Я позвал его, как звал в детстве, и никто мне не откликнулся. Счёт отнеси его сестре на Рыбную, только денег с неё не требуй. Скажи, что я зайду сам и посижу с ней.","chain":"hobart_locks","part":4},{"id":"cellar_035","kind":"note","title":"Записка деду","text":"Дедушка, ты уже поел, не ищи. Суп стоит в печи, это на завтра. Ты опять спрашивал про бабушку: она умерла весной, мой хороший, я знаю, как больно тебе это слышать каждый раз. В подвале её нет, не ходи туда её звать, пожалуйста. Твои очки висят на гвозде у окна. Я вернусь к обеду, посижу с тобой, и мы вспомним, как она ругала тебя за сапоги. Твоя Кейт."},{"id":"cellar_036","kind":"note","title":"Записка на столе","text":"Нэнси, я пошла вниз за углём. Если не вернусь к ужину, сними суп с огня и покорми собаку. За мной без надобности не ходи, а если всё-таки пойдёшь, лишнего угля не бери, он в этом году дорогой. Я, конечно, вернусь. Твой отец за двадцать шесть лет так и не сумел от меня отделаться."},{"id":"cellar_037","kind":"note","title":"Решение совета","text":"Совет постановил считать подвалы под Старой и Мельничной улицами общими, пока не выяснится, кто их копал. Никто из домовладельцев копать не сознался, а записей об этом нет. Подать за подвалы совет будет брать равными долями с первого числа. Господин Дэвис просит внести в протокол, что подвала у него нет и никогда не было. Совет вынужден сообщить господину Дэвису, что подвал у него есть, и советует посмотреть под кухней."},{"id":"cellar_038","kind":"note","title":"Дела на неделю","text":"Починить корыто. Поговорить с Маргарет. Наточить косу. Корыто я починил. Заодно вставил раму на кухне, хотя её в списке не было. Поговорить с Маргарет. Косу наточил. Прибил полку, о которой она просила ещё в прошлом году. Поговорить с Маргарет. Сказать ей, что я был неправ. Поговорить с Маргарет."},{"id":"cellar_039","kind":"note","title":"Записи хозяйки","text":"Масло в погребе опять потекло. Двадцать лет оно у меня держалось до самой жары, а с этой осени внизу тепло, как в хлеву. Я перенесла масло в сени. Потом положила ладонь на пол, и пол был тёплый, будто под ним кто-то лежит и дышит. Молоко я тоже перенесла. Матери про это писать не буду, она и так за меня плохо спит."},{"id":"cellar_040","kind":"note","title":"Молитва","text":"Святой Бертрам, хранитель кладовых, пошли мне мужа, который закрывает за собой дверь. Если такого не осталось, пошли хоть дверь, что закрывается сама. И пусть в этом году не прокиснет молоко. Мой нынешний дверь не закрывает, зато обнимает меня перед сном, так что ты на него не сердись, это я просто ворчу. Аминь."},{"id":"cellar_041","kind":"secret","title":"Записка в кирпиче","text":"Сынок, вчера я выбил кирпич из стены подвала, а на обороте нацарапано: кто будет строить дальше, оставь тут окно. Окна, как видишь, никто не оставил. Я приписал ниже то же самое и вставил кирпич на место. Раствор у нас хороший, ты его не тронешь. Но когда придёт твой черёд класть стены, вспомни отца и оставь окно. Кому-то внизу будет приятно."},{"id":"cellar_042","kind":"secret","title":"Письмо жильцам","text":"Тем, кто построит над нами. Подвал у нас сухой, если не трогать дальний угол. Тяга в печи хорошая. Соседи справа шумные, но вас это уже не коснётся. Ключ от погреба лежит под третьей ступенькой. Мы нашли такой же ключ, когда строились, и такое же письмо, и в первую ночь оно нас очень утешило. Живите тут хорошо, не ссорьтесь из-за пустяков и напишите следующим. Джон и Анна."},{"id":"cellar_043","kind":"secret","title":"Записка сапожника","text":"Записываю, чтобы внуки мне поверили. Старик, который смотрит за огнём на площади, принёс мне чинить башмак и сказал, что дед мой тоже плохо завязывал шнурки и всегда снашивал левый первым. Старику с виду лет шестьдесят, а дед умер, когда площадь ещё не мостили. Левый он и правда снашивал, мне мать рассказывала. Я так обрадовался, что кто-то ещё помнит деда, что взял со старика полцены."},{"id":"cellar_044","kind":"secret","title":"Наказ матери","text":"Дочка, моя мать велела мне, если придёт беда, взять из костра на площади уголёк и нести наверх. Куда наверх, она не сказала, потому что сама не знала, ей так велела её мать. Я пишу это, чтобы ты понимала, зачем за ларём стоит горшок. Уголь в нём я меняю раз в неделю, идти до площади недалеко. Когда меня не станет, меняй его ты и не смейся над старухами. Мы боялись за вас."},{"id":"cellar_045","kind":"secret","title":"Правила обмена","text":"Кто берёт из этой ниши вещь, тот кладёт свою. Я взял гребень и положил свисток. Я взял свисток и положил нож. Я взял нож и положил напёрсток. А я взяла напёрсток, и положить мне нечего, поэтому оставляю эту записку. Простите меня, добрые люди, я шью дочке свадебное платье, а свой напёрсток потеряла."},{"id":"cellar_046","kind":"secret","title":"Мой клад","text":"это мой клад. тут синие стекло. зуб мой. зуб не мой я его нашёл. перо. кто возмёт тому будет плохо. если это ханна то ей будет хуже всех. ханна если это ты то перо можешь взять ты его хотела"},{"id":"cellar_047","kind":"secret","title":"Тайная запись","text":"Я вышла за Джорджа из-за крыши, потому что кто-то должен был её чинить. С тех пор прошло девять лет. Крыша давно целая, а он каждую весну лезет её проверять и зовёт меня держать лестницу. Я хожу и держу. Ему я этого никогда не скажу, но если он однажды перестанет звать, я сама проломлю в ней дыру."},{"id":"cellar_048","kind":"secret","title":"Запись плотника","text":"Мы углубляли погреб на два локтя и пробили чужой потолок. Внизу оказалась кухня, стол там накрыт на двоих, и ложки рыжие от ржавчины. Жена спустилась и вытерла со стола пыль, сказала, что так приличнее, вдруг они вернутся. Я хотел ей что-то ответить и не смог. Доски мы положили обратно, а погреб оставили как был, вина у нас немного."},{"id":"cellar_049","kind":"secret","title":"Считалка","text":"Записала, что поют дети у колодца, когда прыгают через верёвку: «Дом на доме, дом на доме, пятый спит, шестой в соломе. Кто внизу, тот подождёт, кто вверху, тот упадёт». Я спросила у старой Бесси, откуда это, и она сказала, что пели всегда, ей пела мать, а матери бабка. Что это за дома, никто не знает. А я теперь не могу спокойно слушать, пока моя младшая прыгает там со всеми."},{"id":"cellar_050","kind":"secret","title":"Страница дневника","text":"Староста вывесил объявление: нужен кто-нибудь, кто согласен спуститься, плата хорошая. Пошёл мой Адриан с мельницы. Он вернулся через неделю, худой, и всё говорил про какие-то улицы внизу. Платить ему отказались, потому что договаривались только про спуск. Я варю ему бульон, а он сидит и смотрит в пол. Вчера вывесили новое такое же объявление, и плату подняли на монету. Он уже ходил его читать, и я спрятала его сапоги."},{"id":"cellar_051","kind":"boss","title":"Письмо дочери","text":"Мама, я пишу на обороте счёта, другой бумаги нет. Ты опять приходила ночью и укрывала нас. Ноги у тебя теперь так тихо стучат по балкам, что младший думает, это дождь. Он спрашивает, когда мы выйдем. Я говорю, когда ты закончишь плести одеяло.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_052","kind":"boss","title":"Жалоба соседке","text":"Уважаемая соседка! Ваше одеяло снова приползло к нам через отдушину, дошло до полки с вареньем и обвило её. Я его обрезала, а к утру оно срослось. Работа прекрасная, слов нет, и я помню, как вы сидели с моей Хильдой, когда она болела. Но у нас своего места мало, а у вас столько детей. Заберите его, пожалуйста, или скажите, сколько его ещё будет. И зайдите ко мне, я давно вас не видела.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_053","kind":"boss","title":"Счёт за шерсть","text":"Лавка Хемминга, счёт матери с Прядильного двора. За серую шерсть, двенадцать мотков. За серую шерсть, сорок мотков. За шерсть, сколько её у меня было. За осень вы не заплатили, и я не прошу, дорогая, я ведь знаю, сколько у вас ртов. Только заказов от вас больше не приходит. Вторую половину этого счёта забрала ваша девочка, сказала, что ей нужна бумага. Она очень худая, я дала ей хлеба.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_054","kind":"boss","title":"Записи сетчика","text":"Я чиню сети тридцать лет. Вчера соседка, мать восьмерых, принесла мне на пробу нитку. Узел на ней не нужен, нить сама липнет к нити, а нож об неё тупится. Я спросил, где она берёт такую шерсть. Она сказала, что своя, и спрятала руки под передник. Мы знакомы с детства, и раньше она ничего от меня не прятала. Заказал у неё сорок локтей для лодки Харпера, цена хорошая, и детям её будет на хлеб.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_055","kind":"boss","title":"Записка младшего","text":"роб велел писать каждый день чтобы я не разучился и написать что я не боюсь. я не боюсь. мама принесла нам поесть завёрнутое в одеяло. это можно есть только я не знаю что это. лотти говорит не спрашывай. дождь опять ходит по балкам. я знаю что это мама. лотти думает я не знаю а я не говорю чтобы она не плакала","boss":"boss_spider","floors":[1,2]},{"id":"cellar_056","kind":"boss","title":"Правила дома","text":"Пишу я, Роб, потому что я теперь старший. Одеяло не поднимайте. Если стучит наверху, это мама. Если стучит внизу, будите меня. Про её ноги при ней не говорите, она от этого расстраивается. Воду сегодня делит Лотти, завтра Дэви, и младшему всегда давайте первому. При ней не ссоримся и не плачем. Она нас кормит и укрывает, и она всё ещё наша мама.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_057","kind":"boss","title":"Письмо сестре","text":"Дорогая Эвелин, ты спрашивала про ту многодетную с нашего двора. Детей её давно никто не видит, и я за них тревожусь. На той неделе мой Джем уснул раскрытым, окно было открыто, а утром он лежал укрытый по самую шею, и укрыт чем-то серым, ровным, у нас такого сроду не водилось. Муж говорит, что это не он. Я сперва испугалась, а потом потрогала: одеяло тёплое. Мы его оставили. Кто-то же пожалел моего мальчика.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_058","kind":"boss","title":"Письмо брата","text":"Лотти, сестрёнка, я устроился у шорника в Нижнем Форде, и тут кормят. Шлю три монеты, отдай их маме и скажи, что одеяло дошло. Оно мне велико, им можно укрыть лошадь. Я мерил его осенью и мерил вчера, и оно выросло на локоть. Всё думаю, как мама плела его ночами и не давала мне посмотреть. Почему вы не пишете? Напиши мне хоть строчку, мне без вас плохо. Твой брат Уолтер.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_059","kind":"note","title":"Черта в погребе","text":"Оливер, раз уж мы теперь не разговариваем, я тебе пишу. После смерти отца мы поделили погреб пополам, и я провёл мелом черту от двери до дальней стены, всё честно, при свидетелях. Твой лук лежит на моей стороне на целую ладонь, так что убери его до воскресенья. Передай Дженни, что её пирог я съел исключительно из уважения к ней, к тебе это не относится. Седрик.","chain":"chalk_line","part":1},{"id":"cellar_060","kind":"note","title":"Письмо Марион","text":"Марион, мне надо кому-то рассказать. Зимой мне негде сушить бельё, кроме подвала, и вот уже месяц я нахожу его по утрам сложенным, и сложено оно ровнее, чем складываю я. Мой Гил тут ни при чём, он без меня и ложку свою не найдёт. Надо бы мне испугаться, я знаю. Но у меня четверо детей и больная спина, и вчера я оставила внизу ещё и штопку. Поцелуй за меня маму."},{"id":"cellar_061","kind":"note","title":"Объявление у булочной","text":"Ищу того, кто умеет читать вслух и не торопится. Глаза у меня стали плохие. Читать надо письма моего покойного мужа, их девятнадцать. Я знаю их наизусть, но мне хочется услышать их так, как в первый раз, когда я ещё не знала, что там дальше. Платить могу яблоками. Голос пусть будет не слишком красивый, у него был такой же. Спросить вдову Карр на Рыбной, дом с зелёной ставней."},{"id":"cellar_062","kind":"note","title":"Книга писаря","text":"Записываю для памяти. Нед Кобб, подмастерье пекаря, заплатил монету за письмо к Полли Вейн. Он сказал мне: пиши, что я её видел и что она ничего. Я написал так: с тех пор как я увидел вас у колодца, у меня подгорает хлеб. Это чистая правда, я сам его покупаю. Полли читать не умеет, поэтому вечером я пойду и прочту ей вслух, за это ещё полмонеты. Такого приятного заказа у меня не было с тех пор, как умерла моя Агнес.","chain":"scribe_letters","part":1},{"id":"cellar_063","kind":"note","title":"Школьное сочинение","text":"Кем я хочу стать. Я хочу стать как мой дядя Родерик. Дядя Родерик не работает, он уже давно ждёт хорошего случая, и всё равно обедает у нас каждый день. Мама говорит, что он позор семьи, а потом кладёт ему самый большой кусок. Он научил меня свистеть двумя пальцами. Мастер Оукс, вы велели писать правду. Приписка учителя: написано грязно, мальчик. Передай дяде, что он должен мне за пиво."},{"id":"cellar_064","kind":"note","title":"Книга портного","text":"Мерки господина Дрейка я снимаю двадцать лет. Живот у него рос вместе с делами, а жена всякий раз стояла рядом и требовала оставить в шве запас на её пироги. В этом году он пришёл один и попросил ушить сюртук на две ладони. Я ушил и денег с него не взял. Он постоял у двери и спросил, нельзя ли всё-таки оставить запас. Я распорол и оставил."},{"id":"cellar_065","kind":"note","title":"Письмо о закваске","text":"Нелл, доченька, вот тебе горшок с закваской, неси его ровно и не тряси на телеге. На этой закваске пекла ещё моя мать, и ты на ней выросла. Корми её раз в день горстью муки и держи в тепле, а крышку не прижимай, ей надо дышать. Хлеб в городе покупать не вздумай, там в него кладут мел. Напиши мне, как тебя приняли в новом доме и не обижает ли тебя свекровь. Я уже скучаю. Мама.","chain":"sourdough","part":1},{"id":"cellar_066","kind":"note","title":"Рецепт пирога","text":"Элинор, ты двенадцать лет спрашиваешь, почему твой пирог выходит хуже моего, хотя рецепт я тебе дала. Дала, да не весь. В тесто надо класть щепоть мускатного ореха. Я тебе об этом не написала, и мне все эти годы было очень приятно. Теперь я болею, а сыну моему надо есть как следует и после меня. Ты ему хорошая жена, только не вздумай рассказывать об этом на кухне у Бриджет. Твоя свекровь."},{"id":"cellar_067","kind":"note","title":"Письмо кузине","text":"Кузина Тэсс, ты спрашивала, что у нас нового. На Рыночной площади открылась трещина, шириной уже в две ладони. Совет обнёс её верёвкой, и теперь сюда ходят смотреть из трёх приходов. Пекарь поставил рядом лоток, а мой Барни берёт монету за то, чтобы бросить вниз камешек и послушать. Стука пока никто не услышал, зато Барни купил мне новый чепец. Приезжай скорее, пока есть на что посмотреть, и детей привози."},{"id":"cellar_068","kind":"note","title":"Записка Мэри","text":"Мэри, я всё перемерил. На телегу входят мука, постели, дети и куры, а сундук твоей матери не входит, как его ни ставь, и вчера я сказал тебе об этом слишком громко. Прости меня. Я пойду пешком и понесу его на спине, до Форда всего два дня пути, а ты садись на моё место и не вздумай идти рядом. Скобу на крышке надо подтянуть, я сделаю это с утра."},{"id":"cellar_069","kind":"note","title":"Черта в погребе","text":"Седрик, мой лук лежит там, где лежал, это твоя черта ползёт. Вчера я видел своими глазами, что она сдвинулась в мою сторону на две ладони. Я знаю, что ты ходишь туда по ночам и подтираешь её, ты и в детстве жульничал в шашки. Отец бы тебе этого не простил. Дженни спрашивает, с чем ты хочешь следующий пирог, и я тут совершенно ни при чём. Оливер.","chain":"chalk_line","part":2},{"id":"cellar_070","kind":"note","title":"Записка в хлебе","text":"Барт, я запекла записку в хлеб, потому что стража меня к тебе не пускает. Напильника в хлебе нет, не ищи и побереги зубы. Сидеть тебе всего две ночи. Соседям я сказала, что ты вступился за мою честь, хотя мы оба знаем, что подрался ты из-за ставки на гусиных бегах. Гусь твой, кстати, пришёл последним. Поешь и выходи поскорее, дрова кончаются, а я не привыкла засыпать без твоего храпа. Лиззи."},{"id":"cellar_071","kind":"note","title":"Цены зубодёра","text":"Вырвать зуб стоит одну монету, и две, если перед этим мне приходится бегать за вами по улице. Детям я рву бесплатно, если они не кусаются. Руку вам держит моя жена Мод, и за это она ничего не берёт. Рука у неё тёплая, и каждому она говорит, что уже почти всё. Говорит она это с самого начала. Мне она сказала то же самое в день нашей свадьбы, и с тех пор прошло тридцать лет. Мастер Клемент."},{"id":"cellar_072","kind":"note","title":"Журнал сторожа","text":"В полночь я прошёл Кузнечный ряд, всё спокойно, у вдовы Мур горит свет. В час прошёл ещё раз, всё спокойно, свет горит. В два часа вдова Мур вышла на крыльцо и сказала, что я топаю у неё под окнами, а потом вынесла мне горячего вина и постояла со мной, пока я пил. Капитан, эту строку прошу вычеркнуть. В три часа я прошёл ряд ещё раз, хотя обход у меня кончается в два."},{"id":"cellar_073","kind":"note","title":"Книга писаря","text":"Полли Вейн заплатила за ответ Неду Коббу. Она велела написать, что он дурак, но пусть приходит в воскресенье. Я написал: ваше письмо я ношу с собой, приходите в воскресенье, если не боитесь моей матери. Нед читать тоже не умеет, и я прочёл ему это в пекарне. Он сел прямо на мешок с мукой и попросил прочесть ещё раз. Я прочёл три раза и денег за это не взял, хотя полагалось.","chain":"scribe_letters","part":2},{"id":"cellar_074","kind":"note","title":"Письмо с угрозой","text":"бекки. твоя кукла у меня. хочеш увидить её опять положи под лестницу пряник и никаму не гавари. пряник нужен большой. кукла просила передать что с ней харашо обращаюца и что она по тебе скучает. это пишет чесный разбойник а не я. эдди"},{"id":"cellar_075","kind":"note","title":"Черновик проповеди","text":"В воскресенье сказать о гордыне. Тут посмотреть на господина Лоуэлла, но недолго, потому что он платит за крышу. Потом сказать о любви к ближнему, это всегда нравится. Вдову Фелл не упоминать, она заплачет в первом ряду, и у меня потом не найдётся слов. Говорить надо коротко, в прошлый раз Мэри Хиггс захрапела на втором псалме, а она моя родная сестра, и я не могу ругать её с кафедры. Отругаю за обедом."},{"id":"cellar_076","kind":"note","title":"Опись кладовой","text":"Эмили, я пересчитала всё в кладовой, чтобы ты знала, что брать на зиму. Огурцов у нас девять банок, грибов шесть, груш на меду четыре. Сливовое варенье стоит одной банкой на верхней полке, за солью. Его варил твой отец в свой последний август, и оно, наверное, засахарилось. Эту банку не открывать. Я знаю, что дети туда лазят, поэтому скажи им, что там горчица."},{"id":"cellar_077","kind":"note","title":"Письмо о закваске","text":"Мама, горшок я довезла. Свекровь меня не обижает, только всё время нюхает мой хлеб и молчит. Скажи, закваска всегда так растёт? Я поставила её в погреб, там теплее, и за неделю она подняла крышку, а потом съела полотенце, которым я её накрыла. Кормлю я её, как ты велела. Рис смеётся и говорит, что я принесла в приданое единственную родственницу, которая ест больше него. Хлеб выходит лучше твоего, ты уж не обижайся.","chain":"sourdough","part":2},{"id":"cellar_078","kind":"note","title":"Записка на горшке","text":"Джек, мёд я теперь меряю ниткой. Утром нитка доходила до царапины, а к обеду уже не доходит. Кроме тебя, в этом доме мёд никто не любит, а ложки у собаки нет. Сержусь я мало, зато всё вижу. Ложку потом мой, сынок, ты её облизываешь и кладёшь обратно, а мне приходится отскребать. За этим горшком на полке стоит второй, поменьше, я отставила его для тебя."},{"id":"cellar_079","kind":"note","title":"Записка дворецкого","text":"Господин Уэллс, я должен вам сознаться. Восемь лет я доливаю воду в вашу бочку, потому что лекарь сказал, что вино вас убьёт, а вы мне как отец. Вчера кухарка рассказала мне, что вы и сами доливаете туда воду, чтобы поменьше пил я. По моим подсчётам, вина в бочке не осталось совсем. Позвольте мне открыть новую, сэр, и выпьем её вместе, как в ту ночь, когда родился ваш Ричард. Ваш Бейтс."},{"id":"cellar_080","kind":"note","title":"Записи о мыши","text":"Поставил новую ловушку, девятую по счёту. Мышь съела сало и ушла, а ловушка так и осталась взведённой, и я до сих пор не понимаю, как она это делает. Сноха прислала мне кота, кот поглядел на всё это и вернулся к снохе. Дети мои разъехались, и по вечерам в доме слышно только её. Сегодня я положил сало без ловушки, пускай поест спокойно, а ловушку поставлю завтра. Завтра ярмарка, так что поставлю потом."},{"id":"cellar_081","kind":"note","title":"Черта в погребе","text":"Оливер, клянусь памятью отца, я черту не трогал. Позавчера я вбил вдоль неё гвозди, а сегодня она от них ушла. Теперь она идёт дугой и огибает старый люк в углу, как будто кто-то рисовал её заново и не захотел подходить к нему близко. У меня такой ровной руки нет, ты сам мне это говорил, когда мы белили отцу забор. Спустись и посмотри, только один не ходи, позови меня. Седрик.","chain":"chalk_line","part":3},{"id":"cellar_082","kind":"note","title":"Письмо брату","text":"Дик, ты будешь смеяться. Из подпола у меня тянет жареным луком, хотя я лука не жарю уже неделю. Вчера пахло яблочными оладьями с корицей, точно такими, какие пекла наша мать, и я просидел на ступеньке целый час. Потом спустился посмотреть, и там не оказалось ничего, кроме кирпича и холодной земли. Напиши мне, помнишь ли ты про корицу или мне одному это кажется. Приезжай, мне тут плохо одному."},{"id":"cellar_083","kind":"note","title":"Записка няни","text":"Госпожа Лэнг, простите, что пишу вам о таком. Ваш Сэм всю неделю кричит в кладовой и слушает эхо, и я радовалась, потому что он хотя бы не лез мне под руку. Сегодня я пошла послушать сама. Он крикнул: я сегодня съел всю кашу. Эхо ответило ему: умница. Я увела его наверх, дала хлеба с мёдом и заперла дверь на щеколду. Мальчик он хороший, плакал недолго. Скажите, пожалуйста, что мне ему отвечать, он спрашивает, когда опять можно."},{"id":"cellar_084","kind":"note","title":"Спор при свидетеле","text":"Я, Мартин Гейл, спорю с Дэном Хиллом на бочонок эля, что просижу до утра в подвале кожевни без свечи. Свидетель Хэл Уик. Приписка свидетеля: Мартин просидел и спор выиграл. Утром он вышел, сам купил Дэну бочонок и обнял его при всех, потом пошёл домой и помирился с отцом, с которым шесть лет не разговаривал. Что там было, он не рассказывает. Дэн теперь тоже хочет попробовать, но мать его не пускает."},{"id":"cellar_085","kind":"note","title":"Книга писаря","text":"Сегодня я написал сорок второе письмо. Нед больше не говорит мне, что писать, а только просит сделать как в прошлый раз, только лучше. Полли просит о том же самом. Выходит, я второй год пишу письма сам себе и сам себе на них отвечаю, и вчера я поймал себя на том, что жду ответа. Сестра посмотрела, как я сижу над бумагой, ничего не сказала, налила мне супу и погладила по голове, чего не делала лет с десяти.","chain":"scribe_letters","part":3},{"id":"cellar_086","kind":"note","title":"Подсказка жениху","text":"Тимоти, завтра ты идёшь к моему отцу. Он будет молчать, и это значит, что всё хорошо. Если спросит, сколько ты зарабатываешь, скажи правду, он всё равно уже узнал. Рыбу хвали, он ловил её сам. На столе будут стоять две миски, хотя мама умерла зимой. Вторую не трогай и не смотри на неё долго. Я тебя очень люблю, и причешись, пожалуйста, хоть раз в жизни. Твоя Клара."},{"id":"cellar_087","kind":"note","title":"Письмо Кэти","text":"Кэти, денег у меня нет, и я говорю тебе об этом в последний раз. Твой муж мог бы наконец найти себе дело, а ты могла бы перестать его защищать, но ты всегда была упрямая, как отец. Монеты в этом платке пойдут малышке на башмаки. Назад мне их не присылай, потому что я тебе ничего не посылал. Платок мамин, его верни. Твой брат Ллойд."},{"id":"cellar_088","kind":"note","title":"Первое письмо","text":"жена я научылся писать. мне шесдесят два. сорок лет ты читала мне вслух что там написано а я кивал и думал что ты не знаеш. ты знала я теперь понял. учитель велит написать про погоду а я сперва напишу что хотел. ты красивая. вот написал. буквы идут трудно. погода сегодня сырая."},{"id":"cellar_089","kind":"note","title":"Поля романа","text":"Графиня дура, и я бы на её месте уехала ещё в третьей главе. Ниже: Сама ты дура, Марта, у неё три имения. Ниже: Дочитаю в среду и отдам Сильвии, только не рассказывайте мне, чем всё кончится. Ниже: Граф умрёт, целую, Сильвия. Ниже: Сильвия, я с тобой больше не разговариваю. Через две страницы: Прости меня за графа, милая, я напекла булок, приходи в четверг."},{"id":"cellar_090","kind":"note","title":"Запись пасечника","text":"Мать каждый вечер спрашивала меня, как прошёл день, и слушала, даже когда я врал. Теперь спрашивать некому. Сегодня я пошёл осмотреть ульи и сам не заметил, как начал им рассказывать, и неловко мне было стоять и говорить вслух. Рассказал, что Гарет уехал и не пишет и что крыша течёт там же, где текла при отце. Сказал и о том, что был, наверное, плохим сыном. Простоял там до темноты. Пчёлы гудели ровно, как она, когда вязала. К холодам надо будет утеплить ульи."},{"id":"cellar_091","kind":"note","title":"Письмо о закваске","text":"Мама, спасибо за совет, но бочка тоже стала мала. Мы с Рисом переставили закваску в большой ларь и отодвинули его в дальний угол, иначе к полкам не подойти. Хлеба хватает всей улице. Свекровь попросила у меня кусочек на развод и назвала меня дочкой, и я ревела в передник. Рис теперь спускается туда с лопатой. Вчера он сказал, что она поднялась на нижнюю ступеньку и вид у неё довольный. Приезжай к празднику, я соскучилась, и привези муки, сколько увезёшь.","chain":"sourdough","part":3},{"id":"cellar_092","kind":"note","title":"Записка Элле","text":"Элла, ты спишь, поэтому я пишу. Ты хотела назвать мальчика Эдмундом, а я сказал, что так звали осла у моего дяди. Осёл был хороший, назовём Эдмундом. Повитуха говорит, что ты потеряла много крови, но сегодня щёки у тебя уже не такие белые, а мальчика кормит жена мельника, и он ест за двоих. Проснись и скажи мне, что я дурак. Я сижу рядом и очень этого жду."},{"id":"cellar_093","kind":"note","title":"Объявление о гробе","text":"Продаётся гроб, дубовый, отличной работы. Я купил его год назад по совету лекаря Мэллори, который дал мне сроку до первых холодов. С тех пор лекарь Мэллори умер, а я нет. Жена держит в гробу лук, говорит, что это лучшая вещь, которую я купил за всю жизнь, и продавать его не даёт, поэтому приходите, пока она на рынке. Цена договорная."},{"id":"cellar_094","kind":"note","title":"Забытые вещи","text":"В «Синем быке» за этот год постояльцы забыли два ножа, плащ, один зуб в платочке и жену господина Прайса. Господин Прайс вернулся за ней на третий день, и она не сразу к нему вышла. За эти дни она перебрала нам всю кладовую и научила нашу Дору штопать пятку, так что Дора просит её оставить. Зуб отдадим любому, кто сумеет описать платочек."},{"id":"cellar_095","kind":"note","title":"Черта в погребе","text":"Оливер, черта дошла до лестницы и поднялась на первую ступеньку. Я стёр её мокрой тряпкой, а утром она опять была там. Мне теперь всё равно, где лежит лук, забери и свой, и мой. Спускаться туда я больше не буду, и ты не ходи, у тебя дети. Приходите к нам в воскресенье ужинать, все вместе. Я шесть лет злился на тебя из-за отцовской пилы, а пилу вчера нашёл, она висела за дверью. Пусть Дженни принесёт тот, с яблоками.","chain":"chalk_line","part":4},{"id":"cellar_096","kind":"note","title":"Расписка","text":"Я, Флора Дин, должна Ричарду Бейлу один танец. Сорок лет назад, на празднике урожая, я сказала ему, что подвернула ногу. Нога у меня была целая, я просто ждала другого. Другой женился на Энн Фолк, а Ричард с тех пор ходит на все праздники и встаёт у стены. Рабочих ног у нас с тобой теперь на двоих осталось три, Ричард, но долг я заплачу. Приходи в субботу, и палку свою возьми."},{"id":"cellar_097","kind":"note","title":"Книга писаря","text":"Полли и Нед женятся в субботу, и приглашения пишу я, на этот раз даром. Вчера она пришла расплатиться за последнее письмо и сказала: мастер Амос, читать я так и не выучилась, но, когда вы читаете, голос у вас меняется на тех местах, которые вы сочинили сами. Я не нашёлся, что ей ответить. Она велела мне сесть в субботу за их стол, рядом с её тёткой, и поесть как следует. Чернила надо купить к понедельнику.","chain":"scribe_letters","part":4},{"id":"cellar_098","kind":"note","title":"Завещание","text":"Завещаю следующее. Дом отходит моей дочери Элис, потому что это она за мной ходила. Сыну Генри я оставляю пилу и мои извинения, я был с ним слишком суров, он это знает, а сказать ему я так и не смог. Брату Фреду прощаю четыре монеты, которые он мне должен. Пусть перестанет переходить через улицу, как только меня увидит, теперь это уже ни к чему. Шапку отдайте сторожу, он давно на неё смотрит."},{"id":"cellar_099","kind":"secret","title":"Записка каменщика","text":"Брат, ты меня знаешь, я бы на работе пить не стал. Сегодня мы перевернули старый блок для порога, и с нижней стороны на нём стоит кривой лист. Такое клеймо ставлю только я, с пятнадцати лет, и левую прожилку делаю длиннее, чтобы никто не подделал. Там прожилка тоже длиннее. Камню на вид несколько сотен лет, он весь стёрт по краям. Я положил его обратно и ничего не сказал старшине. Приди посмотри, мне одному не по себе."},{"id":"cellar_100","kind":"secret","title":"Письмо землекопа","text":"Милая, мы копали сток на Мельничной и дошли до мостовой. Внизу идёт улица, и на углу висит табличка, а на ней написано: Мельничная. Там стоят дома, и на месте нашего дома тоже стоит дом, с таким же крыльцом, а на нижней ступеньке щербина с той самой стороны, где у нас. Заходить я не стал, и ты бы на моём месте не стала. Пока поднимался, я всё думал, кто у кого перенял. Поцелуй детей, вернусь к ужину."},{"id":"cellar_101","kind":"secret","title":"Записка о балке","text":"Хелен, балку для двери я взял из старого разбора, и ты не ругайся, она крепкая. На ней зарубки и имена, кто-то мерил детям рост: Мэй и Том, Мэй и Том, всё выше и выше. Последняя зарубка Мэй приходится мне по плечо, а Том кончается гораздо раньше. Я поставил балку так, чтобы их было видно и чтобы рядом нашлось место для нашей Эм. Вчера она встала к балке спиной и спросила, кто эта девочка, и я сказал, что подружка."},{"id":"cellar_102","kind":"secret","title":"Перевод надписи","text":"Сестра, только ты не будешь смеяться. Три года я разбирал плиту из-под старого колодца, ту, с буквами, каких теперь никто не пишет. Школа выдавала мне свечи, а я всем говорил, что это закон наших предков. Вчера я дочитал её до конца. Там написано: лавка закрыта, ушёл обедать, скоро вернусь. Школе я сказал, что работа продолжается. Он ведь так и не вернулся, и я с самого утра сижу и думаю об этом человеке."},{"id":"cellar_103","kind":"secret","title":"Записка на мешке","text":"Этот мешок зерна предназначен Элиасу Ренту с Нижней улицы или его наследникам. Мой прапрадед взял у него такой мешок взаймы, и расписка с тех пор переходит у нас от отца к сыну. Нижней улицы нет уже двести лет, соседи говорят, что она под нами, поэтому я спускаю мешок в самый глубокий погреб, какой сумел найти. Наша семья никому не оставалась должна, отец очень этим гордился. Если Элиас отзовётся, пишите в пекарню Хьюза."},{"id":"cellar_104","kind":"secret","title":"Слово ученику","text":"Эдгар, это передаётся только старшему ученику, и теперь я передаю это тебе. Заказчики думают, что дома у нас стоят крепко благодаря нашей кладке. На деле мы ставим стены прямо поверх чужих стен, которые лежат под землёй, и нашего труда там на ладонь. Кто их клал, я не знаю, и мой учитель тоже не знал. Заказчикам этого не говори, пусть гордятся своими домами. Углы ты кладёшь лучше меня, я давно хотел тебе это сказать."},{"id":"cellar_105","kind":"secret","title":"Записка в кубышке","text":"Нейл, твою кубышку под плитой я нашла ещё в тот год, когда ты начал копить на лодку. С тех пор я подкладываю туда монету всякий раз, как удаётся продать пряжу, и вот уже двадцать лет ты радуешься, что дело идёт так быстро. Там теперь хватит и на лодку, и на сеть. Записку я кладу на самое дно, чтобы ты нашёл её, когда всё пересчитаешь. Поплывём вместе, дурак ты мой. Плавать я не умею, так что лодку бери с бортами повыше."},{"id":"cellar_106","kind":"secret","title":"Записка Дэнни","text":"Дэнни, если ты опять прячешься здесь, то ты выиграл. Слышишь? Я сдаюсь. Я всем говорю, что лучше тебя никто не умеет прятаться. Оставляю тебе тут хлеб и твою шапку, потому что ночью холодно. Мы ищем тебя уже второй день, и мама совсем на тебя не сердится. Выходи, и я отдам тебе ножик, насовсем, и ещё тот синий камень. Твой брат Марк. Ниже кривыми буквами: я не прятался я заснул у дяди за бочками и меня не будили. хлеб я съел. ножик теперь мой ты сам написал."},{"id":"cellar_107","kind":"secret","title":"Записка в колодец","text":"Тем, кто внизу. Мой дед говорит, что наш город стоит у вас на крыше. Простите нас, пожалуйста, нас об этом никто не предупреждал. Мы стараемся не топать, особенно после ужина, но мой брат топает, он ещё маленький. Если у вас там темно, я могу бросать вам свечные огарки, у нас их много. Если вам что-нибудь нужно, постучите три раза, только не ночью, а то мама испугается. С уважением, Кэтрин, девять лет."},{"id":"cellar_108","kind":"secret","title":"Запись о снах","text":"Моя соседка Пру сказала, что ей снится один и тот же сон: будто она несёт наверх что-то тёплое и очень боится уронить. Мне снится то же самое. Мы спросили у мясника и у обеих сестёр Плам, и всем снится это, и никто не может сказать, что именно он несёт. Теперь мы здороваемся по утрам так: ну что, донесла? Пру пока не донесла, и я тоже, хотя вчера я уже видела дверь. Мужу я этого не рассказываю, он любит, когда я высыпаюсь."},{"id":"cellar_109","kind":"boss","title":"Запись лекаря","text":"Снова приходила мать с Прядильного двора и просила мази для суставов. Я лечу её семью двадцать лет, и никогда она не брала столько: в прошлый раз на две руки, теперь на восемь колен, и говорит, что это для детей. Детей она ко мне больше не водит. Осмотреть себя она не дала, платок не сняла и стояла в тени. Я вышел за ней на крыльцо, но на улице её уже не было, а над дверью качалась серая нитка.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_110","kind":"boss","title":"Письмо мужу","text":"Николас, милый, ты умер, а я всё равно тебе пишу, больше мне некому об этом сказать. В ту зиму наша Мэг замёрзла в кроватке, ты копал ей могилу и потом слёг. Я тогда поклялась тебе, что никто из них больше не замёрзнет. Шерсти у Хемминга больше нет, но я нашла другую нитку, свою. Плести теперь стало быстрее, рук у меня хватает. Дети спят, укрытые, и им тепло, а я прилечь уже не могу. Не сердись, что я так изменилась.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_111","kind":"boss","title":"Приходская запись","text":"Навестил многодетную мать с Прядильного двора, как навещаю уже двенадцать лет. Дверь она не открыла, но говорила со мной ласково и спрашивала про моё колено. Голос её шёл сверху, от балок, хотя я думал, что она стоит за дверью. Младшего я крестил сам, и мне очень хотелось бы на него посмотреть. Я оставил на пороге крупу и две свечи. Крупа исчезла, а свечи утром лежали у моего порога, завёрнутые в серое. Крупы я отнесу ещё.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_112","kind":"boss","title":"Уведомление","text":"Госпожа, вы задолжали мне за полгода, и я прошу вас освободить комнаты на Прядильном дворе. Пристава я уже посылал. Он поднялся по лестнице, двери не нашёл, потому что всё там затянуто серым, и вернулся без шляпы. Наутро шляпа лежала у него на пороге, а в ней тёплый хлеб. Пристав хлеб съел и идти к вам второй раз отказывается. Я помню, как вы носили мне плату мелочью и извинялись. Скажите мне хотя бы, живы ли дети.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_113","kind":"boss","title":"Письмо учителя","text":"Госпожа, ваш Дэви уже четвёртый месяц не приходит в школу, а лучше него у меня никто не считал. Я передал через вашу Лотти грифель и задачи на сложение. Задачи вернулись решённые, ответы все верные, и почерк его, только к листу пристала серая нитка. Внизу он приписал: мастер Оукс, пришлите ещё, пожалуйста, тут больше нечего делать. Посылаю ему ещё десять задач, потруднее, и немного сыра.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_114","kind":"boss","title":"Записка в отдушину","text":"Лотти, мама говорит, что к вам ходить нельзя и что ты заболела. Я кладу в отдушину мою заколку с птичкой, ты её тогда хотела, а я пожадничала. Твоя мама сидела со мной, когда я болела, и пела мне, я теперь часто об этом вспоминаю. Одеяло от вас опять приползло к нашей полке. Я потрогала его и сказала ему: передай Лотти, что я её жду. Ты услышала? Положи мне что-нибудь в отдушину, чтобы я знала. Хильда.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_115","kind":"boss","title":"Записка матери","text":"Лотти, детка, суп теперь будешь варить ты. Мне больше не пройти в кухонную дверь, я пробовала, и плакать об этом не надо. Кости и лук я спущу тебе сверху, с балки, а воду принесёт Роб. Соли клади меньше, чем клала я, у младшего кашель. Вечером считай всех, как считала я, и говори каждому спокойной ночи по имени. Меня к столу не жди, я поем потом, когда вы уснёте. Целую тебя издали.","boss":"boss_spider","floors":[1,2]},{"id":"cellar_116","kind":"boss","title":"Донесение стражи","text":"Капитану от стражника Нолла. Мы с Билли вошли в дом на Прядильном дворе, как вы приказали. Дальше лестницы мы ничего не разглядели, там темно и всюду висит серое. Очнулись мы утром на улице, и оба целы. У меня пришита пуговица, которая болталась с весны, а у Билли заштопан локоть, и нитка серая. Билли сидит у ворот и плачет, мать у него умерла в марте. Прошу второй раз нас туда не посылать. Я знаю, что это приказ.","boss":"boss_spider","floors":[1,2]},{"id":"crypt_001","kind":"note","title":"Прейскурант","text":"Обычную могилу в шесть футов мы копаем за три монеты, а каждый фут глубже стоит ещё монету. Мельче копать не станем, и не просите. За каменистый грунт я беру особо, потому что спина у меня одна. Если покойника придётся закапывать второй раз, платит родня. Вдовам и вдовцам я копаю за две монеты: так завёл мой отец в тот год, когда похоронил мою мать. Гарольд, могильщик."},{"id":"crypt_002","kind":"note","title":"Поминки","text":"Лотти, на поминки по тётушке Дагмар придут тридцать человек, так что зажарь два окорока и закажи бочонок пива, а яблочный пирог я испеку сама. Сыра много не бери, она его никогда не ела. И отодвинь её стул от окна. В прошлом году она пришла на собственные поминки, села на сквозняке и весь вечер ворчала, что ей продуло спину. Я так по ней соскучилась, что поддакивала."},{"id":"crypt_003","kind":"note","title":"Детской рукой","text":"мама велела написать как всё было. мы с бенни играли в прятки на кладбище. я спрятался за ангелом и меня долго никто не нашол и стало темно и я заплакал. потом пришла какая то тётя и сказала что бенни уже дома и отвела меня к воротам. у неё в волосах была земля. она назвала меня воробушком. я сказал спасибо. мама говорит так меня звала только бабушка но я её не помню. утром мама пошла к бабушке на могилу и взяла с собой гребешок"},{"id":"crypt_004","kind":"note","title":"Жалоба смотрителю","text":"Господин смотритель, камень на границе нашего участка и участка Тредуэллов передвинули на ладонь в мою сторону. Мой покойный свёкор всегда лежал ровно посередине своего места, а теперь у него нога оказалась на чужой земле. Этот старик был ко мне добрее родного отца, и я не позволю ему лежать на земле Тредуэллов. Прошу вас вернуть камень и взыскать с виновного. Агнес Марлоу.","chain":"crypt_boundary","part":1},{"id":"crypt_005","kind":"note","title":"Табличка на воротах","text":"Дорогие родные, очень прошу вас не ставить еду на могилы. От неё заводятся крысы, а утром кто-нибудь непременно видит пустую тарелку, и по всему городу идут разговоры. Я понимаю, что вы хотите порадовать своих. Если душа просит, принесите пирог мне в сторожку, я съем его за вашего покойного и с удовольствием послушаю, каким он был человеком. Смотритель."},{"id":"crypt_006","kind":"note","title":"Квитанция","text":"Вдове Блэр. Я получил от вас четыре монеты за дубовый гроб. В пятницу ваш Томас встал, принёс гроб ко мне на спине и сказал, что в плечах тесновато. Крышка цела, состояние хорошее, поэтому три монеты я возвращаю. Одну оставляю себе за беспокойство: тридцать лет я делаю гробы, и на мою работу ещё никто не жаловался лично. Кланяйтесь ему, мы с ним всё-таки вместе росли. Гробовщик Оукс."},{"id":"crypt_007","kind":"note","title":"Заказ резчику","text":"Мастер Корвин, вы знали моего Эдмунда, так что поймёте меня. Прошу вырезать на камне: «Любимому мужу, Эдмунду Холлу, лучшему из людей». Буквы сделайте глубокие, с золотом по краю, чтобы их можно было прочесть и через сто лет. Двадцать шесть зим он грел мне ноги и ни разу не сказал, что они холодные. Задаток я оставила у вашей жены. Вдова Пруденс Холл.","chain":"crypt_epitaph","part":1},{"id":"crypt_008","kind":"note","title":"Циркуляр цеха","text":"Цех гробовщиков, всем мастерам. Братья, с первого числа заколачивайте крышки девятью гвоздями вместо шести. Разницу берите с заказчика и объясняйте, что подорожало железо. Настоящую причину родне не называйте: шести гвоздей покойнику теперь хватает только до среды. Людям и так тяжело, незачем им об этом знать. Берегите руки и спите, пока спится. Старшина цеха."},{"id":"crypt_009","kind":"note","title":"Письмо сестре","text":"Энни, ты же знаешь, что сорок лет я плачу на чужих похоронах за деньги. Когда хоронили моего Уилла, у меня не вышло ни слезинки, и соседки всё это видели. Дома я села и подсчитала, сколько взяла бы за такие похороны. Вышло шесть монет. Утром я пошла к Фитцам, у них умер свёкор, и ревела там так, что хозяйка прибавила мне монету. Она думала, что я плачу по свёкру. Приезжай, сестрёнка, мне очень плохо одной."},{"id":"crypt_010","kind":"note","title":"Письмо жене","text":"Дорогая Марта, устроился я хорошо. Здесь сыровато, зато сосед тихий, бывший аптекарь. Пришли мне, пожалуйста, шерстяные носки, синие, а то ноги мёрзнут. Письмо я оставлю под камнем, ты найдёшь его, когда придёшь поливать астры. Скажи Бобу, чтобы не бросал калитку открытой. Не плачь, голубка, и ешь как следует, я же знаю, что одна ты совсем перестанешь готовить. Твой Годфри.","chain":"crypt_letters","part":1},{"id":"crypt_011","kind":"note","title":"Наказ ученику","text":"Том, прежде чем рубить, всегда переворачивай плиту. Камень у нас старый, и на обороте часто стоит чьё-то имя. Чужое имя замажь раствором и работай спокойно. Но если на обороте окажется то самое имя, которое сейчас заказали, и тот же год, ничего не руби, сразу позови меня и родне ни слова не говори. Со мной такое было дважды, и оба раза я потом не спал. И надень рукавицы, я тебя прошу: без пальцев ты мне в мастерской не нужен, а я к тебе уже привык."},{"id":"crypt_012","kind":"note","title":"Эпитафия","text":"Здесь лежит Нед Уик, который до последнего дня говорил, что кашель у него пустяковый. Я тебе говорила, Нед. Приду в воскресенье и скажу ещё раз. Твоя Бетси."},{"id":"crypt_013","kind":"note","title":"Надпись на камне","text":"Наша Пиппа Роу прожила два года и четыре месяца и больше всего на свете любила пуговицы. Если вы найдёте пуговицу, положите её сюда, пожалуйста. Мы с отцом всё ещё находим их по всему дому и приносим ей."},{"id":"crypt_014","kind":"note","title":"Ответ соседке","text":"Госпожа Марлоу, камень стоял так ещё при моём отце, и отец мой считать умел. Ваш свёкор при жизни занимал чужое место и на рынке, и у колодца. Если теперь у него нога оказалась на моей земле, то это у вас семейное. Камня я не трону. Мы с вами тридцать лет не здороваемся, и я не вижу причин начинать, но ваши астры в этом году удались, это я признаю. Бартоломью Тредуэлл.","chain":"crypt_boundary","part":2},{"id":"crypt_015","kind":"note","title":"График дежурств","text":"В понедельник дежурит Рид. Во вторник Рида хоронят, поэтому вместо него выйдет Оуэн. В среду дежурит Оуэн. В четверг Рид вышел на работу сам, и я, братцы, чуть не расплакался, так я ему обрадовался. В пятницу дежурит Рид. За вторник жалованье Риду не начислять, потому что он отсутствовал. Не обижайся, Рид, порядок есть порядок, а пива я тебе поставлю, если ты теперь пьёшь."},{"id":"crypt_016","kind":"note","title":"Прошение","text":"Господин смотритель, прошу вас перенести мою бабушку Гертруду на южную сторону, потому что на северной у неё ноет колено. О колене она сообщила нам сама, в четверг, за ужином. Мы её очень любим и рады видеть, но она сидит у нас уже четвёртый вечер и говорит, что ляжет обратно только на солнышке. Ваш покорный слуга Джозеф Пайк, её внук."},{"id":"crypt_017","kind":"note","title":"Счёт таверны","text":"Стол могильщиков. Гарольд выпил шесть кружек, Симон четыре. Тот, что сидел с ними, взял одну и не притронулся к ней, только держал её в руках и слушал, как они смеются. Ушёл он, не заплатив. Запишу его кружку на Гарольда, потому что Гарольд его закапывал. Гарольд не спорил и велел в следующий раз налить ему того же, что и всегда."},{"id":"crypt_018","kind":"note","title":"Второе письмо","text":"Мастер Корвин, уберите, пожалуйста, «лучшему из людей». Я разбираю стол Эдмунда и реву над каждым ящиком, а сегодня нашла в нём счета от некой Розалинды за ленты. Никаких лент я от него за двадцать шесть лет не видела! «Любимому» пока оставьте, я ещё не всё разобрала. Пруденс Холл.","chain":"crypt_epitaph","part":2},{"id":"crypt_019","kind":"note","title":"Рецепт","text":"Мама оставила мне рецепт пирога на поминки: яблоки, мёд, корица и муки сколько возьмёт. Сколько возьмёт, мама? Я пекла уже три раза, и каждый раз выходит камень. Говорят, хранитель книги поднимает покойных, чтобы уточнить у них то, что не записано, и я думаю об этом чаще, чем хотелось бы. Я спросила бы только про муку, честное слово, а потом ещё немножко посидела бы с тобой."},{"id":"crypt_020","kind":"note","title":"Школьная задача","text":"В ряду двенадцать могил. Ночью из них вышли трое, а к утру вернулись двое. Сколько могил должен проверить смотритель? Ответ Лиама: все двенадцать, потому что папа всегда проверяет все, а потом долго моет руки. Рукой учителя: верно, Лиам, но запиши ход решения. И передай папе, чтобы он не ходил туда один, мы все за него волнуемся."},{"id":"crypt_021","kind":"note","title":"Второе письмо","text":"Марта, носки я получил, спасибо, только левый маловат. По вечерам больше не приходи: ты сидишь на сырой траве, а спина у тебя сама знаешь какая. Аптекарь советует барсучий жир, натирай на ночь и не жалей. Приходи лучше днём, когда сухо, и садись на скамейку, я для того её и просил поставить. Мне оттуда всё слышно, голубка. Твой Г.","chain":"crypt_letters","part":2},{"id":"crypt_022","kind":"note","title":"Молитва","text":"Пошли нам, Господи, сухую землю и нетяжёлую глину. Сделай так, чтобы лопата опять не упёрлась в черепицу, а то этой осенью такое случилось уже в третий раз, и все мы делаем вид, что это камень. И дай моей Мэри поправиться. Про землю я прошу для порядка, а про неё всерьёз. Записываю это, потому что вслух при ней сказать не могу."},{"id":"crypt_023","kind":"note","title":"Любовная записка","text":"Кларисса, я буду ждать тебя у склепа Вейнов после вечерни, туда никто не ходит. Надень ту голубую ленту, я всю неделю о ней думаю. Я знаю, что ты жена смотрителя, и знаю, что нам надо это прекратить, но третью ночь не сплю. Покойники никому не скажут. Вейны, правда, могут, но они со всеми в ссоре, и их никто не станет слушать. Твой до гроба, а здесь до него недалеко."},{"id":"crypt_024","kind":"note","title":"Записка на могиле","text":"Ада, я положил с тобой гребень, как ты просила. Потом я вспомнил, что волосы ты всегда расчёсывала левой рукой, а гребень я вложил тебе в правую. Ночью я сходил и переложил его. Смотрителю я сказал, что это был крот. Пятьдесят лет ты меня поправляла, милая, а теперь приходится самому."},{"id":"crypt_025","kind":"note","title":"Запись смотрителя","text":"Участки Марлоу и Тредуэлл я измерил шагами дважды, и оба раза вышло по-разному. Камень я поставил посередине и велел родне успокоиться. Утром он снова оказался на стороне Марлоу, а земля была взрыта с обеих сторон. На следующую ночь я запер обоих спорщиков у себя в сторожке, и до утра они ругались у меня на глазах, а камень всё равно сдвинулся. Жена спрашивает, кто же его двигает. Я велел ей ложиться и запер дверь.","chain":"crypt_boundary","part":3},{"id":"crypt_026","kind":"note","title":"Объявление","text":"Я потерял вставную челюсть, деревянную, на похоронах моего друга Хиггинса. Нашедшему дам вознаграждение. Если её нашёл сам Хиггинс, пусть оставит себе, я обзавёлся новой. Мы с ним сорок лет делили одну скамейку и один табак, так что поделим и это."},{"id":"crypt_027","kind":"note","title":"Дневник","text":"Я зарыл Буна у ограды, где нельзя, и никому не показал это место. Четырнадцать лет он спал у меня в ногах. Через неделю ночью кто-то стал копать у меня во дворе, я вышел с палкой и не сразу понял, кто это. Потом я сел прямо на землю и заплакал. Принёс ему кость, он её не взял, зато махал хвостом. Теперь я оставляю дверь открытой."},{"id":"crypt_028","kind":"note","title":"Третье письмо","text":"Мастер Корвин, «любимому» оставьте и больше не трогайте. Розалинда оказалась шляпницей. Ленты он брал на шляпу для меня, шляпа оплачена и три года ждала у неё на полке, потому что этот человек три года забывал её забрать. «Лучшему из людей» не возвращайте, раз он три года забывал. Допишите вместо этого: «Шляпу я забрала». Я сижу в ней на кухне и не знаю, как ещё на него сердиться.","chain":"crypt_epitaph","part":3},{"id":"crypt_029","kind":"note","title":"Правила для новых","text":"Держите лопату при себе. После заката спиной к рядам не стойте. Если кто-то окликнет вас по имени, сначала подумайте, кому вы его называли. Обедаем в сторожке. Кружку мойте за собой, вчера опять оставили. Я вам не мать, ребята, но вашим матерям я обещал, что вы вернётесь домой, так что будьте любезны."},{"id":"crypt_030","kind":"note","title":"Черновик речи","text":"Речь над Альбертом. Друзья! Альберт был честен (зачёркнуто). Альберт был трезв по воскресеньям (зачёркнуто). Альберт был с нами очень долго. Так и оставлю. Он занял у меня двадцать монет и вернул одну, а я до сих пор не знаю, с кем теперь буду ходить на рыбалку."},{"id":"crypt_031","kind":"note","title":"Письмо брату","text":"Хью, отец снова дома. Он вошёл ночью, снял сапоги у двери, как при жизни, и сел на своё место. Мать поставила ему тарелку. Есть он не ест, зато починил забор и, наверное, поможет нам с яблоками. Смотрителю пока ничего не пиши, дождёмся конца сбора. Мать впервые с зимы напевает у печки. Приезжай, брат, сам всё увидишь, только разуйся у двери, он на это смотрит."},{"id":"crypt_032","kind":"note","title":"Письмо мужу","text":"Годфри, преподобный Лоуэлл прочитал твоё письмо и велел его сжечь. Он говорит, что писать ты не можешь, потому что я сама тебя хоронила. Я ответила ему, что левый носок ты ругал всю жизнь, и никто другой этого знать не может. Я вяжу новый, побольше. Письмо я не сожгла, оно лежит у меня под подушкой. Твоя Марта.","chain":"crypt_letters","part":3},{"id":"crypt_033","kind":"note","title":"Обрывок тетради","text":"мама сказала что дедушка теперь спит на горке. а он вчира стоял у забора и смотрел как мы играим. я ему помахала. он не махнул обратно. наверно забыл как. мама не велела ходить к забору но я всё равно пойду потомучто он там один. я возьму его за руку и покажу как надо махать"},{"id":"crypt_034","kind":"note","title":"Шутка","text":"Записываю шутку, которую рассказал сегодня в сторожке, пока не забыл. Приходит покойник к смотрителю и говорит: у меня жалоба. Смотритель отвечает: оставьте в ящике. А покойник ему: так я в ящике и лежу. Вечером я рассказал её жене. Жена не смеялась и сказала, что эту шутку я рассказывал ещё на нашей свадьбе. Вот и хорошо, значит, она помнит нашу свадьбу."},{"id":"crypt_035","kind":"note","title":"Записка жене","text":"Мэг, я сегодня буду поздно. Мы роем могилу сразу на троих, земля сырая, и край уже один раз обвалился. Суп оставь на печи и ложись, не жди меня. Если я приду и скажу, что всё хорошо, сначала спроси меня, как зовут нашу козу. Я не шучу, милая: к Оуэнам муж тоже пришёл ночью и сказал, что всё хорошо. Целую тебя и козу."},{"id":"crypt_036","kind":"note","title":"Запись смотрителя","text":"Госпожа Марлоу скончалась в марте, а Тредуэлл ушёл через три недели, хотя здоровье у него было как у быка. Соседки говорят, что ему стало не с кем ругаться. Они лежат через камень, и камень ходит по ночам примерно на ладонь. Разбираться я перестал и теперь записываю только, в какую сторону он пошёл. Вчера он опять сдвинулся к Марлоу. В трактире принимают ставки, и я поставил на неё.","chain":"crypt_boundary","part":4},{"id":"crypt_037","kind":"note","title":"Расписка","text":"Я, Хэмфри Слоун, занял у Джона Бейли шесть монет и отдам к осенней ярмарке. Ниже другой рукой: Хэмфри умер летом. В день ярмарки я нашёл на подоконнике шесть монет, сырых и в земле. Я вымыл их и положил в кошель. Дурак ты, Хэмфри, мы же с тобой с детства дружили, я бы и так простил."},{"id":"crypt_038","kind":"note","title":"Счёт резчика","text":"Вдове Холл. Первая надпись с золотом стоит шесть монет, а её стёсывание две. Вторая надпись стоит три монеты, стёсывание ещё две. Третья надпись тоже три. Камень стал тоньше на палец, но за это я не беру. Шляпа вам к лицу. Моя жена видела вас в ней в церкви и сказала, что Эдмунд, старый растяпа, всё-таки умел выбирать. Мастер Корвин.","chain":"crypt_epitaph","part":4},{"id":"crypt_039","kind":"note","title":"Листовка","text":"Оберег от вставших покойников! Он сделан из олова, освящён и стоит всего полторы монеты. Подумайте о матушке: она у вас одна, и двоюродный дядя, который умер в прошлом году, у вас тоже один, и он прекрасно знает, где она живёт. Если оберег не поможет, мы вернём деньги. Жалобы принимаем только лично от пострадавшего."},{"id":"crypt_040","kind":"note","title":"Последнее письмо","text":"Марта, мне сказали, что ты теперь здесь, в восточном ряду. Я так и знал, что ты опять сидела на сырой траве. Спроси у смотрителя, нельзя ли поменяться местами с Хопкинсами, а то через два ряда кричать неудобно, да и голос у меня уже не тот. Носки можно больше не вязать, теперь отдыхай. Я ждал тебя, голубка, и совсем не торопил. Твой Годфри.","chain":"crypt_letters","part":4},{"id":"crypt_041","kind":"secret","title":"За кирпичом","text":"Дик, ты спрашивал, откуда у нас новая миска. Мы копали под склепом Фарроу и вышли на черепицу. Под черепицей оказалась комната, в комнате стоял стол, а на столе миска. Смотрителю я сказал, что там камень. Миску, если честно, я взял, уж очень она хорошая. Только маме не говори, что до нас из неё кто-то ел суп, лет за тысячу."},{"id":"crypt_042","kind":"secret","title":"Под плитой","text":"В фундаменте часовни я нашёл плиту с именем моего деда. Дед жив и ходит на рынок. Плита старше часовни, и мох на ней старше меня. Я поставил её обратно лицом внутрь. Деду я ничего не сказал: сердце у него слабое, и я люблю этого старого ворчуна, так что пусть ещё походит на рынок."},{"id":"crypt_043","kind":"secret","title":"Детской рукой","text":"тут мои конфеты. кто возьмёт будет проклят. это честное проклятие, я попросила тётю из склепа и она кивнула. но если ты грустный то можно взять одну. тётя тоже сказала ладно"},{"id":"crypt_044","kind":"secret","title":"Между томами","text":"Я перебрал книги усопших за двести лет, всё искал старика, который смотрит за огнём на площади. Нет ни записи о рождении, ни могилы. Тогда я решил спросить у него самого, как его зовут и откуда он взялся. Сел к костру, а он подвинул мне кружку и спросил, как там мой сын. Мы проговорили о сыне до утра, и мне впервые за эти годы стало легче. Как его зовут, я так и не спросил."},{"id":"crypt_045","kind":"secret","title":"В склепе","text":"Кто-то прокопал ход между склепом Линчей и склепом Барроу. Мы думали, что это воры, но ничего не пропало. В ходе стоят две кружки, а колода карт разложена на середине партии. Старики Линч и Барроу пятьдесят лет играли по четвергам, и каждый на смертном одре клялся, что другой жульничал. Закрывать ход я пока не стал, Барроу вроде выигрывает."},{"id":"crypt_046","kind":"secret","title":"Старая надпись","text":"Сестрица, на дне старого склепа мы нашли надпись, и буквы там почти такие же, как наши. Отец Мэтью смог разобрать только конец: «...оставляем вам. Крыша течёт с северной стороны, простите». Крыша там и вправду течёт с северной стороны. Кто-то умер задолго до всех нас и всё равно стыдился перед нами за крышу. Отец Мэтью прослезился, и я, признаться, тоже."},{"id":"crypt_047","kind":"secret","title":"В кувшине","text":"Кто бы ты ни был, милый человек, в этом кувшине лежат семена, а рядом мешочек соли. Я закопала их на случай, если наверху станет худо. Семена прошлогодние, и с тыквами у меня никогда не получалось, так что не обессудь. Дочка смеётся, что я прячу еду для людей, которых нет. А я думаю, что ты будешь. Ешь как следует и одевайся теплее."},{"id":"crypt_048","kind":"secret","title":"Письмо без адреса","text":"На похоронах судьи Уайта я плакала за четыре монеты. Он был мой отец, об этом знали только мы двое, а теперь знаю я одна. Плакала я как обычно, чтобы никто не заметил разницы. Однажды на рынке, когда мне было семь лет, он взял меня за подбородок и сказал, что я похожа на мать. Деньги лежат здесь. Тратить их я не хочу, а выбросить жалко."},{"id":"crypt_049","kind":"secret","title":"Список смотрителя","text":"Пишу для себя, в книгу этого не заношу. Этой осенью выходили и вернулись до рассвета Эбби Кларк, Нил Мур и двое Стэнли. Ходили они только домой и постояли под окнами. Если об этом узнает хранитель книги, он будет поднимать их на допрос, так что пусть постоят. Эбби всю жизнь сама укладывала детей и теперь хочет только послушать, как они засыпают."},{"id":"crypt_050","kind":"secret","title":"За ящиком","text":"Мама, Дэн опять спустился через провал за часовней, и я не смог его удержать. Он говорит, что ниже нашего есть ещё одно кладбище, что на плитах там наши фамилии, только пишутся они странно, а на каждой третьей лежат свежие цветы. Я спросил его, кто их носит. Он пожал плечами и пошёл ужинать. Поговори с ним, тебя он слушает, а у меня сердце не на месте."},{"id":"crypt_051","kind":"boss","title":"Книга усопших","text":"Аделина Корр, прачка. Умерла весной. Поднята для уточнения даты. Дату не помнит. Поднята повторно. Просит прекратить. Причина просьбы не указана, запрос возвращён заявителю.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_052","kind":"boss","title":"Том 88","text":"Эзра Нолл, кровельщик. Графа причины смерти заполнена неразборчиво. Поднят для уточнения. Показал, что упал с крыши. Какая это была крыша, не указано. Поднят повторно, чтобы уточнить крышу. В настоящее время указывает рукой на север и ложиться отказывается. Дело открыто. На полях рукой писца: это крыша его дочери, он чинил её перед зимой и не успел закончить.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_053","kind":"boss","title":"Прошение вдовы","text":"Господин хранитель, пишет вам вдова Тиббс. Моего мужа вы поднимали уже три раза, записи об этом у вас есть, а он совсем исхудал. Я всю жизнь его откармливала, он и так был худой. Прошу вас, оставьте его в покое хотя бы до весны, дайте человеку полежать. Пометка канцелярии: заявитель в книге усопших не значится. Подать повторно после внесения.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_054","kind":"boss","title":"Жалоба совету","text":"Хранитель поднял весь южный ряд для сверки. Третий год они стоят вдоль стены по алфавиту, и к колодцу пройти нельзя. Просим сверять их в другом месте или хотя бы убрать с прохода букву М. Там стоит Том Миллер, муж нашей Лиззи, и она каждое утро приносит ему шарф, а он её не узнаёт. Подписали жители Кладбищенского переулка.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_055","kind":"boss","title":"Жалоба писца","text":"Совету от писца Арно. Я служу при книге двенадцатый год. Господин хранитель требует точности до часа и велел поднимать всех за двести лет подряд. Я попросил у него один день на похороны матери. Он ответил, что мать будет поднята в свой черёд, и тогда я с ней увижусь. Он сказал это ласково, господа, как будто дарил мне что-то. Прошу вас, заберите меня от него.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_056","kind":"boss","title":"Том без номера","text":"Хранитель книги усопших. Имя: смотри том первый. Том первый не найден. Умер, по словам писца, зимой. Поднят собственноручно для уточнения. Дату не помнит. Приступил к обязанностям. Приписка писца: я сам закрыл ему глаза, а утром он сидел за столом и спрашивал, почему чернила стоят не на месте. Я принёс ему чернила. Что мне ещё было делать?","boss":"boss_necro","floors":[3,4]},{"id":"crypt_057","kind":"boss","title":"Детское прошение","text":"господин хранитель. это нелли. вы подняли мою бабушку спросить про дату а она всё говорит про пироги. пожалуста пусть она ещё немножко поговорит. папа сказал что нельзя просить но вы же всё равно её спрашиваете. я могу сама приходить и слушать про пироги а вы идите отдохните, вы наверно устали","boss":"boss_necro","floors":[3,4]},{"id":"crypt_058","kind":"boss","title":"Вырванный лист","text":"Мэрион, жена хранителя. Умерла на исходе зимы, дата известна, уточнений не требуется. Поднята для уточнения, не холодно ли ей. Поднята для уточнения, ела ли она. Поднята для уточнения, сердится ли. Поднята для уточнения. Поднята для уточнения. Продолжение на обороте.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_059","kind":"note","title":"Договор","chain":"crypt_bell","part":1,"text":"Мисс Гонория Эйнсли, будучи в здравом уме, заказывает медный колокольчик на столбике у своей будущей могилы и шнур от него к правой руке в гробу. Она очень боится проснуться там одна. Её племянник Перси будет платить ночному сторожу Джасперу по монете в месяц, чтобы тот слушал колокольчик, а если услышит, то копал. Мисс Эйнсли просит записать отдельно, что Перси хороший мальчик, хотя навещает её только по четвергам."},{"id":"crypt_060","kind":"note","title":"Протокол собрания","text":"Приходское собрание рассмотрело вопрос, могут ли вставшие сидеть в церкви на своих прежних скамьях. За проголосовали четырнадцать человек, против одиннадцать. Постановили, что сидеть они могут, но только в задних рядах и петь не будут. Вдова Кобб попросила занести в протокол, что её муж и при жизни пел плохо и никто ему не запрещал, а теперь он сидит и молчит, и она не может этого слышать. Вопрос о пении решено отложить до весны."},{"id":"crypt_061","kind":"note","title":"Приглашение","text":"Дорогая тётя Вайолет, в субботу я выхожу за Питера, и столы мы поставим прямо у кладбищенской ограды, возле третьего ряда. Мама лежит там с осени, и я хочу, чтобы музыка до неё доставала. Я знаю, что это странно, и родня Питера уже делает лица. Папа обещал играть на скрипке и не плакать, хотя на второе я не рассчитываю. Приезжайте, пожалуйста, и наденьте ту шаль, которую она вам подарила. Ваша Анна."},{"id":"crypt_062","kind":"note","title":"Записка на камне","chain":"crypt_second_wife","part":1,"text":"Госпожа Изабель, мы с вами не знакомы. Меня зовут Дорис, и в мае я вышла замуж за вашего Оливера. Мне показалось нечестным не сказать вам об этом лично. Он до сих пор носит ваше кольцо на шнурке и думает, что я не знаю. Я на него не сержусь и на вас тоже. Заодно я прополола ваши мальвы, надеюсь, вы не в обиде, просто у меня руки не могут пройти мимо сорняка."},{"id":"crypt_063","kind":"note","title":"Записка учителю","text":"Господин учитель, прошу извинить моего Гилберта за вторник. Он помогал укладывать дедушку обратно. Дедушка у нас крупный, одна я с ним не справляюсь, а ложиться он в этот раз не хотел и всю дорогу держал мальчика за рукав. Гилберт вернулся домой поздно и совсем притихший, поэтому утром я дала ему поспать. Чистописание он сделает в среду. Джудит Рэнсом, его мать."},{"id":"crypt_064","kind":"note","title":"Лист переписи","text":"В доме Бёрчей проживают Кристофер Бёрч, его жена Эмма, трое детей и тёща, госпожа Крамп. Хозяин сообщил мне с порога и довольно громко, что госпожа Крамп умерла два года назад, и просил её не учитывать. Госпожа Крамп сообщила из кухни, что дом куплен на её деньги, и велела записать её первой. У ворот Эмма шепнула мне, что без матери ей было бы совсем худо. Я записал всех. Итого в доме проживают шесть человек."},{"id":"crypt_065","kind":"note","title":"Донесение сторожа","chain":"crypt_bell","part":2,"text":"Господин Перси, в ночь на четверг колокольчик на могиле вашей тётушки зазвонил. Я разбудил напарника, и мы раскопали её за два часа, хотя вы знаете, какая у нас глина. Мисс Эйнсли лежала мёртвая и совершенно спокойная. Мы закопали её обратно. Думаю, что шнур дёрнула осевшая земля. За раскопки прошу две монеты. Вы бы приехали, сударь, могилка у неё хорошая, а цветов совсем нет."},{"id":"crypt_066","kind":"note","title":"Опись","text":"Опись имущества покойного Роберта Кента, составил оценщик Рэй. В доме стоят стол, два стула и кровать, есть котёл с трещиной. Чашек две: одна с отбитой ручкой, другая целая, чистая, с цветочком. Соседка рассказала мне, что из второй пила его жена, которая умерла двенадцать лет назад, и что он мыл эту чашку каждое утро вместе со своей. Оцениваю её в полмонеты. Покупателя искать я не стал и отдал чашку соседке, она меня попросила. Полмонеты вношу сам."},{"id":"crypt_067","kind":"note","title":"Под диктовку","text":"Записано отцом Мэтью со слов Гарольда, который писать не умеет. Молли, дочка, у меня всё хорошо. (Кашляет с осени, это я добавляю от себя.) Денег мне не присылай, у меня их полно. (Одни и те же штаны он заштопал трижды.) Мне и одному неплохо живётся, скучать тут некогда. (Тут он замолчал, долго смотрел в окно и велел написать про погоду.) Погода стоит хорошая. Письмо я прочту ему вслух, без скобок. Приезжай, Молли."},{"id":"crypt_068","kind":"note","title":"Вторая записка","chain":"crypt_second_wife","part":2,"text":"Госпожа Изабель, я нашла вашу поваренную тетрадь. На полях вы написали: «Лука ему поменьше, врёт, что любит». Двенадцать лет он врал вам, а теперь врёт мне, и я-то каждую субботу жарила с луком! Там же написано: «Если молчит, не трогать до ужина». Я смеялась одна на кухне, а потом почему-то заплакала. Вы бы мне понравились, честное слово."},{"id":"crypt_069","kind":"note","title":"Ответ заказчице","text":"Госпожа Хоггарт, вы просите стихи на камень, чтобы рифмовались с именем вашего мужа. К имени Губерт рифм у меня только две: «любит» и «рубит». Он был мясник и вас очень любил, так что я предлагаю взять обе: «Здесь лежит наш Губерт, он мяса больше не рубит, но всё равно нас любит». Выйдет дороже на монету. Возвышенно с таким именем не получается, я пробовал всю ночь и, кажется, даже всплакнул, он ведь отпускал мне в долг."},{"id":"crypt_070","kind":"note","title":"Сестре о муже","text":"Кэт, мой Говард шестой год копает себе могилу. Он говорит, что хочет сделать хорошо, а сам уходит туда с трубкой сразу после завтрака и сидит дотемна, и за шесть лет яма стала глубже на два фута. Я знаю, что он просто бегает от меня и от кур. Теперь я ношу ему обед, мы садимся на край, спускаем ноги и разговариваем так, как не говорили с самой свадьбы. Только не проговорись ему, что я всё поняла, пусть копает помедленнее."},{"id":"crypt_071","kind":"note","title":"Что я возьму","text":"когда я умру я возьму с собой: 1 ножик. 2 собаку если она тоже уже умрёт. 3 шапку потомучто там холодна. 4 папу. папа сказал что он не пойдёт но я его всё равно записала. 5 хлеба. мама сказала что брать ничего не надо там всё есть. откуда она знает если там не была. я спросила. она стала плакать и обняла меня и мы потом пекли печенье. печенье я тоже возьму"},{"id":"crypt_072","kind":"note","title":"Мелом на двери","text":"Ушёл копать для Фергюсонов, вернусь к обеду. Кто хочет сделать заказ, напишите фамилию мелом здесь, ниже. Дорси, это тебе, старый ты пень. Перестань писать свою фамилию. Лекарь сказал мне, что у тебя изжога и больше ничего, а я уже два раза начинал копать. Если тебе скучно одному с тех пор, как уехала Нелл, так и скажи и приходи вечером, у меня есть сидр."},{"id":"crypt_073","kind":"note","title":"Второе донесение","chain":"crypt_bell","part":3,"text":"Господин Перси, колокольчик теперь звонит каждый четверг после полуночи. Откапывать её я больше не стану. Я взял скамеечку, сажусь рядом и говорю: «Я здесь, мисс Эйнсли, всё хорошо, спите». Звон тут же стихает. Это она вас ждёт по четвергам, сударь, я понял это на третий раз. Я пробовал отвечать за вас, но голос у меня грубый, и она звонит ещё немного, прежде чем поверить. Приехали бы, честное слово."},{"id":"crypt_074","kind":"note","title":"Записка в лавку","text":"Дженни, пока я у сестры, запомни постоянных. Господин Вуд берёт белые для жены и жёлтые для другой, не перепутай и сделай вид, что ничего не понимаешь. Вдова Оукли стесняется, что покупает самые дешёвые, так что клади ей побольше и считай как за три стебля. Весной придёт старик с палкой за фиалками для покойной жены. Денег с него не бери. Когда-то он звал замуж меня, и пусть это останется между нами. Воду меняй утром, детка, и обедай, пожалуйста."},{"id":"crypt_075","kind":"note","title":"Книга мерок","text":"Артур Пендл, пять футов восемь дюймов. Жена не поверила и велела ему встать прямо, потому что он всю жизнь сутулится, а в гробу распрямится. Я перемерил, вышло пять футов девять. Ширину плеч госпожа Пендл уточнила сама, руками, и убрала их не сразу. Себя мерить она не дала и сказала, что я и так вижу. Гробы они заказали одинаковые. Он спросил, нельзя ли сделать в стенке дырку, чтобы разговаривать. Я сказал, что нельзя, и они ушли под руку и спорили про дырку до самой площади."},{"id":"crypt_076","kind":"note","title":"Про зеркало","text":"Ричард, когда умерла Нора, мы завесили все зеркала, как положено, а про то, что на чердаке, забыли. На прошлой неделе Джо слазил туда и сказал, что в зеркале мама чистит яблоки. Я велел ему не выдумывать и пошёл завесить зеркало сам. Простоял там до ночи, брат. Она подняла голову и показала мне на подбородок: я третью неделю не брился. Я знаю, что надо завесить, и завешу, только не на этой неделе. Побрился."},{"id":"crypt_077","kind":"note","title":"Записка соседке","text":"Бриджит, пожалуйста, не пускай своих к колодцу у часовни. Мой Джимми крикнул туда: «Кто там?», просто так, как все мальчишки кричат. А снизу ответили: «Джимми, иди обедать». Это был голос моей матери, больше никто так не тянет его имя. Я заколотила колодец досками и сказала Джимми, что это эхо. Вчера вечером, когда он уснул, я сходила туда и отодвинула одну доску, и она позвала обедать меня. Доску я вернула на место. У тебя остались длинные гвозди?"},{"id":"crypt_078","kind":"note","title":"Третья записка","chain":"crypt_second_wife","part":3,"text":"Изабель, можно я буду без «госпожи»? Оливер слёг. Лекарь говорит про грудь и отводит глаза. Про это в вашей тетради ничего нет, я пролистала её всю. На последней странице остался недописанный рецепт варенья из крыжовника, и дальше пусто, наверное, вы тогда уже болели сами. Скажите, он брал вас за руку или отворачивался к стене? Мне надо знать, как с ним быть. Простите, что спрашиваю."},{"id":"crypt_079","kind":"note","title":"Гарольду","text":"Гарольд, ты спрашивал, зачем я прихожу раньше всех. Третий месяц кто-то по ночам роет яму у восточной стены. Роет чище нашего, ровно на шесть футов, и никто за этим не приходит. А через день или два кто-нибудь умирает, и яма приходится ему как раз. Симон говорит, что пусть роют, спине легче. Сегодня утром я нашёл маленькую, на ребёнка. Я засыпал её и утоптал, пока никто не видел. Завтра приду ещё раньше. У Оуэнов младшая кашляет, ты знал?"},{"id":"crypt_080","kind":"note","title":"Зимняя запись","text":"Снег лежит по всему кладбищу, кроме могилы Генри Оттера: там он тает каждую ночь. Прихожане начали шептаться, а один уже приложил к холмику больную ногу. Я дождался темноты и посмотрел сам. Вдова Оттер пришла с передником, полным горячих кирпичей, разложила их по могиле и немного постояла. Он всю жизнь мёрзнул, и сорок лет она грела ему постель. Прихожанам я ничего объяснять не стал. Ей я оставил у калитки свои кирпичи, у меня печка жарче."},{"id":"crypt_081","kind":"note","title":"Письмо подмастерью","text":"Бен, ты спрашивал, почему я взял за портрет дочки Ларков меньше обычного. Девочка умерла в ноябре, и родители просили написать её с открытыми глазами. Мать сказала, что глаза у неё были голубые, а отец сказал, что серые. Они спорили при мне, а потом вдруг замолчали, потому что каждый испугался, что забыл. Я смешал что-то среднее, как вода в пасмурный день. Оба заплакали и сказали друг другу: вот видишь. Я тебе покажу этот цвет, он может пригодиться."},{"id":"crypt_082","kind":"note","title":"Ответ племянника","chain":"crypt_bell","part":4,"text":"Джаспер, посылаю тебе монету за месяц и ещё одну за скамеечку. Приехать я пока не могу. Тётя растила меня с шести лет, и я знаю всё, что ты хочешь мне сказать. Я боюсь, что приеду, скажу ей что-нибудь, колокольчик замолчит, и тогда всё кончится по-настоящему. А пока он звонит, я ещё могу приехать в следующий четверг. Говори ей, что я здоров и ем суп. Перси."},{"id":"crypt_083","kind":"note","title":"Соседке о пчёлах","text":"Госпожа Белл, когда хозяин умирает, надо пойти к ульям и сказать об этом пчёлам, иначе они улетят. Отец умер три недели назад. Я хожу туда каждое утро, стучу ключом по ульям, как он учил, и говорю им, что он задержался на ярмарке. Пчёлы работают, мёд идёт хороший. Вы знали его лучше всех, и я прошу вас прийти и сказать им самой. Я пробовала, только у меня не выговаривается. Вас они послушают, а я постою за яблоней."},{"id":"crypt_084","kind":"note","title":"Письмо внучке","text":"Милая Мэри, ты спрашивала, чем занимается твой дед. Покойнику кладут на грудь хлеб, я съедаю его, запиваю пивом, и грехи покойного переходят ко мне. За это мне дают монету и в дом не пускают, потому что грехов на мне теперь на целую улицу. У старого Хаммонда хлеб был лёгкий, а над судьёй я жевал до утра. Сорок лет я ем за этот город, детка, и никто не садится со мной за стол. Кто съест за меня, я пока не знаю. Напиши мне что-нибудь про свою школу."},{"id":"crypt_085","kind":"note","title":"Объяснение звонаря","text":"Господин настоятель, вы спрашивали, кто звонил в полночь. Это был я. По обычаю я бью столько раз, сколько человеку было лет. На похоронах старого Пула я задумался о том, как он учил меня рыбачить, сбился и дал шестьдесят два удара вместо семидесяти одного. Вдова Пул считала. Она ничего мне не сказала, только посмотрела, и я не смог заснуть. Ночью я поднялся на колокольню и добил ему девять. Штраф прошу удержать из жалованья."},{"id":"crypt_086","kind":"note","title":"Предложение","text":"Элси, говорить я не мастер, поэтому пишу. У меня есть дом в две комнаты и работа, которая никогда не кончится, потому что люди умирать не перестанут. Пью я мало. По воскресеньям руки у меня чистые, можешь проверить. Я видел, как ты несёшь воду от колодца, и с тех пор копаю криво, смотритель уже заметил. Дай мне ответ, какой есть. Кристиан. Ниже другим почерком: покажи руки в воскресенье."},{"id":"crypt_087","kind":"note","title":"Просьба сторожа","chain":"crypt_bell","part":5,"text":"Господин смотритель, Перси уже третий год не присылает ни денег, ни писем. Я всё равно хожу по четвергам и сижу на скамеечке. Мне семьдесят лет, и я прошу вас вот о чём: когда придёт мой срок, положите меня рядом с мисс Эйнсли и протяните мне в руку второй шнур от её колокольчика. Звонит она теперь совсем тихо. Кто-то должен ей отвечать, а вас, простите, она не знает. Джаспер, сторож."},{"id":"crypt_088","kind":"note","title":"Список на рынок","text":"Мука, соль, два яйца. Нитки чёрные. Табак для Джона (зачёркнуто). Свечи. Масло, если будет недорого. Табак для Джона (зачёркнуто). Купить всё-таки табак, немножко, и насыпать в его кисет: мне нравится, когда в доме так пахнет."},{"id":"crypt_089","kind":"note","title":"Письмо Нату","text":"Нат, я вернулся. Вчера я сошёл с повозки у кладбища и первым делом увидел камень со своим именем, а на нём свежие цветы. Семь лет прошло, и ты написал мне правду: Нэнси вышла за мельника, у них двое, и младшего зовут как меня. Я постоял за оградой и видел, как она пришла и подмела у камня. Выглядит она хорошо. Утром я уеду, брат, и прошу тебя молчать. Присмотри, чтобы мельник её не обижал."},{"id":"crypt_090","kind":"note","title":"Жалоба преподобного","chain":"crypt_goose","part":1,"text":"Господин смотритель, в среду на кладбище меня укусила за ногу гусыня. Я шёл утешать семью Хопвудов, а вместо этого сидел у них на кухне с мокрой тряпкой на икре. Вдова Фрай сказала мне, что птицу зовут Беатриса, что покойный муж кормил её с руки и что с тех пор она ходит навещать его могилу. Вдове я сочувствую, но прошу убрать птицу с освящённой земли. Она ждала меня за часовней, смотритель, и я уверен, что нарочно. Преподобный Лоуэлл."},{"id":"crypt_091","kind":"note","title":"Погодная книга","text":"Третье марта: дождь, ветер с запада. Четвёртое: дождь. Пятое: ясно, на рассвете умерла Элен. Шестое: ясно. Седьмое: ясно и тепло, соседи вывесили бельё. Восьмое: опять ясно, и я этого не понимаю. Девятое: ясно. Десятое: наконец пошёл дождь, я вышел и постоял под ним во дворе. Элен посмеялась бы над этой записью. Одиннадцатое: дождь."},{"id":"crypt_092","kind":"note","title":"Уведомление","text":"Канцелярия кладбища напоминает, что срок аренды места номер сто семнадцать, девяносто девять лет, истёк. Родне покойной Лилли Пай, шести лет, следует оплатить продление либо освободить участок. Отметка канцелярии: родни не найдено, эту фамилию в городе уже никто не носит. Ниже рукой писца: продление оплачено, одна монета, из моих. Не спрашивайте зачем, господин смотритель, моей девочке тоже было шесть. Плательщиком запишите семью Пай."},{"id":"crypt_093","kind":"note","title":"Последняя записка","chain":"crypt_second_wife","part":4,"text":"Изабель, я принесла его к вам. Оливер лежит теперь рядом с вами, а с другой стороны от него смотритель оставил место мне, так что он у нас посередине и никуда не денется. Пока меня нет, присматривай за ним: он мёрзнет и врёт про лук. Варенье я дописала сама, с цедрой получается лучше. В воскресенье я приду, и мы посидим втроём."},{"id":"crypt_094","kind":"note","title":"Старому другу","text":"Мортимер, ты упрямый осёл. Лекарь дал мне две недели, и я не собираюсь тратить их на то, чтобы дуться из-за той лошади. Лошадь была хромая, и я это знал, когда её тебе продавал. Вот, я это написал, и теперь тебе не на что жаловаться. Приезжай до понедельника и ругайся лично. Если ты явишься только на похороны и встанешь там с постным лицом, я тебе этого не прощу. Бренди у меня осталось. Я хочу увидеть твою глупую физиономию, вот и всё. Рэндольф."},{"id":"crypt_095","kind":"note","title":"Порядок процессии","text":"Городской совет разрешает пронести гроб с телом бакалейщика Гиббонса через рынок, как он просил в завещании, и остановиться напротив лавки бакалейщика Фогга на время одной молитвы. Покойный просил читать её медленно. Они сбивали друг другу цены сорок лет, и совет просит господина Фогга не устраивать сцен. Приписка клерка: господин Фогг снял шапку, закрыл лавку и пошёл за гробом до самого кладбища, ругая покойного всю дорогу, и обратно его вели под руку."},{"id":"crypt_096","kind":"note","title":"С посылкой","text":"Розамунд, вот твои три ложки, я завернула их в ту салфетку, которую ты любила. Три я оставила себе. Седьмую я вложила маме в руки, когда никого не было: разделить её нельзя, а спорить над ней я больше не могу. Ты написала, что мне всегда доставалось лучшее, и в письме я на это отвечать не буду. Приезжай к празднику и привези свои ложки, потому что на шестерых мне своих не хватит, а тесто я уже поставила."},{"id":"crypt_097","kind":"note","title":"Доклад совету","chain":"crypt_goose","part":2,"text":"Докладываю совету, что за прошлый месяц ни один из вставших восточного ряда не вышел за ограду. Покойный Брукс дошёл было до калитки, но встретил там гусыню вдовы Фрай и бежал обратно так, как не бегал при жизни, а ведь он служил гонцом. Теперь у ворот тихо, и жена моя впервые за два года спит ночью. Прошу выделить на птицу мешок зерна в месяц и запретить преподобному на неё жаловаться. Вдова Фрай плачет от гордости и спрашивает, будет ли жалованье."},{"id":"crypt_098","kind":"note","title":"Просьба вдовы","chain":"crypt_goose","part":3,"text":"Господин смотритель, Беатриса умерла ночью, ей шёл двадцать третий год. Я знаю, что птице не положено лежать на кладбище, но прошу вас положить её в ногах у моего мужа. Он разговаривал с ней больше, чем со мной, и я не сердилась: она, в отличие от меня, его слушала. Вдова Фрай. Ниже рукой смотрителя: положил сам, ночью, и сверху посадил мяту. Восточному ряду об этом пока ничего не известно, и я прошу всех, кто это прочтёт, держать язык за зубами."},{"id":"crypt_099","kind":"secret","title":"Два кольца","text":"Кора, сегодня мы с нашим Питом вышли ниже нашего ряда на чужую дверь, целую, в старой стене. На двери два кольца: одно где положено, а второе внизу, на высоте Питова живота. Кто-то прибил его для ребёнка, чтобы тот мог стучать сам. Пит постучал в нижнее, я не успел его остановить. Никто не вышел, и слава богу. Тогда Пит сказал двери спасибо, и мы пошли обратно. Я вот думаю сделать ему такое же у нас. Домой буду к ужину."},{"id":"crypt_100","kind":"secret","title":"Старый список","text":"Список тех, кто понесёт огонь на новое место, если придётся уходить. Улица кузнецов несёт в первую смену, улица ткачей во вторую. Жаровню держат двое и меняются через каждые сто шагов. Детей вперёд не пускайте, они могут оступиться. Жаровню не роняйте, что бы ни случилось у вас за спиной. Ниже другой рукой: старик сказал, что последний отрезок пронесёт сам, как и в прошлый раз. Мы спросили, какой прошлый раз он имеет в виду, а он попросил подбросить дров."},{"id":"crypt_101","kind":"secret","title":"Для себя","text":"Мисс Гленн и мисс Хейл прожили в одном доме пятьдесят один год, и никто в городе не видел одну без другой. Мисс Хейл умерла первой. Когда умерла мисс Гленн, племянники положили её в семейный ряд, на другом конце кладбища, потому что так принято. Прошлой ночью мы с сыном перенесли её. Камень я оставил у племянников, они сюда всё равно не ходят. Пишу это, чтобы кто-нибудь знал, где она лежит. Сын спросил, зачем мы это делаем, а я велел ему держать фонарь повыше."},{"id":"crypt_102","kind":"secret","title":"Кого нашли","text":"Этих мы нашли сами, родни у них не было, и хоронил я их за свой счёт. Утопленника у мельницы я записал Джоном. Женщину с большой дороги записал Анной, как мою сестру. Мальчика из канавы записал Томасом, он был похож на Томаса. В книгу это не пойдёт, там для таких оставляют пустую графу. Я считаю, что совсем без имени лежать нельзя, и, когда иду вдоль ряда, здороваюсь с ними, чтобы имена не пропадали. Анна, ты извини, цветов нынче нет."},{"id":"crypt_103","kind":"secret","title":"При бутылке","text":"Отец Мэтью, это мой бренди, и я ставлю на бутылке метки. Симон. Ниже: Сын мой, метки ты ставишь криво, а ночи на кладбище холодные. Ниже: Так я и знал, что это вы! Я на вас в обиде, отец. Ниже: Приходи в четверг и садись рядом, я принесу сыр и расскажу, отчего не сплю. Ниже: В четверг приду. Сыра возьмите побольше. Метки я больше ставить не буду."},{"id":"crypt_104","kind":"secret","title":"Под яблоней","text":"Преподобный сказал, что на освящённой земле им лежать нельзя, раз они не успели вздохнуть. Тогда я сама похоронила их под яблоней за оградой и назвала мальчика Дэвидом, а девочку Розой. Потом у нас родились ещё четверо, и все выросли на этом дереве. Две нижние ветки я зову Дэвид и Роза, и дети так и кричат друг другу: кто первый долезет до Розы. Откуда это, они не знают. Кто найдёт письмо, скажите эти имена вслух, пожалуйста, всего один раз."},{"id":"crypt_105","kind":"secret","title":"В гробу","text":"Тому, кто вскрыл эту крышку. Золота тут нет, сынок, я проиграл его давным-давно. Кольца тоже нет, оно с весны в закладе. Сапоги на мне ещё хорошие, можешь их взять, только носки оставь. Ты, наверное, устал, а ночь холодная, так что посиди немного и заколоти за собой как следует, потому что дует. И скажи матери, чем ты занимаешься. Я в твои годы своей не говорил и теперь жалею. Иеремия Бут, честный игрок."},{"id":"crypt_106","kind":"secret","title":"На сланце","text":"Тем, кто будет здесь копать. Когда-нибудь вам понадобится это место, я понимаю: людей становится больше, а земля не растёт. Подо мной лежит моя жена, Кэтрин Нэш. Меня зовут Уолтер, кости у меня самые обыкновенные, и меня вы можете подвинуть куда угодно, я возражать не стану. Её, пожалуйста, не трогайте. Она очень не любила, когда её будили. Простите за беспокойство, и удачи вам с вашим домом."},{"id":"crypt_107","kind":"secret","title":"Устав общества","text":"устав тайново общиства кладбищенских волков. 1 никому ни слова иначе будешь проклят. 2 взнос одно яблоко в неделю. 3 главный Дик потомучто у него есть ключ от сторожки. 4 кто струсит у склепа вейнов тот неделю носит за всеми палки. 5 Сэмми остаётся в общистве хотя он с зимы болел и теперь его нет. его место никому не занимать. его яблоко кладём на камень. Дик сказал что это правило самое главное и писать его надо большими буквами но у меня кончилось места"},{"id":"crypt_108","kind":"secret","title":"Признание повитухи","text":"Я, Нора Тилл, повитуха, пишу то, чего не скажу и на исповеди. В ночь большого снега я приняла двух детей. У госпожи Вейн родился мёртвый мальчик, а у её служанки живой, и служанка умерла к утру. Я положила живого госпоже в руки и сказала, что это её сын. Она назвала его Кристофером и тридцать лет на него не могла надышаться. Я видела, как он её хоронил и как плакал. Мне надо было кому-то сказать, и я сказала этой стене. Мне совсем не жалко, Господи."},{"id":"crypt_109","kind":"boss","title":"Список опечаток","text":"К тому двести седьмому. Страница 14: вместо «Элис Лонг, швея» следует читать «Элис Ланг, швея». Поднята для извинений, извинений не приняла. Страница 31: вместо «умер от лихорадки» следует читать «умер от лихорадки и тоски», как сообщила вдова. Поднят для внесения поправки, подтвердил и заплакал. Страница 40: опечатки не оказалось, шестеро подняты напрасно. Приписка писца: господин хранитель велел поднять всех упомянутых ещё раз, чтобы проверить, верно ли записаны извинения.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_110","kind":"boss","title":"Письмо матери","text":"Сынок, ты опять не приехал и, наверное, не обедаешь. Я нашла твою детскую тетрадку. Помнишь ту зиму, когда умер отец? Мы сидели на кухне, тётя сказала, что это случилось во вторник, а я сказала, что в среду, и мы так и не вспомнили. Ты тогда плакал сильнее, чем на кладбище, а потом завёл эту тетрадь и записывал, кто когда кашлянул. Я думала, что это пройдёт. Милый мой, мы все были рядом с ним, разве этого мало? Приезжай.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_111","kind":"boss","title":"Счёт канцелярии","text":"Совету для уплаты. За квартал мы израсходовали сорок бочонков чернил, девять тысяч перьев и двести фунтов воска. Лампы в архиве горят день и ночь, потому что господин хранитель считает невежливым допрашивать людей в темноте. Птичницы со всей округи жалуются, что у гусей не осталось целого крыла. На содержание поднятых средств не требуется, поскольку они не едят. Вдова Стокс всё равно носит им кашу, и за кашу никто не платит.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_112","kind":"boss","title":"Опросный лист","text":"Опросный лист поднятого. Имя: Джейн, а фамилию напишите сами, вы же всё знаете. Дата смерти: не помню. Причина смерти: устала. Вопрос: есть ли у вас замечания к записи? Ответ: кто кормит кур? Вопрос: просьба отвечать по существу. Ответ: у меня остались пять кур, а дочка не умеет собирать яйца. Вопрос: подтверждаете ли вы сказанное? Ответ: про кур подтверждаю. Решение: поднять повторно для уточнения причины.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_113","kind":"boss","title":"Подложная запись","text":"Господа, на мои письма вы не ответили, поэтому пишу в последний раз. Когда очередь дошла до буквы Т, я увидел в списке свою мать. Я взял перо и поставил у неё в графе «дата подтверждена», хотя её никто не спрашивал. С тех пор я поставил эту пометку ещё четыреста раз, по ночам и по порядку, как он нас учил. Пусть они полежат. Чернил на это уходит совсем немного. Писец Арно.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_114","kind":"boss","title":"Ответ совету","text":"Совет благодарит хранителя книги за долгую службу и просит сдать ключи от архива к первому числу. Ниже, ровным почерком: ваше письмо получено и подшито. В подписях членов совета отсутствуют точные даты. Обнаружено также, что ни один из членов совета в книге усопших пока не значится. Это упущение будет устранено. Ключи находятся там, где им положено находиться. Прошу господ сохранять спокойствие и не менять адресов.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_115","kind":"boss","title":"Благодарность","text":"Господин хранитель, я знаю, что о вас говорят в городе, и подписывать жалобу соседей я отказалась. Вы подняли моего Джейми для сверки, и я простояла рядом с ним целый час. Он сказал мне, куда дел перочинный нож, и назвал меня так, как называл маленьким. Ему было девятнадцать. Прошу вас поднять его ещё раз. Я могу заплатить и могу придумать вопросы, сколько понадобится: например, в котором часу он вернулся домой в тот четверг. Вы же любите точность. Вдова Кэрью.","boss":"boss_necro","floors":[3,4]},{"id":"crypt_116","kind":"boss","title":"На обороте","text":"Дорогой, отвечаю на всё сразу, потому что ты опять забудешь записать. Мне не холодно. Я поела, ты спрашивал. Я не сержусь, я сказала тебе это уже сорок раз, а ты киваешь, макаешь перо и спрашиваешь снова. На столе у тебя давно пора прибрать. Чернила стоят там, где ты их поставил, не ищи. А теперь положи перо и ляг, милый, ты совсем не спишь, и я из-за этого тоже не могу лечь. Твоя Мэрион.","boss":"boss_necro","floors":[3,4]},{"id":"flooded_001","kind":"note","title":"Смена адреса","text":"Почтовой конторе. Прошу вас письма для Долорес Хобб носить теперь на второй этаж, Тростниковая, дом 4, потому что первый этаж на лето заняла река. Стучите громче, я глуховата. Вашему мальчику передайте, что сапоги можно не снимать, полы у меня всё равно мокрые.","chain":"address_change","part":1},{"id":"flooded_002","kind":"note","title":"Смена адреса","text":"Почтовой конторе. Это снова Долорес Хобб. Я перебралась на чердак того же дома, и почтальону придётся подниматься по приставной лестнице. Третья перекладина гнилая, пусть мальчик бережёт ноги, он у вас хороший. Посылку от племянника прошу не мочить, там чай, а племянник у меня один и вспоминает обо мне раз в год.","chain":"address_change","part":2},{"id":"flooded_003","kind":"note","title":"Смена адреса","text":"Почтовой конторе. Долорес Хобб живёт теперь на крыше того же дома, от трубы налево. Я спускаю корзину на верёвке, кидайте письма с лодки прямо в неё. Ваш мальчик бросает плохо, вчерашнее письмо утонуло, и я так и не узнала, родила ли моя внучка Мэг. Я всю ночь не спала. Напишите ей, пожалуйста, чтобы прислала ещё раз, и пусть мальчик в этот раз прицелится.","chain":"address_change","part":3},{"id":"flooded_004","kind":"note","title":"Смена адреса","text":"Почтовой конторе от Долорес Хобб. Больше письма носить не надо, племянник всё-таки вспомнил обо мне и забирает на холм. Мальчику вашему спасибо за старание. Если придёт письмо от Мэг, перешлите его. А если Мэг приедет сама и станет искать дом четыре, скажите ей, что дом стоит на месте, просто теперь пониже, а бабушка ждёт её на холме и уже вяжет крошечные носки.","chain":"address_change","part":4},{"id":"flooded_005","kind":"note","title":"Жалоба","text":"Портовому совету от Гектора Брандта, торговца солью. В моём подвале лежало сорок мешков соли. Теперь там лежат сорок мешков. Соль ушла в реку без разрешения и без оплаты. Прошу взыскать с реки двести монет. Жена велит мне успокоиться. Я спокоен, я просто пишу жалобу.","chain":"salt_claim","part":1},{"id":"flooded_006","kind":"note","title":"Ответ совета","text":"Господину Брандту. Совет вам искренне сочувствует. Иск к реке мы сможем принять, как только вы укажете её постоянное место жительства. На сегодня река проживает в том числе и в здании совета, поэтому заседание откладывается. Вашей супруге совет кланяется и просит её приглядеть за вами.","chain":"salt_claim","part":2},{"id":"flooded_007","kind":"note","title":"Вторая жалоба","text":"Совету от Гектора Брандта. Извольте, вот место жительства реки: Рыбная улица, Кожевенная улица, моя лавка и ваше здание. Прошу также учесть, что сельдь у причала теперь продают уже солёной, без моего согласия. Соль эта моя, и я требую долю с каждой селёдки. Жена сказала, что я смешон. Прошу приобщить к делу, что она эту селёдку тоже ест.","chain":"salt_claim","part":3},{"id":"flooded_008","kind":"note","title":"Объявление","text":"Рассол высшего качества! Отборная вода с Рыбной улицы, настоянная на сорока мешках лучшей соли. Монета за ведро, ведро приносите своё. Черпаю сам, прямо из окна. Г. Брандт и сын. Сын просит добавить, что ему стыдно. Отец просит добавить, что сын ест его хлеб.","chain":"salt_claim","part":4},{"id":"flooded_009","kind":"note","title":"Записка в ведре","text":"Мэйбл, раз улица теперь внизу, я перекинул верёвку от моего окна к твоему. Видишь ведро? Тяни его к себе, в нём пирог. Он с угрём, потому что теперь всё с угрём, но пёк я его сам и всё время думал о тебе, так что ешь и не морщись. Тоби из дома напротив.","chain":"rope_bucket","part":1},{"id":"flooded_010","kind":"note","title":"Записка в ведре","text":"Тоби, пирог мы съели. Отец спрашивает, кто его прислал, и я сказала, что ветром надуло. Верёвка у тебя провисает, ведро черпает воду, и твою последнюю записку я разбирала целый час. Разобрала всю, даже то, что ты зачеркнул, и мне понравилось. Подтяни верёвку со своей стороны, пожалуйста.","chain":"rope_bucket","part":2},{"id":"flooded_011","kind":"note","title":"Записка в ведре","text":"Мэйбл, я подтянул, сколько смог. Узел теперь на чердачном окне, потому что ниже привязывать уже не к чему. Завтра мы с отцом разбираем крышу на плот, так что ты, пожалуйста, не отвязывай свой конец, что бы ни случилось. Я приплыву за ним сам. То, что я зачеркнул, было правдой. Пришлю ещё пирог, если найду муку.","chain":"rope_bucket","part":3},{"id":"flooded_012","kind":"note","title":"Записка в ведре","text":"Тоби, твоего дома не видно с пятницы, и плота твоего тоже. Верёвка уходит прямо в воду, но я её не отвязываю, ты же просил. Сегодня я вытянула ведро, и в нём лежали раковина и горсть ила. Отец говорит, чтобы я отошла от окна и поела. Опускаю тебе пирог с луком, ты такой любишь. Если это ты, потяни за верёвку.","chain":"rope_bucket","part":4},{"id":"flooded_013","kind":"note","title":"Наказ ученику","text":"Наказ первый, Робин, и запомни его, пока я добрый. Над Кожевенной улицей сети не бросай, они цепляются за вывески. Лучше всего ловится над лавкой Пегги, она всегда держала в подвале сыр, и рыба это помнит. Если зацепишь флюгер, дёргай вбок. Нож не доставай, сеть дороже флюгера. И не вздыхай, отец твой тоже всё путал, а рыбак вышел неплохой.","chain":"fisher_lessons","part":1},{"id":"flooded_014","kind":"note","title":"Наказ ученику","text":"Наказ второй, Робин. Если попалось что-нибудь, что не рыба, клади в ящик на корме и записывай, над чьим домом ты это взял, потому что на берегу люди спрашивают. Ложки свои Кобб забрал и плакал. Сапоги тоже забрал. Портрет тётки брать отказался наотрез, так что вези его обратно и опусти, где нашёл. Вещи людям отдавай без денег, у них больше ничего не осталось.","chain":"fisher_lessons","part":2},{"id":"flooded_015","kind":"note","title":"Наказ ученику","text":"Наказ третий, Робин, и матери твоей об этом ни слова. Над домом Уинтеров сети не бросай. Вытащишь, а рыба в сети уже выпотрошена и лежит ровно, головами в одну сторону, как складывала её покойная хозяйка. Есть такую рыбу или нет, решай сам. Я ел. Госпожа Уинтер всегда чистила рыбу лучше всех на улице, и у меня не хватило духу её обидеть.","chain":"fisher_lessons","part":3},{"id":"flooded_016","kind":"note","title":"Школьный журнал","text":"Школа госпожи Стерн. Занятия я перенесла на баржу. Присутствуют одиннадцать детей. Тема урока: реки нашего края. Дети справедливо указали, что река теперь одна и что она везде. Оценки я поставила всем, неделя у них и так была плохая.","chain":"school_barge","part":1},{"id":"flooded_017","kind":"note","title":"Школьный журнал","text":"Присутствуют девять детей, двое уехали с родителями на холм, и я этому рада. Тема: счёт. За ночь баржу снесло за мельницу, и Оливер спросил, считается ли это прогулом у всей школы сразу. Я поставила ему отметку за логику и оставила без обеда. Потом отдала ему свой.","chain":"school_barge","part":2},{"id":"flooded_018","kind":"note","title":"Школьный журнал","text":"Присутствует Оливер. Тема: чистописание. Когда он не спешит, то пишет очень хорошо. Отец обещал приплыть за ним в среду, а сегодня пятница. Завтрак мы разделили пополам. Он спросил, зачем я веду журнал для него одного, и я сказала, что так положено. Уроки будут идти, пока светло, чтобы он поменьше смотрел на воду.","chain":"school_barge","part":3},{"id":"flooded_019","kind":"note","title":"Метка на двери","text":"Здесь стояла вода в год большого сома. А здесь в год, когда Кейт вышла замуж и мы плясали на столах, чтобы не промочить ноги. Эту отметку отец сделал прошлой весной. Дальше дверь кончается, так что следующую, братец, будешь делать на втором этаже. Я свою очередь отработал."},{"id":"flooded_020","kind":"note","title":"Рост Пенни","text":"Пенни шесть лет. Пенни семь лет. Весной вода дошла Пенни до колена. Пенни восемь лет. Осенью вода дошла ей до пояса, и она сказала, что вода растёт быстрее и это нечестно. Пенни девять лет, отмечал уже на чердачной балке, потому что косяк теперь внизу. Ростом она пошла в отца, чем отец очень гордится."},{"id":"flooded_021","kind":"note","title":"Правила парома","text":"Не вставайте, пожалуйста. Скот заводите по одному. Плакать можно, петь только с разрешения кормчего. Покойников мы везём по полной цене, места они занимают столько же, и родня пусть на нас не обижается. Мокрые монеты принимаем, мокрые расписки нет."},{"id":"flooded_022","kind":"note","title":"Рецепт","text":"Щуку, дочка, готовь так. Сними чешую и вспори брюхо. Кольца, ложки и пуговицы из брюха складывай в миску у двери, вдруг хозяева придут спрашивать. Потом туши с луком час. Соль клади осторожно, соль нынче дорогая, а твой отец всё равно скажет, что недосолено."},{"id":"flooded_023","kind":"note","title":"Детской рукой","text":"сиводня мы ловили рыбу из окна спальни. папа сказал что теперь можно спать в лотке. ура. мама плакала и сказала что это изза лука. а у нас нет лука"},{"id":"flooded_024","kind":"note","title":"Ответ сборщику","text":"Сборщику податей. Вы прислали мне счёт за уборку Рыбной улицы. Рыбная улица лежит на глубине двенадцати футов. Я оплачу его, как только увижу там метлу и человека при ней. Вашей матушке поклон, мы с ней вместе ходили в школу, и считать она тоже не умела."},{"id":"flooded_025","kind":"note","title":"Объявление","text":"Утерян мост, каменный, с тремя пролётами. В последний раз его видели в четверг у Рыбных ворот. Нашедшего просят сообщить старосте, он сорок лет ловил с этого моста рыбу и очень тоскует. Гильдия паромщиков просит не сообщать."},{"id":"flooded_026","kind":"note","title":"Приказ цеха","text":"Приказ цеха рыбаков. Сети на Главной улице ставьте только по чётным дням. По нечётным там ходят свадебные лодки, и невесту Дженкинсов уже дважды вытаскивали вместе с уловом. Жених передаёт, что в третий раз заберёт её вместе с рыбой, и рыба пойдёт на свадебный стол."},{"id":"flooded_027","kind":"note","title":"Записка жене","text":"Энид, ты сказала, что уедешь к матери, как только вода дойдёт до порога. Третий год я каждую весну подкладываю под порог по кирпичу. Если дверь стала открываться туже, это от сырости. Пишу и прячу за печку, потому что вслух у меня не выйдет: я не хочу, чтобы ты уезжала."},{"id":"flooded_028","kind":"note","title":"Молитва","text":"Госпожа река, подвал возьми, раз уж взяла. Забор Кобба тоже можешь взять, забор всё равно плохой, а Кобб тридцать лет должен мне за курицу. Лестницу оставь, у меня колено. И прости, что я в тебя выливала. Самого Кобба, если можно, не топи, а то кто мне отдаст за курицу."},{"id":"flooded_029","kind":"note","title":"Надгробие","text":"Здесь лежит Гарольд Мосс, добрый муж. Сначала он лежал в саду, потом, когда сад залило, мы с соседями перенесли его на чердак, а теперь на крышу, к трубе, там теплее. Гарольд, не обижайся, что всё так наспех, спина у меня не новая. Я скучаю."},{"id":"flooded_030","kind":"note","title":"Расписка","text":"Я, Барт Квилл, взял у Джудит Фенн лодку на одну ночь, чтобы сплавать за бумагой, которая подтверждает, что дом на Мельничной улице мой. Бумагу я нашёл, а дома нет. Лодку верну в воскресенье, а бумагу могу оставить в залог. Джудит, не смейся, бумага очень хорошая, на ней есть печать."},{"id":"flooded_031","kind":"note","title":"Задача","text":"Задача. Вода прибывает на ладонь в день. До крыши осталось двенадцать ладоней. Сколько дней осталось Томасу? Решение ученика: Томас умеет плавать, это мой брат, и я сам его научил. Учитель: ответ принят с радостью, но перепиши и покажи действия."},{"id":"flooded_032","kind":"note","title":"Шутка","text":"Записал за Рори в таверне, чтобы рассказать жене, она любит про старост. Сколько старост нужно, чтобы объявить наводнение? Двое: один пишет приказ, а другой держит его за воротник над водой."},{"id":"flooded_033","kind":"note","title":"Кто черпает","text":"Кто вычерпывает воду: в понедельник Дагган, во вторник Дагган, в среду жена Даггана, в четверг Дагган, в пятницу Дагган. В субботу Дагган просит пересмотреть список. Напоминаю Даггану, что список он составил сам, на спор со мной, и спор этот проиграл. Твоя жена."},{"id":"flooded_034","kind":"note","title":"Новому гребцу","text":"Кто садится с сундуком, с того бери деньги вперёд. Кто всю дорогу смотрит за борт и молчит, того сажай на корму, поближе к себе, и денег с него не спрашивай. Кто спрашивает, сколько ещё плыть, тому говори, что скоро. И будь с ними поласковей, сынок, у них сегодня плохой день."},{"id":"flooded_035","kind":"note","title":"Письмо","text":"Дорогая моя Лиззи ... мы перебрались к дяде на холм и взяли только самое нужное, но твоё свадебное платье так и осталось на столе ... не возвращайся за ним, слышишь? Вода уже дошла до второго ... я тебя очень прошу. Платье я сошью новое, а другой дочери у меня нет. Твоя мама."},{"id":"flooded_036","kind":"note","title":"Письмо","text":"Сын мой ... в лодке не оставалось места для деда, и я сказала ему, что следующая придёт утром. Он поверил и сел ждать на крыше с собакой ... каждый вечер я ставлю лампу на окно, которое смотрит в ту сторону ... не говори отцу, что следующей лодки не было."},{"id":"flooded_037","kind":"note","title":"Приказ старосты","text":"Всем жителям приказываю немедленно перейти на верхние этажи. Кто останется в подвале после ... заплатит штраф четыре монеты. Исключение делается только для ... и для гусей. Штраф я соберу лично, как только научусь плавать. Жена меня уже учит."},{"id":"flooded_038","kind":"note","title":"Список долгов","text":"Альберт, сынок, если я не вернусь, вот кому я давал деньги. Нед Оуэн должен девять монет, но он утонул, и с него не бери. Дик Рэй должен четыре ... с его вдовы не спрашивай, ей и без тебя ... Том Каррик должен две монеты и лодку, он ещё жив, спроси у ..."},{"id":"flooded_039","kind":"note","title":"Рецепт лекаря","text":"Марта, от кашля давай ему ложку мёда и ... три дня подряд, на ночь. Ни в коем случае не ... иначе я за него не отвечаю. Младшему давай половину. И поспи сама, ты третью неделю на ногах."},{"id":"flooded_040","kind":"note","title":"Вывеска цирюльника","text":"Брею на втором этаже. С лодки я больше не брею, потому что порезал уже двоих. Один из них мой шурин, он теперь со мной не разговаривает, и мне это нравится. Стрижка по старой цене, вода в тазу бесплатно."},{"id":"flooded_041","kind":"note","title":"Записка на лестнице","text":"Дети, ваши кровати теперь на чердаке. Вниз не ходите, вода стоит уже на пятой ступеньке, я вас очень прошу. Если снизу позовут ужинать, это не я. Я зову только с верхней ступеньки и всегда сначала говорю, что на ужин. Целую вас, мама."},{"id":"flooded_042","kind":"note","title":"Приглашение","text":"Роза Марлоу и Дункан Фэрроу приглашают вас на свадьбу в субботу у колокольни. Лодки привязывайте к южному окну. Гостей просим приплыть сухими, насколько получится. Подарки дарите только такие, что держатся на воде. Тётя Эдит, вас особенно просим не плакать, вода и так высокая."},{"id":"flooded_043","kind":"note","title":"От звонаря","text":"Колокол теперь бьёт сам, когда вода качает язык. Прошу не приходить ко мне с жалобами в три часа ночи. Я живу через улицу, и мне слышно лучше всех. Если вам не спится, приплывайте с вином, посидим и послушаем вместе, звонит он всё-таки красиво."},{"id":"flooded_044","kind":"note","title":"Поправка к плану","text":"Поправка к городскому плану. Улицу Сукновалов читайте теперь как пролив Сукновалов. Площадь Четырёх Ветров считайте заливом. Номера домов остаются прежние, просьба отсчитывать их от воды. Картограф просит передать жене, что к ужину не придёт, город всё ещё меняется."},{"id":"flooded_045","kind":"note","title":"Книга повитухи","text":"Мальчик, пять фунтов, родился на лестнице между вторым и третьим этажом, потому что ниже было мокро, а выше мы не дошли. Мать спрашивает, что писать в графе о месте рождения. Я записала: дом Трентов, пока что. Мальчик кричит громко, мать смеётся и плачет, и я вместе с ней."},{"id":"flooded_046","kind":"note","title":"Дневник","text":"Моя собака Бланш опять нырнула и принесла башмак. Все башмаки левые и все разные, а сегодняшний детский. Я складываю их у печи сушить и за каждый даю ей кусок рыбы, она так старается. Соседи говорят, что я странная, но никто из них пока не пришёл спросить, чьи это башмаки."},{"id":"flooded_047","kind":"note","title":"Книга сапожника","text":"Заказы на неделю. Кэмпбелл заказал сапоги до колена. Дюран заказал до бедра, чтобы было выше, чем у Кэмпбелла. Кэмпбелл заказал до пояса. Дюран теперь спрашивает, можно ли с рукавами. Они соседи и сорок лет друг с другом не разговаривают. Кожи у меня осталось на один заказ, и я боюсь решать, кому его отдать."},{"id":"flooded_048","kind":"note","title":"Обход домов","text":"Обход домов. В доме Кроули вода поднялась на три ступени, жильцы говорят, что пока терпимо. В доме Рена поднялась на девять ступеней, там тоже говорят, что пока терпимо. В доме Флинта вода стоит выше окон. Я постучал веслом по ставню, и изнутри мне сказали, что пока терпимо. Дальше я не поплыл. Старосте напишу, что все бодры."},{"id":"flooded_049","kind":"note","title":"Уведомление","text":"Жильцу Дойлу. Первый этаж я больше не сдаю по причине реки. Плату за него переношу на второй, так как дом у меня один. Прошу вас не присылать больше рыбу в счёт долга, у меня её полный коридор. Вы хороший человек и плохой жилец, и моя жена велит спросить, есть ли у вас сухие носки."},{"id":"flooded_050","kind":"note","title":"Детской рукой","text":"мы с вилом считаем сколько ступенек на леснице осталось до воды. вчира было девять сиводня восемь. вил говорит что вода тоже учится считать только назад. мама сказала хватит глупостей идите есть. а ночю я видел как она сама вышла со свечкой и считала"},{"id":"flooded_051","kind":"note","title":"Отчёт фонарщика","text":"Отчёт фонарщика. На Рыбной я зажёг четыре фонаря с лодки. На Кожевенной тоже с лодки, там остались одни верхние кронштейны. Ниже Кожевенной под водой горит ещё один, на углу у аптеки. Я его не зажигал. Масла он не просит, поэтому в отчёт его не вношу. Старая Мейзи из аптеки всегда просила меня не забывать про её угол, и по вечерам я подплываю с ним поздороваться."},{"id":"flooded_052","kind":"note","title":"Купчая","text":"Продан дом с садом на Мельничной улице господину Пру. Покупатель осмотрел сад с лодки, шестом, и претензий не имеет. Яблони плодоносят, со слов продавца. Продавец просил записать, что это был дом его матери и что ему очень жаль."},{"id":"flooded_053","kind":"note","title":"Что нести наверх","text":"Надо отнести наверх муку, одеяла, зеркало тёти и кровать деда. Дед пока идти не хочет, говорит, что у него внизу дела. Спросить его поласковее, какие там могут быть дела. Бабушкино кресло всё ещё стоит внизу, и он каждый вечер с ним разговаривает."},{"id":"flooded_054","kind":"note","title":"Записка библиотекарю","text":"Дорогая госпожа Брандон, возвращаю «Уход за садом» с опозданием в четыре года. Простите за вид. Сада у меня теперь нет, и дочитывать незачем. На странице сорок кто-то живёт, я его не трогала и вас прошу не трогать. Вы всегда были ко мне добры, даже когда я брала книги грязными руками."},{"id":"flooded_055","kind":"note","title":"Записка соседке","text":"Кэтрин, я тут родилась и никуда не поеду, так и скажи своему сыну, хотя спасибо ему, что волнуется. А вчерашний стул, будь добра, забери и принеси тот, что повыше, у этого вода уже дошла до сиденья. И приходи посидеть, я соскучилась."},{"id":"flooded_056","kind":"note","title":"Надпись на стене","text":"Здесь был Рори Гленн. Вода здесь была уже потом."},{"id":"flooded_057","kind":"note","title":"Из бутылки","text":"Нас девять на колокольне, дядя Арчи десятый, но он спит. Если найдёшь это письмо, пришли лодку. Если лодки нет, пришли соли. Рыбу без соли есть уже никто не может, и мы начинаем ссориться. Моя жена третий день не разговаривает со своей сестрой, и за это я реке благодарен, но соли всё равно пришли."},{"id":"flooded_058","kind":"note","title":"Рынок на крышах","text":"По четвергам рынок проводится на крышах. Мясной ряд идёт от дома Гиббса до трубы Кейна, а овощной стоит на сарае вдовы Тейт, пока сарай держит. Просим покупателей не заглядывать в слуховые окна, там живут люди. Вдове Тейт от всего рынка спасибо и пирог."},{"id":"flooded_059","kind":"note","title":"Жалоба старосте","text":"От Поттеров с третьего этажа. Соседи снизу поют по вечерам. Соседей снизу нет с апреля, они уехали к родне, и я сам помогал им грузить сундуки. Поют они неплохо, но всё одно и то же, и моя жена начала подпевать. Прошу принять меры, пока она не выучила второй куплет."},{"id":"flooded_060","kind":"note","title":"Дневник","text":"Купил гуся. Дорого, и кормить его нечем. Дома все третью неделю ходят мокрые и злые, а он плавает по кухне и разговаривает. Дочка сегодня смеялась, впервые за месяц. Ему хорошо, пусть живёт."},{"id":"flooded_061","kind":"note","title":"Альманах","text":"Весна ожидается сухая, лето жаркое, реки мелкие. От издателя: приносим извинения, типография переехала на чердак, и тираж подмочен. Исправления выйдут, как только найдётся наш наборщик. Альфред, вернись, мы на тебя не сердимся."},{"id":"flooded_062","kind":"note","title":"Протокол собрания","text":"Собрание квартала Тростника решило на холм не переезжать, потому что земля там дорогая, а родня противная. Будем надстраивать. Каменщик Кейн говорит, что этаж в год выдержит любой дом, если не жалеть раствора. Голосовали поднятием рук, Кейн поднял обе. Родня с холма прислала сказать, что всё слышала и ждёт нас к ужину."},{"id":"flooded_063","kind":"note","title":"На двери","text":"Ворам. Внизу брать нечего, всё наверху. Наверху живём мы, нас шестеро, и у всех есть вёсла. Бабушка просила написать, что у неё весло самое большое."},{"id":"flooded_064","kind":"note","title":"Объявление","text":"Продаю дело водоноса: два ведра, коромысло и постоянных покупателей на Рыбной улице. Причина продажи видна из окна."},{"id":"flooded_065","kind":"note","title":"Записка капитана","text":"Последняя лодка на холм отходит с рассветом. На доске я написал, что завтра будет ещё одна. Завтра её не будет, и знаю об этом только я. Если сказать правду, у причала затопчут малых, поэтому детей я беру без очереди и слежу за этим сам. Пишу, чтобы это было хоть где-то сказано."},{"id":"flooded_066","kind":"note","title":"Распоряжение","text":"Приказываю перенести огонь с площади на второй этаж ратуши, а когда вода дойдёт и туда, на чердак. Старик, который смотрит за углями, просит сухих дров. Сухих дров нет. Выдайте ему хотя бы стул, и пусть уже не просит. Я знаю, что он устал, он сидит там столько, сколько я себя помню."},{"id":"flooded_067","kind":"note","title":"Счёт из таверны","text":"Шкипер Дарби, «Сухой угол», второй этаж. Шесть кружек эля и сельдь. Дверь под водой, поэтому ушёл ты через окно и разбил его. Потом вернулся через окно и выпил ещё две кружки. Окно пишу один раз, оно уже было разбито. Дарби, родной, заплати, я же знаю твою мать."},{"id":"flooded_068","kind":"note","title":"Отцовский наказ","text":"Сын, соль пробуй языком, весам не верь. Речные торговцы кладут в неё песок, горные мел, а дядя твой кладёт и то и другое и ещё обижается. За солью к нему не ходи. На похороны его сходи, он всё-таки мой брат, и я его любил, хоть ни разу ему этого не сказал."},{"id":"flooded_069","kind":"note","title":"Письмо жениху","text":"Господину Тиму Арно. Вы просите руки нашей Лоры. У речных так: сначала дядя осмотрит днище вашей лодки, потом тётя посмотрит ваши зубы. Если дядя останется доволен, зубы смотреть не будем. Лора велела добавить, что лодка у вас хорошая, а откуда она это знает, мы с ней ещё поговорим. Её мать."},{"id":"flooded_070","kind":"note","title":"Дневник вдовы","text":"Чердак маленький, и вещей я взяла мало. Две миски зачем-то взяла. Свою разбила на лестнице и ем теперь из Рэндаловой. На донышке у неё вырезано: «Жена, добавки». Тридцать лет я её мыла и думала, что это царапины. Будет тебе добавка, дурак ты мой, когда увидимся."},{"id":"flooded_071","kind":"secret","title":"Промеры","text":"Брат, ты один у нас умеешь считать, проверь меня, я очень хочу ошибиться. Я сверил воду по Верхнему камню на холме, и сверил трижды. За десять лет река не поднялась ни на ладонь. Поднимаются только метки на наших дверях, по ладони в неделю. Выходит, река стоит на месте, а вниз едет весь город. Старосте я не докладываю, он только что заказал новые лестницы и впервые за год доволен."},{"id":"flooded_072","kind":"secret","title":"Записка в стене","text":"Тем, кто когда-нибудь построит дом у меня на крыше. Дубовая балка над южным окном цела, берите её, послужит ещё. Колодец на заднем дворе копать не советую, там наша кухня. В жестянке за кирпичом лежат кремень, трут и немного табака. Простите, если табак плох. Мы тут хорошо жили и желаем вам того же."},{"id":"flooded_073","kind":"secret","title":"Письмо внучке","text":"Дорогая моя, мой дед показывал мне записки своего деда. Там говорится про старика, который сидит при огне на площади, и горшок с углями у него такой же, как у нашего, и должен он всем в городе, точь-в-точь как наш. Я как-то спросила нашего старика, сколько ему лет. Он сказал, что дрова кончаются, и попросил подбросить. Спроси у него ты, он к тебе добрее."},{"id":"flooded_074","kind":"secret","title":"Тайный счёт","text":"Везём соль на север, без пошлины, в шести гробах, по два мешка в каждом. С нами едут трое плачущих, по монете на каждого. Тётя Мод плачет лучше всех, ей бы надо платить две. Седьмой гроб дядя велел взять с настоящим покойником, для вида. Покойнику тоже запишем монету, он хорошо держался."},{"id":"flooded_075","kind":"secret","title":"Записка ныряльщика","text":"Нырял за кольцом жены у Рыбных ворот, она плакала о нём целую неделю. Мостовая там обрывается, дальше идёт провал, и из него поднимается тепло, как от печки. Камни на краю старой работы, клейма на них чужие. Вода над провалом всё время мелко дрожит, как рука у того, кто долго несёт тяжёлое. Кольцо я не нашёл. Жене сказал, что нырну ещё раз, а сам боюсь."},{"id":"flooded_076","kind":"secret","title":"Клад","text":"сдесь лежит клад братства красной шапки. три пуговицы. зуб это мой. монета но не настоящая. кто возьмёт тот наш брат навсегда и должен положить ещё чтонибудь. мы уезжаем на холм. эмма плачет потомучто ей жалко но она сестра ей можно. присматривай за кладом пожалуста"},{"id":"flooded_077","kind":"secret","title":"Признание","text":"Отец Мартин, вслух я этого сказать не могу. Три года я рисовал на дверях следы воды, по медяку за метку, чтобы квартал получал пособие за потоп, которого не было. Выводил ровно, с потёками, и люди меня хвалили. В ту осень вода поднялась в точности до моих меток, дом за домом. Теперь соседи просят нарисовать им метки пониже, и я рисую. Скажите мне, пожалуйста, что это не я."},{"id":"flooded_078","kind":"secret","title":"Записка мужу","text":"Фред, ты думаешь, что я спустила деньги на шляпы. Шляпы сестрины. Деньги здесь, в этой жестянке, сорок две монеты на дом на холме. Я скажу тебе, когда наберётся пятьдесят, хочу посмотреть на твоё лицо. Если ты нашёл это раньше, положи обратно и сделай вид, что не находил."},{"id":"flooded_079","kind":"secret","title":"Записка крысолова","text":"Крысы ушли с Кожевенной за три недели до воды, все до одной, в сторону холма. Я взял с квартала плату и сказал, что это моя работа. На эти деньги я купил лодку. Никому об этом не говорил, даже жене. Лодка хорошая, и когда пришла вода, я вывез на ней всю Кожевенную и ни с кого не взял ни монеты. Может быть, теперь мы квиты."},{"id":"flooded_080","kind":"secret","title":"Про шкаф","text":"Сэм, ты мой лучший друг, поэтому говорю только тебе. Лестница за шкафом ведёт на чердак Мэттисов. Про неё знаем мы с Линдой и теперь ты. Тридцать лет мы ходили друг к другу, и муж её так и не понял, отчего у них пахнет моим табаком. Если встретишь её наверху, передай, что шкаф я отодвинул и вода туда не дошла. Пусть приходит, как раньше."},{"id":"flooded_081","kind":"boss","title":"Предание","text":"Паромщик брал по две монеты с головы. В ночь большой воды он не взял ни с кого и нагрузил лодку так, что она ушла на дно. Выплывшие говорили, что он держал её снизу, на спине, пока последний не вылез на крышу. На следующую ночь кто-то постучал снизу в борт чужой лодки, два раза, как монетами о дерево.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_082","kind":"boss","title":"Книга сборов","text":"Неделя перед паводком. Вдова Ларк с двумя детьми заплатила шесть монет, младшему я дал сушёной рыбы. Мясник с тушей заплатил четыре. Священник заплатил две и просил скидку от имени небес, я отказал. Старик с горшком углей обещал отдать две монеты на обратном пути и поехал в долг. Горшок он всю дорогу держал на коленях и грел руки, и за горшок я с него не взял.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_083","kind":"boss","title":"Книга сборов","text":"Ночь воды. Пишу, пока грузятся. От Рыбных ворот я перевёз сорок человек и платы не взял. С Кожевенной двадцать шесть, платы не взял. На Тростниковой сажаю, сколько влезает, и уже не считаю. Лодка моя берёт двенадцать, это я знаю лучше всех. Если эту книгу найдёт моя дочка, пусть знает, что долгов за этой ночью ни на ком нет и взыскивать ни с кого не надо.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_084","kind":"boss","title":"Показания","text":"Показания Агнес Ларк писарю квартала. Лодка пошла вниз, вода была мне уже по грудь, младшего я держала на руках, и тут под ногами стало твёрдо. Оно было шершавое и двигалось. Писарь просит уточнить, на чём я стояла. Я не знаю, на чём, но я стояла, и дети мои стояли. Писарь просит уточнить, отчего я плачу. Этого, милый, не записывайте.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_085","kind":"boss","title":"Детской рукой","text":"дяденька паромщик сказал садись не бойся. лотка утонула а мы неутонули. под нами было большое и скользкое. я постучал ему два раза чтобы сказать спасибо. мама говорит что я это придумал. а он мне тоже постучал","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_086","kind":"boss","title":"Записка рыбака","text":"Нелл, я сказал тебе, что рыба не идёт, но это неправда. Пишу, потому что вслух ты засмеёшься. Я вышел затемно к Мельничной, и снизу в борт постучали два раза, ровно, как монету на лавку кладут. Я сказал, что денег при себе нет. Оно подождало и постучало опять. Тогда я смотал сети и поплыл домой пустой. Дай мне завтра немного мелочи, родная, и ни о чём не спрашивай.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_087","kind":"boss","title":"Приказ гильдии","text":"Гильдия лодочников всем своим. На стук снизу не отвечайте. Монеты за борт не бросайте, касса и так пуста. Кто услышал стук, пусть запишется у старшины, чтобы мы понимали, где он сегодня ходит. За месяц записано тридцать один раз. Никто не пострадал, кроме Дэви, он упал со страху с собственной лодки. Дэви, мы за тебя переживаем, и верни багор.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_088","kind":"boss","title":"Письмо отцу","text":"Отец, я сделала, как ты велел: бросила за борт две монеты, за тебя и за мать, за ту ночь, чтобы вы никому не были должны. К утру обе лежали в лодке на скамье, мокрые, ровно положенные, и на одной была твоя зарубка. Стук был слабый, как будто он устал. Что с ними делать, я не знаю, пока держу в чашке. Береги спину и напиши мне, что думаешь.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_089","kind":"note","title":"Раздел дома","text":"Нотариусу Оуксу от Ансела Рида. Отец оставил нам с братом дом на Тростниковой, и мы наконец договорились. Нижний этаж с лавкой и хорошим сухим подвалом отходит мне, потому что я старший и умнее. Верхний этаж и чердак получает Пирс, раз уж он всю жизнь просидел наверху над своими книжками. Прошу оформить бумагу. Пирс передаёт, что старший ещё не значит умнее, но бумагу он подпишет.","chain":"house_split","part":1},{"id":"flooded_090","kind":"note","title":"Раздел дома","text":"Нотариусу Оуксу от Ансела Рида. Прошу пересмотреть раздел, потому что в моей половине вода стоит уже под самый потолок. Брат показывает мне договор и смеётся, а я пишу вам с его лестницы, куда он разрешил мне поставить сундук. За лестницу он хочет четыре монеты в месяц. Это мой родной брат, господин Оукс, мы с ним лежали в одной люльке.","chain":"house_split","part":2},{"id":"flooded_091","kind":"note","title":"Счёт брату","text":"Ансел, я всю ночь считал, и вышло, что за лестницу, за кухню и за угол, где спят твои дети, ты должен мне девятнадцать монет. Записываю это, чтобы ты не думал, будто я размяк. Если ты спросишь, отчего я вчера уступил Лотти свою кровать, то кровать скрипит, и она мне надоела. Долг можешь отдавать хоть сто лет, только не съезжай.","chain":"house_split","part":3},{"id":"flooded_092","kind":"note","title":"Раздел дома","text":"Нотариусу Оуксу от братьев Рид, пишем вдвоём, потому что перо у нас одно. Вода поднялась и в верхний этаж, и теперь нам обоим принадлежит только крыша, а про крышу в договоре ничего не сказано. Пирс считает, что крыша это верх. Я считаю, что надо делить заново и поровну, как хотел отец. Пирс согласен, но просит записать, что он согласился первым. Новую бумагу вышлите, пожалуйста, на холм, мы едем туда в среду на одной лодке.","chain":"house_split","part":4},{"id":"flooded_093","kind":"note","title":"Про закваску","text":"Хэтти, я уезжаю к сыну и оставляю тебе закваску. Она досталась мне от матери, а той от её матери, и ни разу за всё это время не умирала. Корми её мукой через день и держи в тепле, только не у самой печки, она этого не любит. Хлеб с неё выходит кислый, мой муж тридцать лет на него жаловался и ел. Не потеряй её, милая, кроме тебя мне некому её доверить. Бриджит Дин.","chain":"flooded_sourdough","part":1},{"id":"flooded_094","kind":"note","title":"Про закваску","text":"Госпожа Фиона, простите, что оставляю вам этот горшок, но мы уезжаем завтра, и лодка переполнена. В нём закваска Бриджит Дин. Она велела кормить через день, и я кормила, даже когда нам самим не хватало, только не говорите об этом моим детям. Я знаю, как дорого теперь стоит мука и о чём я вас прошу. Горшок тёплый, потому что я ношу его за пазухой. Вы всегда пекли лучше всех нас.","chain":"flooded_sourdough","part":2},{"id":"flooded_095","kind":"note","title":"Про закваску","text":"Госпожа Дин, вы меня не знаете, я Амос, сторож при барже с зерном. Ваша закваска попала ко мне через четвёртые руки вместе с запиской, а я никогда в жизни ничего не пёк. Вчера она вылезла из горшка и поползла по столу, и я за неё испугался. Напишите мне, пожалуйста, это значит, что ей плохо или что ей хорошо? Кормлю, как написано. Я к ней привык и по вечерам рассказываю ей, как прошёл день.","chain":"flooded_sourdough","part":3},{"id":"flooded_096","kind":"note","title":"Про закваску","text":"Господин Амос, закваска лезет из горшка, когда ей хорошо. Значит, вы ей нравитесь, чего мой покойный муж за тридцать лет так и не добился. Отделите половину и отдайте тому, кто голоден, а остальное кормите дальше. Я живу у сына на холме, тут пекут белый хлеб, мягкий и совсем без вкуса. Если будете проплывать мимо, привезите мне буханку. Я заплачу сколько скажете. Мы с мужем столько лет ругали этот хлеб, что теперь мне его очень не хватает.","chain":"flooded_sourdough","part":4},{"id":"flooded_097","kind":"note","title":"Смета дамбы","text":"Совету города от мастера плотин Корнелиуса Вейна. На каменную дамбу вдоль Рыбной набережной прошу четыре тысячи монет и два лета работы. Дешевле я не построю. Хамфри, ты мой шурин, и поэтому пишу тебе прямо: в этом году её ещё можно поставить, а в следующем я уже не обещаю. Передай сестре, что я приду в воскресенье.","chain":"dam_estimate","part":1},{"id":"flooded_098","kind":"note","title":"Ответ совета","text":"Мастеру Вейну. Совет ознакомился со сметой и нашёл её чрезмерной. На дамбу выделено четыреста монет. Корнелиус, не злись, половину этих денег я выбил у них сам, председатель хотел дать двести и благодарность. Построй что получится. Сестра ждёт тебя в воскресенье и просит не говорить за столом о реке.","chain":"dam_estimate","part":2},{"id":"flooded_099","kind":"note","title":"Отчёт Вейна","text":"Совету от Вейна. На четыреста монет я насыпал вал из земли и хвороста высотой мне по пояс, а каменщикам заплатил из своих. Прошу записать, что в обычную весну этот вал реку удержит, а в необычную удержит её примерно до завтрака. Хамфри, я сказал это на совете вслух, и ты сделал вид, что у тебя упало перо. В воскресенье я всё равно приду, потому что сестра тут ни при чём.","chain":"dam_estimate","part":3},{"id":"flooded_100","kind":"note","title":"Письмо шурину","text":"Корнелиус, вала больше нет, и совета, считай, тоже. Твою смету на четыре тысячи я нашёл у себя в столе и перечитал, пока вода поднималась по ступеням. Всё там было написано правильно. У меня не выйдет сказать тебе это за столом, поэтому пишу. Сестра велит передать, что в воскресенье обед будет на холме, у её тётки. Приди, пожалуйста. Я сяду с того края, откуда тебе будет удобнее меня не замечать.","chain":"dam_estimate","part":4},{"id":"flooded_101","kind":"note","title":"Про корову","text":"Гас, спасибо тебе ещё раз, что пустил мою Дейзи наверх, пока в хлеву вода. По лестнице она поднялась сама, я только морковку держал. Это на неделю, не больше. Молоко всё ваше, а ковёр я тебе возмещу. Ты настоящий сосед, я всегда так говорил, даже в тот год, когда ты зажилил мой топор.","chain":"cow_upstairs","part":1},{"id":"flooded_102","kind":"note","title":"Про корову","text":"Брэм, неделя давно прошла. Вверх по лестнице твоя корова идёт, а вниз упирается и кричит. Мясник сказал, что коровы так устроены и вниз по ступеням не ходят, и что ты об этом наверняка знал. Ты об этом знал, Брэм? Жена спит в кладовке, потому что в спальне стоит Дейзи. Я не жалуюсь, молоко хорошее, но приди и поговори с ней, она тебя слушает.","chain":"cow_upstairs","part":2},{"id":"flooded_103","kind":"note","title":"Про корову","text":"Гас, сегодня вода поднялась почти вровень с твоим окном, и я подогнал к нему плот. Дейзи шагнула на него сама, будто всю жизнь этого ждала, и теперь стоит и жуёт твою занавеску. Выходит, она всё-таки спустилась, хотя лестница тут ни при чём. За ковёр я всё ещё должен, и про пол тоже помню. Плыви с нами на холм, места хватит, а жену твою посадим на корму, подальше от Дейзи, они так и не помирились.","chain":"cow_upstairs","part":3},{"id":"flooded_104","kind":"note","title":"Письмо сестре","text":"Эстер, дорогая, к нам по распоряжению старшины подселили речных, шестерых, с бабкой и с сетями. Пахнет от них рыбой, а сети они развесили на моих розах. Я пересчитала ложки и спрятала хорошую скатерть. Старуха зовёт меня хозяюшкой, и я едва держусь. Пиши мне чаще, в собственном доме мне теперь не с кем поговорить.","chain":"hill_lodgers","part":1},{"id":"flooded_105","kind":"note","title":"Письмо сестре","text":"Эстер, ложки все на месте, я считала ещё два раза. Вчера их старик без спросу починил мне калитку, которую мой покойный Эдвин обещал починить одиннадцать лет. Я сказала ему спасибо, и вышло очень сухо. Дети у них тихие и никогда не просят есть, и это меня беспокоит. Скатерть я пока не достаю, но кашу теперь варю на всех, разом получается дешевле.","chain":"hill_lodgers","part":2},{"id":"flooded_106","kind":"note","title":"Письмо сестре","text":"Эстер, только не смейся, вчера мы со старухой просидели до полуночи. Её зовут Ида. Под водой у неё остался дом, где родились все её дети, а я всё это время жаловалась ей на розы. Она только сказала: «Ешь, хозяюшка, остынет». Сегодня я достала хорошую скатерть. Розы, кстати, стоят в бутонах, сети им, кажется, не повредили.","chain":"hill_lodgers","part":3},{"id":"flooded_107","kind":"note","title":"Письмо сестре","text":"Эстер, они уехали на север, к родне, там дают землю. Ложки все на месте, кроме одной, но её я нашла у себя в переднике. Дом стал очень большой и совсем тихий. Сети они оставили, старик обещал вернуться за ними весной, и я их пока не снимаю. Ида велела солить всё сильнее, чем я привыкла, и я солю. Приезжай, пожалуйста, хоть на неделю.","chain":"hill_lodgers","part":4},{"id":"flooded_108","kind":"note","title":"Колыбельная","text":"Сестра, ты просила записать, что я пою Элли на ночь. Спи, моя рыбка, вода подождёт, мама на лестнице песню поёт, папа с веслом у большого окна, завтра посмотрим, какая она. Раньше в этой песне была мельница, но Элли теперь спрашивает, где мельница, вот я и поменяла слова. Мотив ты знаешь от мамы. Если у тебя получится лучше, напиши."},{"id":"flooded_109","kind":"note","title":"Про голубей","text":"Нора, я перевёз голубей на холм, как ты велела, и построил им голубятню лучше старой. Ночуют они в ней, а утром летят домой. Я ходил на берег и смотрел: они кружат над тем местом, где стоял наш сарай, потом садятся на конёк церкви и ждут, пока я приплыву и дам зерна. Теперь я плаваю туда каждый день, и ты меня не ругай. Они не знают, что случилось, а объяснить им я не умею."},{"id":"flooded_110","kind":"note","title":"Просьба соседке","text":"Мириам, ты плаваешь мимо сада, сделай милость. Верхушка яблони Эдмунда ещё торчит из воды, и на ней висят три яблока. Сорви их, если дотянешься. Он посадил её в год нашей свадьбы, и я не хочу, чтобы они упали в воду, пока я тут сижу. Одно съешь сама, за работу, другое отдай своим детям, а третье привези мне. Я положу его на окно и есть не буду, пока оно пахнет."},{"id":"flooded_111","kind":"note","title":"Книга пари","text":"Пари на статую основателя. Хью Мейсон ставит две монеты, что вода дойдёт ей до пояса к жатве. Нэт ставит три на подбородок к зиме. Госпожа Пайл поставила монету на нос и просит не говорить мужу. Правнук основателя поставил пять на то, что вода остановится у колена, из уважения к предку, и уже проиграл. Половину я ему потихоньку верну, он хороший парень и у него ребёнок."},{"id":"flooded_112","kind":"note","title":"Объявление","text":"Всем жителям Кожевенной от аптекаря Ноэля. Из моего подвала ушли триста пиявок. Если вы нашли пиявку в сапоге, верните её в аптеку живой, я заплачу медяк. Особенно прошу поискать Амелию. Она крупная, с жёлтой полосой, двадцать лет работала со мной, а до того с моим отцом, и я не знаю, как без неё начинать утро. Детям скажите, что она спокойная."},{"id":"flooded_113","kind":"note","title":"Завещание","text":"Я, Эбенезер Твилл, в здравом уме, что бы там ни говорила моя жена, оставляю сыну лодку, дочери дом, если она его найдёт, а жене Марджори бессрочное право говорить, что она была права. Она была права насчёт лестницы и насчёт моего брата, а ещё насчёт холма, куда надо было переехать десять лет назад. Марджори, я всегда это знал, просто мне нравилось, как ты сердишься."},{"id":"flooded_114","kind":"note","title":"Правила приличия","text":"Племяннице Сесили о том, как теперь ходить в гости. Привязывать лодку к чужому балкону без приглашения неприлично, сначала покричи снизу. Мокрое весло оставляй снаружи. Если хозяйка живёт на крыше, не говори ей, что у неё хороший вид. В окно входи медленно и подавай руку тому, кто старше. Я понимаю, милая, что мир стал другой, и всё-таки вести себя мы будем прилично. Твоя мать сказала бы то же самое."},{"id":"flooded_115","kind":"note","title":"Пятно на потолке","text":"На потолке от сырости выступило пятно, очень похожее на мою свекровь. Те же щёки, и смотрит она так же, будто я пересолила. Сначала я его закрашивала, но оно проступает. На этой неделе я сказала ему, что суп сегодня вышел неплохой, а потом рассказала, как растёт Джозеф, она его очень любила. Муж говорит, что надо вывести пятно уксусом. Пусть выводит сам, я не буду."},{"id":"flooded_116","kind":"note","title":"На обороте рисунка","text":"это наш дом он внизу. это папа на лотке он гребёт. это рыба она лежит на маей кравати. а это солнце я нарисовала большое патамушто мама просила чтобы было посуше. мама павесила рисунок на чердаке и сказала что теперь гараздо теплее"},{"id":"flooded_117","kind":"note","title":"Сочинение","text":"Кем я буду. Когда я вырасту я буду паромщиком патамушто у него всегда есть денги и можно сидеть. Мой брат Хью хочет быть сухим. Учитель сказал что такой работы нет а брат сказал что тогда он будет сухим бесплатно. Мама сказала что мы оба будем кем хотим если доедим суп. Перси девять лет."},{"id":"flooded_118","kind":"note","title":"Письмо с юга","text":"Мама, служба моя кончается осенью, встречай меня на пристани у Рыбных ворот. Здесь на юге такая сушь, что у нас в полку трескаются сапоги, и я всё вспоминаю наш погреб, где пахнет яблоками. Поставь мой стул к окну, как раньше. На обороте другой рукой: адресата и улицы больше нет. Письмо я прочитал, простите, чтобы найти обратный адрес, и написал ему сам. Почтарь Джонас."},{"id":"flooded_119","kind":"note","title":"Брачное объявление","text":"Вдовец, пятьдесят два года, ищет жену. Имею лодку без течи, своё весло и все зубы, кроме двух. Рыбу умею готовить одним способом. От невесты желаю, чтобы она умела вычерпывать и говорила про покойного мужа не чаще, чем я про покойную жену. Спрашивать Оскара Лейна у Мельничной протоки. Ниже женской рукой: Оскар, это Нэн из дома напротив. Весло у тебя моё, но приходи в воскресенье, поговорим."},{"id":"flooded_120","kind":"note","title":"Красильщику","text":"Красильщику Ханту от прачек Кожевенной улицы. Твои чаны залило, и вода во всём квартале теперь синяя. Мы стираем в ней, потому что другой нет, и третью неделю бельё выходит голубым, а у судьи голубые даже воротнички. Судья грозит тебе судом, хотя жене его нравится. Мы тебя не виним, Хант, у тебя своё горе. Но если где-нибудь остался жёлтый, вылей его, пожалуйста, с того конца улицы, мы хотим зелёного."},{"id":"flooded_121","kind":"note","title":"Объявление","text":"Гробовщик Уэллс сообщает, что по нынешним обстоятельствам сдаёт гробы внаём как лодки, по медяку в час. Гробы просмолены на совесть и держат двоих, если эти двое не ссорятся. Крышка годится под стол. Просьба возвращать в чистоте, заказы на них никто не отменял. Господин Бёрк катается бесплатно, он заказал себе этот гроб ещё зимой, и я очень рад видеть его в нём живым."},{"id":"flooded_122","kind":"note","title":"Счёт живописца","text":"Госпожа Вейл заказала мне портрет своего дома на улице Сукновалов. Дома теперь не видно, поэтому она его описывала, а я рисовал. Окна она исправляла девять раз. Плющ велела убрать, а потом вернуть. На десятый день она сказала, что крыльцо вышло слишком красивое, и заплакала, и я оставил его таким. Беру только за краски. Передайте ей, что картина подсохнет к пятнице."},{"id":"flooded_123","kind":"note","title":"Рапорт","text":"Господин капитан, заключённого Фитча, взятого за кражу окорока, я перевёл из подвальной камеры к себе на третий этаж, другого сухого места у меня нет. Ест он с нами за столом. Срок его кончился в марте, но идти ему некуда, дом его стоял на Кожевенной. Жена вяжет ему шарф. Прошу оформить его ещё на полгода за что-нибудь небольшое."},{"id":"flooded_124","kind":"note","title":"К проповеди","text":"Заметки к воскресной проповеди. Про воду сегодня не говорить, все устали. Начать с терпения. Мельнику в глаза не смотреть, он знает, за что. Вдове Кларк сказать хорошее, и сказать при всех, пусть услышат. Служба идёт на барже, поэтому заканчивать надо засветло, а Барроу опять позеленеет, пусть садится ближе к борту. Сам тоже постарайся не вздыхать, старый дурак, на тебя смотрят дети."},{"id":"flooded_125","kind":"note","title":"Донесение","text":"Донесение пожарной дружины. В четверг загорелась крыша у Хейла на Тростниковой. Воды кругом было сколько угодно, но вёдра наши утонули ещё весной вместе с сараем дружины, и черпали мы шляпами. Старая Морли сняла с огня котёл и отдала его прямо с супом, другого у неё не было. Крышу мы отстояли. Теперь на чердаке у Хейлов пахнет луком, а сам Хейл каждый день носит ей рыбу."},{"id":"flooded_126","kind":"note","title":"Плита","text":"Здесь покоится Гертруда Пайк. Она говорила, что будет дождь. Ниже другой рукой: говорила, Труди, и не раз, а я всё равно вышел без шляпы."},{"id":"flooded_127","kind":"note","title":"Ищу мужа","text":"Ищу мужа. Джейкоб Тилль, сорок лет, рыжий, на подбородке шрам от моей сковороды. Ночью он храпит на три голоса, так что его ни с кем не спутаешь. В последний раз его видели на барже, которая шла к мельнице. Если найдёте, скажите ему, что я не сержусь за лодку и что место за столом я ему держу. Спрашивать Энн Тилль у церкви, каждый день после полудня."},{"id":"flooded_128","kind":"note","title":"Письмо матери","text":"Мать, ты спрашиваешь, на чём мы теперь живём. Я снял в доме все двери и сколотил из них плот. Вышел он широкий, а на ручках удобно сушить чулки. Дети поделили его по старым комнатам, и Дженни не пускает брата на дверь от своей спальни, так что он стучит, прежде чем перейти. Вчера он постучал, а она ответила, что её нет дома. Напиши, как твоя нога."},{"id":"flooded_129","kind":"note","title":"Расценки","text":"Расценки музыканта Брайса. Свадьба три монеты, похороны две. За вычерпывание воды беру четыре, потому что темп быстрый и играть приходится без остановки. Если заказчик хочет вычерпывать медленно и с чувством, цена как за похороны. С шапкой ходит моя жена, она лучше меня знает, кто сколько может дать, так что, если она взяла с вас меньше, не спорьте."},{"id":"flooded_130","kind":"note","title":"На стене церкви","text":"Кто оставил свой дом под водой, вешайте ключ на эту стену и подпишите улицу. Вода уйдёт, и вы его заберёте, а пока он хотя бы не потеряется. На сегодня ключей двести шесть. Госпожа Прайс приходит каждую субботу и протирает свой, и я прошу мальчишек над этим не смеяться. Вашего ключа никто не тронет, я слежу за этим сам. Пономарь Элиас."},{"id":"flooded_131","kind":"note","title":"Выдача хлеба","text":"Выдача хлеба, неделя седьмая. Семья Кэрроу. Жена Кэрроу говорит, что их семеро, считая бабушку. Бабушку хоронили весной, и я сам нёс гроб с правой стороны. Она знает об этом и знает, что я это знаю. Пока я записывал, она ни разу не подняла на меня глаз. Выдано на семерых."},{"id":"flooded_132","kind":"note","title":"Дневник Беатрис","text":"Весь город только и говорит что о воде, и ни один человек не заметил, что я постригла чёлку. Мама сказала, что нам сейчас не до чёлок. Джаспер вчера перевозил нас на лодке и посмотрел на меня два раза, я считала. Потом он сказал, что у меня мокрый рукав. Он заметил мой рукав! Наверное, жизнь моя всё-таки не кончена, хотя в доме и вправду очень сыро."},{"id":"flooded_133","kind":"note","title":"Партия","text":"Уолтер, твой ход. Доску я перенёс на чердак и ни одной шашки не тронул, спроси у Клары. Я знаю, что ты теперь на холме и что дочь не пускает тебя в лодку из-за сердца, так что пришли ход с почтой. Мы играем эту партию с зимы, ты её проигрываешь, и я хочу, чтобы ты дожил и увидел это сам. Твоя белая на правом краю стоит под боем, старый ты осёл. Я подсказал тебе, потому что скучаю."},{"id":"flooded_134","kind":"note","title":"Записка на столе","text":"Хильда, я от тебя ухожу, я так больше не могу, ты опять сказала про мою мать. Вещи я собрал. Отвези меня, пожалуйста, к причалу, когда закончишь, лодка у нас одна, а вёсла у тебя. Ниже её рукой: закончу к вечеру. Пока почини ставень, ужин на столе. Что я сказала про твою мать, то и повторю, когда приду."},{"id":"flooded_135","kind":"note","title":"Письмо дяде","text":"Дядя Уоррен, отец всё хуже понимает, какой нынче год. Он решил, что это наступление с юга, и выставил у лестницы стул и старую алебарду. Каждое утро я докладываю ему, что противник остановлен на шестой ступеньке, и он велит выдать людям по чарке. Людей у него двое, кот и я. Если соберётесь навестить, приходите с донесением и не заговаривайте про воду. Вчера он назвал меня лучшим сержантом своей роты, и я ушла плакать в кладовую."},{"id":"flooded_136","kind":"note","title":"Писано со слов","text":"Писано рукой писаря Хейвуда со слов госпожи Долл, которая заявляет о краже. Украдены корыто, две наволочки и кот Фрэнсис. Вор, по её словам, река. Я разъяснил, что река не может отвечать по суду, потому что у неё нет имущества. Госпожа Долл ответила, что теперь у неё есть корыто. Жалоба принята. Кот вернулся сам и, как уверяет госпожа Долл, претензий не имеет, о чём я тоже записал, чтобы она спала спокойнее."},{"id":"flooded_137","kind":"note","title":"Загадки","text":"Загадки для Энни, чтобы не скучала в лодке. Вошла без стука, села на все стулья и ни одного не подвинула. Кто это? Ног у неё нет, а на второй этаж поднялась. Кто это? Весь город её ругает, а она всё равно пришла ко всем в гости. Кто это? Ответ на все три один и тот же, я нарочно так сделал, чтобы ты отгадала. Скажи дедушке, как приедешь."},{"id":"flooded_138","kind":"note","title":"На двери","text":"Генри, суп стоит на крыше, ложка там же. Если вы не Генри, суп очень плохой."},{"id":"flooded_139","kind":"note","title":"Объявление","text":"Продаю лодку. Течёт только слева, а справа она очень хорошая. Сидите справа."},{"id":"flooded_140","kind":"note","title":"Квитанция","text":"Перевозчик Ройс принял две монеты за спасение тёщи господина Хэнкока с крыши на Мельничной. Господин Хэнкок при ней спросил, сколько я возьму, чтобы отвезти её обратно. Госпожа стукнула его шляпой, заплатила за него сама и сказала, что теперь он ей должен. Потом он всю дорогу держал её за руку, пока у старухи не перестали дрожать пальцы. Квитанция выдана ей."},{"id":"flooded_141","kind":"note","title":"Письмо Аде","text":"Ада, река встала! Третий день можно ходить по льду, и мы с Джеком ходили над Мельничной. Лёд там чистый, как стекло, и сквозь него видно нашу улицу и скамейку у ворот, ту самую, где ты заплетала мне косы. Дети катаются над ратушей и кричат. Я стояла там, пока не замёрзли ноги. Приезжай, пока не растаяло, я очень хочу тебе показать."},{"id":"flooded_142","kind":"note","title":"Письмо Луизе","text":"Луиза, ты спрашивала, как тут мама. На три дня воды стало меньше, и показалось наше крыльцо. Мама взяла тряпку и велела отцу везти её к дому. Она вымыла крыльцо и протёрла дверную ручку, а отец держал лодку и молчал. На четвёртый день вода вернулась. Мама сказала, что зато теперь там чисто. Пришли ей, если сможешь, тёплый платок."},{"id":"flooded_143","kind":"note","title":"Письмо брату","text":"Бен, приплыви и посмотри сам, потому что мне больше некому это сказать. В тихий вечер вода над нашей улицей отражает окна, а окон над ней никаких нет, только небо. В этом отражении у нас в кухне горит лампа, и мама накрывает на стол. Она поставила четыре тарелки, и твою тоже, ту, что со сколом. Я плаваю туда каждый вечер. Жене своей, пожалуйста, не рассказывай."},{"id":"flooded_144","kind":"note","title":"Наказ горничной","text":"Тесс, каждое утро, до того как встанет хозяйка, протирай лестницу. Следы там маленькие и босые, они поднимаются от воды до двери её спальни и тем же путём идут обратно. Хозяйка думает, что ночью у нас никто не ходит, и пусть думает, ей и без того тяжело после сына. Воду из-под тряпки выливай в окно, вниз не носи. Будь умницей, и спасибо тебе."},{"id":"flooded_145","kind":"note","title":"Для памяти","text":"Пишу для памяти, чтобы проверить себя. На плоту нас семеро: я, жена, трое детей, брат и тёща. Вечером я пересчитал, вышло восемь, и ни одного чужого лица. Утром снова семь. Поговорил об этом с кузиной Анной, и она сказала, что я устал и мне надо поспать. Жена спрашивает, с кем я разговариваю, потому что кузины у меня нет."},{"id":"flooded_146","kind":"note","title":"Старому другу","text":"Корбин, старый ты пират, тридцать лет я проходил по морям и поклялся больше никогда не видеть воды. Я нарочно купил дом как можно дальше от берега и посадил горох. Вчера мой горох уплыл. Смейся, я знаю, что ты смеёшься. Приезжай и привези табаку. Причал у меня теперь прямо у кровати, и сплю я, к своему стыду, намного лучше."},{"id":"flooded_147","kind":"note","title":"Сигналы","text":"Сигналы для нашего конца Тростниковой. Белая тряпка на шесте значит, что всё хорошо. Красная значит, что нужна лодка. Синяя значит, что есть лишний хлеб и можно приплыть. Жёлтая значит, что Марион опять поссорилась с мужем и ночует у сестры, и заплывать к ней с вопросами не надо. Жёлтая висит с понедельника. Марион, золотце, мы за тебя волнуемся, повесь хотя бы белую."},{"id":"flooded_148","kind":"note","title":"Джону Хоупу","text":"Джон, сорок лет назад ты позвал меня замуж, и я сказала, что пойду за тебя, когда река войдёт ко мне в дом. Ты очень обиделся и уехал ловить треску. Так вот, вчера она вошла и дошла до самой кухни. Я женщина слова. Мне шестьдесят два года, и у меня болят колени. Если ты ещё не передумал, приплывай."},{"id":"flooded_149","kind":"note","title":"Письмо жене","text":"Жена, пишу тебе с крыши, как обычно, только сегодня меня позвали на чай. Двадцать лет мне кричали снизу, чтобы я не топтал черепицу, а теперь вся улица живёт наверху и спрашивает у меня, куда ставить ногу. Госпожа Хэллоран, которая раньше и кланяться мне брезговала, назвала меня мастером и попросила глянуть её дымоход. Я знаю, что ты скажешь, и зазнаваться не стану. Но ты всё-таки расскажи об этом своей сестре."},{"id":"flooded_150","kind":"note","title":"Про попугая","text":"Попугая мне оставил Джеффри, он привёз его с юга. Говорит птица мало, зато голосом Джеффри, и чаще всего спрашивает, где его сапоги. Я отвечаю, что сапоги там же, где всегда, у печки, только печку мы перенесли. Дочь просит меня при людях с птицей не разговаривать. Вчера он сказал: «Мюриэль, иди спать», и я пошла."},{"id":"flooded_151","kind":"note","title":"Черновик речи","text":"Дорогие сограждане, мы стоим на твёрдой почве. (Гарри, про почву не надо.) Положение находится в моих руках. (В каких руках, ты вчера упал с лодки.) Совет принял меры. (Скажи какие.) Совет принимает меры. (Гарри, скажи им, что тебе тоже страшно, и садись. Я стою рядом, и у меня в кармане хлеб с сыром.)"},{"id":"flooded_152","kind":"note","title":"Рекомендация","text":"Бетси Ньюман прослужила у меня горничной одиннадцать лет. Гладит она посредственно, серебро после неё приходится перетирать, и вечно она поёт на лестнице. В ночь воды она вынесла через окно троих моих детей, одного за другим, и вернулась за старшим, хотя я кричала ей, чтобы не ходила. Кто возьмёт её на службу, пусть знает, что её первый год оплачу я. Я перед ней в долгу до конца своих дней."},{"id":"flooded_153","kind":"note","title":"Объявление","text":"Баня Хопкинсов закрывается. Люди перестали ходить, говорят, что и так мокрые. Я объясняю им, что мокрый и мытый это разные вещи, но спорить со всем кварталом у меня больше нет сил. Матушка держала эту баню полвека. Кто ходил к ней мальчишкой, приходите в субботу, я истоплю как следует и денег не возьму."},{"id":"flooded_154","kind":"note","title":"Заклад","text":"Госпоже Бейли от ростовщика Стоуна. Прошлой зимой ваш муж заложил у меня скрипку, чтобы заплатить лекарю за ваше лечение, и просил вам не говорить. Вас вылечили, а его, я слышал, не стало. Лавку я закрываю и уезжаю. Скрипку посылаю с этим мальчиком, а в книге долг вычеркнул. Ваш муж приходил каждый месяц, приносил по монете и ни разу не опоздал."},{"id":"flooded_155","kind":"note","title":"Наказ мужу","text":"Эдгар, я с детьми уезжаю вперёд, а ты приедешь в пятницу. Кашу надо мешать, иначе она пристанет, Эдгар, мешать всё время. Чистые рубашки лежат в верхнем сундуке, в нижнем они уже мокрые. Кошку не забудь. Дом ты всё равно не спасёшь, поэтому не сиди с ним до последнего, как ты умеешь. Я не сплю, когда тебя нет, ты об этом знаешь."},{"id":"flooded_156","kind":"note","title":"Письмо кузине","text":"Кузина, всё обошлось, и теперь уже можно смеяться. Дед улёгся спать в лодке у крыльца, потому что там, по его словам, воздух лучше. Ночью верёвка перетёрлась, и к утру его принесло к самой мельнице, за две мили. Он проснулся и спросил у мельника, кто передвинул мельницу и почему его не предупредили. Мы искали его полдня, мама успела выплакаться. Дед просит передать, что воздух там и правда лучше."},{"id":"flooded_157","kind":"note","title":"Письмо сыну","text":"Сынок, ты пишешь, что мальчишки на холме дразнят тебя лягушкой. Отвечай, что лягушка хотя бы умеет плавать. Драться нельзя, мать велела написать это первым делом. Она это прочитала и ушла к тесту, так что слушай: большой палец держи снаружи и бей первым. Мы очень по тебе скучаем. Ешь всё, что дают."},{"id":"flooded_158","kind":"note","title":"Письмо внучке","text":"Внучка, ты пишешь, чтобы я поскорее уезжала, потому что у нас наводнение. Мне восемьдесят один год, и я тебе скажу: разве это вода? Когда я была молодая, по Главной улице ходили корабли с парусами, а мой отец ловил с чердака осетров. И вода тогда была мокрее нынешней. Никуда я не поеду, пока не дождусь настоящей. Носки твои пришли, спасибо, последние у меня как раз промокли."},{"id":"flooded_159","kind":"secret","title":"Мерный локоть","text":"Феликс, это только тебе, ты мой лучший подмастерье и не станешь смеяться. Сегодня на стройку привезли старый блок из-под набережной, ему лет пятьсот, не меньше. На боку у него вырезан мерный локоть, на палец короче настоящего. Я приложил наш цеховой, по которому меня учил отец, а его учил дед, и они сошлись. Выходит, один старый растяпа ошибся с линейкой, и с тех пор мы кладём весь город на палец короче. Стена стоит, так что править мы ничего не будем, и ты тоже молчи."},{"id":"flooded_160","kind":"secret","title":"Письмо жене","text":"Матильда, не пугайся, ничего страшного я не нашёл. Я углубил наш подвал и наткнулся под ним на чужой. На стене там вырезан человек, который стоит согнувшись и держит на плечах дом. Лицо у него стёрлось, а руки сделаны очень старательно, кто-то его, видно, любил. Я вырезал такого же у нас над печью, только поменьше. Мне с ним спокойнее, и тебе, надеюсь, тоже будет."},{"id":"flooded_161","kind":"secret","title":"Письмо матери","text":"Мать, не волнуйся, я вернулся. В ту ночь старик с площади велел мне нести его горшок на холм, и я нёс его четыре часа по воде и по грязи, а он всю дорогу ругал меня, что я несу неправильно. На холме он пересыпал угли в ямку, потрогал их и сказал, что теперь будем ждать следующих. Я спросил, что за следующие и откуда им взяться, если город утонул. Он спросил, не холодно ли мне, и отдал свою куртку. Она теперь у меня."},{"id":"flooded_162","kind":"secret","title":"Прочитай потом","text":"Элинор, прочитай это, когда нас с отцом не будет. В ночь воды я нашла тебя в корзине у Рыбных ворот, тебе было месяца три. Мы взяли тебя и никому не сказали, потому что своих детей у нас не было, а мы их очень хотели. На тебе был чепчик с вышитыми буквами Р. Т., он лежит здесь же. Твоих родных я не искала. Я знаю, что это дурно, и больше всего боюсь, что они были живы. Прости меня, если сможешь, доченька."},{"id":"flooded_163","kind":"secret","title":"Письмо священнику","text":"Оррин, ты священник и мой брат, поэтому тебе я могу это написать. В ночь воды на шлюзах стоял я. Вода шла на весь город разом, и я открыл створ на Нижний квартал, чтобы Верхний устоял до утра. В Нижнем жила наша Элспет, и я помнил про неё, когда брался за ворот. Её сняли с крыши на второй день, живую, с кошкой под мышкой. Теперь по субботам она кормит меня супом и ругает того, кто открыл створ, а я ем и киваю. Отпущения я не прошу. Приходи в субботу, за столом мне одному тяжело."},{"id":"flooded_164","kind":"secret","title":"Опись","text":"Опись вещей, поднятых наверх по тайному распоряжению совета. Первым подняли вино, сто сорок бутылок. Потом кресло председателя. Потом ещё вино. Городской архив с купчими и метриками остался в подвале, потому что носильщики были заняты. Милая, если станут спрашивать, почему у людей нет бумаг на их дома, покажи эту страницу. Я писал её, пока они спорили, какое вино брать в лодку, и мне стыдно, что я сам таскал эти бутылки."},{"id":"flooded_165","kind":"secret","title":"Письмо тётушке","text":"Тётушка, вы одна умеете молчать. Это я оставляю по вторникам хлеб на ступеньке вдовы Элмс. Она думает, что это покойный муж присматривает за ней с небес, и рассказывает об этом всему рынку, и лицо у неё при этом светлое. Мешать ей я не хочу, поэтому хожу ночью и босиком. Я люблю её с тех пор, как он был ещё жив, и он об этом знал и каждый раз звал меня к себе на пиво."},{"id":"flooded_166","kind":"secret","title":"Письмо Вивиан","text":"Дорогая Вивиан, я четвёртый год записываю, насколько город садится в воду, и нашла странную вещь. В базарные дни он садится сильнее всего, а за неделю ярмарки опустился на целый палец. Получается, что кому-то внизу становится тяжелее, когда нас наверху больше. Староста посмеялся и сказал, что ярмарку отменять не будет. Я всё равно теперь хожу по улице тише и стараюсь не топать, и ты надо мной не смейся."},{"id":"flooded_167","kind":"secret","title":"Сожги это","text":"Племянница, сожги это, когда прочитаешь. Весь квартал сорок лет просил у меня рецепт моего яблочного пирога, и ты просила тоже. Рецепта нет. Я покупала пироги у Хьюза на том берегу, перекладывала на своё блюдо и посыпала корицей. Хьюза теперь нет, лодки туда не ходят, а завтра ко мне придёт Эмма за пирогом на поминки по матери. Приезжай, милая, я не знаю, как ей об этом сказать."},{"id":"flooded_168","kind":"secret","title":"Бертраму","text":"Бертрам, ты один знаешь, что я не утонул. Шляпу и лодку у Мельничной я оставил нарочно, а сам уехал с торговцами и живу теперь на холме под именем Хопвуд. Жена получила вдовье пособие. По четвергам я вижу её на рынке, и выглядит она очень хорошо, гораздо лучше, чем при мне, и это, если хочешь знать, обидно. Вчера она купила две булочки. Узнай, пожалуйста, для кого вторая."},{"id":"flooded_169","kind":"boss","title":"Записка мужу","text":"Ты опять доплатил за вдову Холл из своих и записал, что она заплатила. Думаешь, я не умею читать твою книгу? Умею. В этом месяце ты заплатил за неё, за сына Бейтса и за какого-то старика с козой, а дома у нас нет масла. Ешь вчерашнюю рыбу, она на полке, и вытри ноги. И не вздумай перестать, я за такого и выходила.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_170","kind":"boss","title":"Выговор","text":"Паромщику Рыбных ворот от гильдии лодочников. Сообщаем вам в третий раз, что за этот год вы перевезли без платы семнадцать человек, больше, чем разрешает устав. Также вы брали на борт сверх положенного, о чём доложил ваш собственный помощник, и плакал при этом. Штраф составляет шесть монет. Гильдия отмечает, что штраф за вас уже внесли в складчину жители Кожевенной, и просит их больше так не делать. Старшина передаёт вам поклон.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_171","kind":"boss","title":"Вопрос священника","text":"Ваше преподобие, прошу наставить меня. Вдова паромщика просит его отпеть. Тела у нас нет, и лодки нет тоже, но без тела отпевать можно, если человек умер. А рыбаки приходят ко мне и уверяют, что он по-прежнему работает, и двое даже показывают где. Могу ли я отпеть человека, если половина прихода считает, что он на службе? Вдова сказала, что, если я не решу до воскресенья, она начнёт без меня.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_172","kind":"boss","title":"Записка лодочника","text":"Жена, я задержусь. Чинил сегодня лодку Мэллоу, а днище у неё стёрто, и поперёк него идёт шершавая полоса шириной с телегу, будто лодку долго везли на чём-то живом. Сын спросил, отчего это. Я сказал, что от камня. С Мэллоу я взял обычную цену и просмолил днище погуще, чтобы вышло гладко. Раз уж он подставляет спину, пусть хоть не царапается. Не жди меня с ужином.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_173","kind":"boss","title":"Письмо брату","text":"Гарт, не вези к нам людей ночью по Тростниковой. Мы думали, что он топит лодки, но он поддевает их снизу, переворачивает и подхватывает людей на спину, как в ту ночь. Только везёт он их всё к той же крыше, откуда снимал тогда, а крыши нет уже девять лет, там одна вода. Он стоит там с ними и ждёт, пока они вылезут. Двоих с баржи мы так и не нашли. Кто умеет плавать, успевает соскочить. Прошу тебя, брат, ходи днём.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_174","kind":"boss","title":"Письмо матери","text":"Мама, я разбирала отцовский сундук и нашла банку. Ты ведь помнишь, что он брал с меня две монеты за перевоз, чтобы я не думала, будто родня катается даром. Я всё детство на него за это дулась. В банке лежат все мои монеты, и каждая завёрнута в бумажку с датой и с тем, куда я ехала. «К тётке, плакала». «На ярмарку, в новых башмаках». Я сижу на полу и не могу встать. Приходи, пожалуйста, вечером.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_175","kind":"boss","title":"Последний лист","text":"Последний лист книги сборов, разными чернилами. Старик с углями должен две монеты за перевоз, напомнить на обратном пути. Другой рукой: обратного пути пока не было, переношу на следующий год. Третьей рукой: переношу. Детской рукой: папа сказал перенести. Пятой рукой: переношу, и если вы это когда-нибудь прочитаете, дедушка, знайте, что про вас в нашей семье помнят.","boss":"boss_serpent","floors":[9,12]},{"id":"flooded_176","kind":"boss","title":"Письмо племяннице","text":"Племянница, ты спрашиваешь, зачем я каждое воскресенье выплываю на середину реки. Я рассказываю твоему отцу новости: кто родился, кто женился и кто опять ему должен. Говорить надо громко, он и при жизни плохо слышал на левое ухо. Вчера я сказала ему, что у тебя родился мальчик, и снизу постучали два раза. Потом я ещё час рассказывала про соседей, чтобы он не думал, что я приплыла только ради этого. Приезжай с малышом, я покажу вам, где сидеть.","boss":"boss_serpent","floors":[9,12]},{"id":"forge_001","kind":"note","title":"Список покупок","text":"Нэнси, детка, сходи на этой неделе на рынок, у меня прихватило спину. Купи два мешка угля и новый фартук для Дэйви, старый он совсем прожёг. Возьми большой горшок гусиного жира, потому что отец опять обжёг руки и молчит, думает, что я не вижу. Масло не бери, оно у нас всё равно растечётся по полке. И спроси у Мод, почём теперь лёд и есть ли он ещё вообще. Сдачу оставь себе на ленту."},{"id":"forge_002","kind":"note","title":"Приказ по цеху","text":"Подмастерьям запрещается жарить колбасу на заготовках мастера. Вчера заказчик спросил, почему его подкова пахнет чесноком, и мастер не нашёлся, что ему ответить, а он за сорок лет всегда находился. За каждую колбасу назначаю штраф три медяка. Найденную колбасу несите старшине, он разберётся с ней лично. Ребята, я тоже был молодым и голодным. Жарьте на совке, как все люди."},{"id":"forge_003","kind":"note","title":"Книга водоноса","text":"Я принял Литейный колодец, плата по медяку с двора. Вода в этом году теплее прошлогодней, и хозяйки мне радуются: стирать легче, руки не стынут. Вдова Лорси принесла мне пирог с капустой и спросила, не тяжело ли мне таскать вёдра. Я ответил, что нет. Если она спросит ещё раз, скажу, что тяжело.","chain":"forge_well","part":1},{"id":"forge_004","kind":"note","title":"Расписка","text":"Я получил от вдовы Лорси шесть серебряных за кованую оградку на могилу её мужа. Она просила сделать оградку повыше. Я спросил, зачем ей повыше, человек там теперь лежит смирно. Она молча доложила ещё одну монету. Покойного я знал тридцать лет, так что вопросов у меня больше нет."},{"id":"forge_005","kind":"note","title":"Табличка","text":"Если у вас пожар, стучите громче, мы тут все оглохли от молотов. Если просто горит, значит, это литейная, и вы можете идти дальше."},{"id":"forge_006","kind":"note","title":"Детской рукой","text":"папа сказал нелзя ходить босиком по двору а я ходил. теперь у меня на пятке картинка как решотка. мама мазала жиром и ругалась а потом поцеловала пятку. Нэд дал мне два ореха чтобы посмотреть. папе не скажу что картинка красивая"},{"id":"forge_007","kind":"note","title":"Требования","text":"Старшинам цеха от подмастерьев Угольного ряда. Мы требуем смену в десять часов, воду за счёт цеха и двойную плату за ночную работу. Фартуки прожигаются от работы, поэтому перестаньте вычитать за них из жалованья. Жёны и матери видят нас только спящими и уже спрашивают, как нас зовут. Пока нам не ответят, мы к горнам не подойдём. Подписали двадцать шесть человек. Дэйви поставил крестик, потому что пока учится писать.","chain":"forge_strike","part":1},{"id":"forge_008","kind":"note","title":"Правила литейной","text":"1. Фартук надевай до того, как подошёл к печи. 2. Ковш через голову товарища не передавай, у него есть мать. 3. Воду в форму не лей, сколько бы тебя ни просили и кто бы ни просил. 4. Если со стороны печи тебя позовут по имени, молчи и иди к мастеру, даже если голос похож на голос твоего отца."},{"id":"forge_009","kind":"note","title":"Рецепт","text":"Дочка, ты просила рецепт нашего хлеба, записываю. Тесто замеси с вечера, положи на порог и накрой мокрой тряпкой. К утру оно испечётся само, потому что порог у нас теперь горячий, а печку мы не топим с прошлой зимы. Корка снизу выходит чёрная, её срежь ножом и отдай собаке, собака у нас неразборчивая, в отца. У тебя в Холлоу порог, наверное, холодный, так что не знаю, как ты там вообще живёшь. Ты хоть ешь?"},{"id":"forge_010","kind":"note","title":"Записка","text":"Гвен, я выковал тебе колечко из того самого гвоздя, который ты уронила мне на ногу в день нашего знакомства. Размер я угадал по тому, как ты держишь кружку. Если окажется велико, скажи, я переделаю, нога у меня уже зажила. Выходи за меня, пока я не растерял смелость. Гвоздей у меня полный двор, а ног только две."},{"id":"forge_011","kind":"note","title":"Письмо домой","text":"Матушка, я доехал и жив. Мастер у нас строгий, зато кормят супом, и кровать у меня своя, мы спим на ней вдвоём с Лукасом. Лукас хороший, он делится со мной хлебом. Тут очень тепло, ты зря положила мне шерстяные чулки. Посылаю их обратно с возчиком, продай их, кому нужнее. Сегодня мне дали качать мехи, и мастер сказал, что я дую как чайник. Я пока не понял, хорошо это или плохо. Я скучаю по тебе. Поцелуй за меня Бесс.","chain":"forge_letters","part":1},{"id":"forge_012","kind":"note","title":"Надгробие","text":"Здесь лежит Уилмот Кросс, клепальщик. Сорок лет соседи жаловались, что он стучит. Теперешние соседи могут быть спокойны. Жена велела дописать, что дома ей стало слишком тихо и что она бы ещё послушала."},{"id":"forge_013","kind":"note","title":"Счёт из трактира","text":"Трактир «Кривой ковш», счёт Роланда Тэйта за неделю. Эля он выпил четырнадцать кружек, это семь медяков. Кружка холодной воды стоит два серебряных, и он заказал одну. Долг я записал. Роланд, ты мне как брат, поэтому скажу прямо: воду ты пил сидя, не торопясь и с закрытыми глазами, и я впервые за год видел тебя счастливым. Проценты с этого долга я брать не стану."},{"id":"forge_014","kind":"note","title":"Книга водоноса","text":"Хозяйки теперь варят яйца прямо в колодце, опускают их в мешочках на бечёвке. Я беру полмедяка за мешочек, старшина разрешил. Ведро достаю в рукавицах, а верёвку сменил на цепь, потому что старая стала ломкой. Вдова Лорси велела мне беречь руки и принесла рукавицы своего мужа, сказала, что ему они теперь ни к чему. Они мне малы, но я их ношу.","chain":"forge_well","part":2},{"id":"forge_015","kind":"note","title":"У горна","text":"Оуэна мы схоронили в воскресенье, и дежурить у горна теперь приходится мне, Бертраму. Мы с ним дружили с ученичества. С той недели угля в горне каждое утро больше, чем я клал вечером. А вчера в списке дежурных кто-то вписал без меня: Оуэн. Его почерк я знаю сорок лет. Стирать я не стал и принёс ему табаку."},{"id":"forge_016","kind":"note","title":"Школьная задача","text":"Один подмастерье куёт двенадцать гвоздей в час. Сколько гвоздей он выкует за смену, если смену продлили, а потом продлили ещё раз? Ответ ученика: столько, сколько скажет мастер. Пометка учителя: верно, садись. И передай отцу, чтобы хоть в воскресенье поспал."},{"id":"forge_017","kind":"note","title":"Ответ цеха","text":"Подмастерьям Угольного ряда. Про воду мы поговорим. Про ночные смены тоже поговорим. Фартуки прожгли вы сами, поэтому они ваши. Старшины напоминают, что большой заказ не может стоять. Кто не выйдет к горнам в понедельник, не получит ни платы за неделю, ни рекомендации. Приписка писаря, не для собрания: Гаррет, твоя мать приходила ко мне и плакала. Выйди в понедельник, прошу тебя как дядя.","chain":"forge_strike","part":2},{"id":"forge_018","kind":"note","title":"Шутка на свадьбу","text":"Это для свадьбы Дункана, скажу за столом, если мне нальют. Спросили кузнеца: что жена говорит про твой стук? Он отвечает: ничего не говорит, двадцать лет молчит, золотая женщина. Спросили жену. Та отвечала очень долго, но кузнец не расслышал ни слова. Надо бы дописать что-нибудь про тёщу, только сначала узнаю, где она будет сидеть."},{"id":"forge_019","kind":"note","title":"Молитва","text":"Святая Морвен, держащая огонь в ладони, сделай так, чтобы у моего Фенвика зажила рука и он снова взял клещи. Если нельзя клещи, пусть возьмёт хотя бы ложку, а то кормлю его я, и он от этого злится и стыдится. Я тридцать лет люблю этого сварливого человека. Свечу я тебе поставлю, как только свечи у нас перестанут гнуться от жары."},{"id":"forge_020","kind":"note","title":"Жалоба в цех","text":"Третий раз прошу цех что-нибудь сделать со стеной литейной, к которой прибиты мои сушильные верёвки. Бельё сохнет быстрее, чем я успеваю сходить за вторым тазом. Вчера две простыни сгорели прямо на верёвке, причём сама верёвка цела. Эти простыни мать подарила мне на свадьбу, и муж спал на них до самого конца. Прошу возместить. Корделия Брам, Мехов переулок."},{"id":"forge_021","kind":"note","title":"Объявление","text":"Продаю чугунную печь, почти новую, в нашем доме она больше не нужна. Отдам также шесть зимних одеял и детские сани, на которых мои дочки катались, пока на улице ещё лежал снег. Сани жалко, хорошие были сани. Спросите Найджела на Угольном ряду, если я ещё не уехал."},{"id":"forge_022","kind":"note","title":"Письмо домой","text":"Матушка, пришли мне мази и сушёных яблок, если сможешь. Меня поставили к средней печи и платят на медяк больше, так что скоро я пошлю тебе денег. Лукаса поставили к большой. Спать он теперь не приходит, говорит, что ему некогда. Кровать вся моя, а мне почему-то не спится. Я всё думаю, что надо было сказать ему, чтобы поел.","chain":"forge_letters","part":2},{"id":"forge_023","kind":"note","title":"Нужен ученик","text":"Двору Хэдли нужен ученик, крепкий и непьющий, который не боится жары. Кормим два раза в день, а жена мастера подкладывает третий, когда он не смотрит. Про брови просим не спрашивать, они отрастают."},{"id":"forge_024","kind":"note","title":"Расчётный лист","text":"Ансельм Хоук, молотобоец. Жалованье за месяц составило двенадцать серебряных. Вычеты такие: за фартук два, за уголь, потраченный без нужды, один, складчина на поминки старшины три, лекарю пять. На руки выдано одно серебряное. Подпись за Ансельма ставлю я, новый старшина, потому что пальцы у него не сгибаются. Его жена пришла за деньгами и долго смотрела на эту монету. Я добавил ей свою, в книгу не пишу."},{"id":"forge_025","kind":"note","title":"Книга водоноса","text":"Ведро приходит наверх наполовину пустым, остальное уходит паром, пока я его поднимаю. С утра я разливаю воду по корытам, чтобы до обеда остыла. Дети спрашивают меня, кто стучит внизу. Я сказал им, что это ведро бьётся о камни. Дети поверили, а вдова Лорси посмотрела на меня и ничего не сказала. Она-то видела, что ведро в тот час стояло на земле.","chain":"forge_well","part":3},{"id":"forge_026","kind":"note","title":"Наказ сыну","text":"Дэйви, сынок, я поехал к тёще и вернусь в среду. Держи горн ровно и качай мехи так, как я тебе показывал, а не так, как ты любишь. Кочергу отнеси вдове Лорси и денег с неё не бери, она нас кормила, когда я болел. Если средняя печь запоёт, сразу закрой заслонку и иди ночевать домой, ничего там не жди и не слушай. Ключ я оставил под ведром. Ешь как следует, я спрошу у матери."},{"id":"forge_027","kind":"note","title":"Опись","text":"Опись имущества покойного Тибальда Фрея, составил его сын. Наковален осталось две, молотов девять. Клещей одиннадцать пар, и одна пара сжата так, что мы вдвоём с братом не смогли её разжать. Внутри что-то есть, и оно тёплое, поэтому мы оставили всё как было. Мехи дырявые. Долгов за отцом нет, он всю жизнь этим гордился и велел написать отдельно."},{"id":"forge_028","kind":"note","title":"Дневник","text":"Я делал пряжку для невесты Эдвина, и получилась она только с пятого раза. Бертрам говорит, что она похожа на лягушку. Это лебедь. Невеста взяла пряжку, поцеловала меня в щёку и спросила, как я догадался, что она любит лягушек. Бертраму я об этом не скажу до самой его смерти."},{"id":"forge_029","kind":"note","title":"Письмо поставщика","text":"Господа старшины! Последняя подвода льда доехала до ваших ворот мокрой телегой. Возница, мой родной брат, клянётся, что лёд на ней был, и я ему верю, хотя он мне должен. Счёт прилагаю полный. Лошадь в ваш квартал больше не идёт, она встала на перекрёстке и смотрит на брата с укоризной, так что дальше возите сами."},{"id":"forge_030","kind":"note","title":"Листок стачки","text":"Идёт шестой день стачки. Мы сидим у ворот, на хлеб пока хватает, а мать Гаррета носит нам суп, ругает всех по очереди и всё равно наливает добавку. К горнам никто из нас не подходил, ключи у нас, и ворота я запирал сам. А дым из труб идёт, как шёл.","chain":"forge_strike","part":3},{"id":"forge_031","kind":"note","title":"Вывеска сапожника","text":"Делаю подмётки для Литейной. Двойные продержатся месяц. Тройные продержатся месяц и неделю. Четверные я вам не советую, споткнётесь, как мой зять. Стивен Гейл, у фонтана. Фонтан не работает, а я пока работаю."},{"id":"forge_032","kind":"note","title":"Письмо сестре","text":"Марджери, мы перебрались на верхний этаж, потому что внизу стало не уснуть от жары. Хозяин взял за это ещё медяк. Петух во дворе кричит всю ночь: небо у нас красное, и он думает, что настало утро. Муж грозится его сварить, а сам каждый вечер кормит с руки. Приезжай, сестричка, на именины и привези ведро снега, если он где-нибудь ещё лежит. Я скучаю по снегу, но по тебе больше."},{"id":"forge_033","kind":"note","title":"Письмо домой","text":"Матушка, пишу быстро, мастер ждёт. Деньги за три месяца тебе передадут, на меня их не трать. Вчера Лукас вышел к ужину, брал еду руками прямо из кипящего котла и не морщился. Он посмотрел на меня и не вспомнил, как меня зовут. Завтра меня тоже ставят к большой печи, мастер сказал, что я готов. Пришли мне всё-таки те чулки, если ты их не продала. Ночью мне стало холодно, матушка, а здесь никому не бывает холодно.","chain":"forge_letters","part":3},{"id":"forge_034","kind":"note","title":"Донесение","text":"Старшине от трубочиста. Трубы на Молотовой я проверил, они чистые, и тяга ровная. Спросил печников про дом Бенедикта, потому что печи у него нет вовсе, а дым идёт из-под пола. Печники сказали, что это не к ним. Бенедикт мне кум, и дети у него кашляют, так что прошу вас, пошлите к нему хоть кого-нибудь, пока он сам не начал копать."},{"id":"forge_035","kind":"note","title":"Договор","text":"Мальчик Пип девяти лет отдан в ученье мастеру Хэдли на семь лет. Мастер обязуется дать ему кров и ремесло. Отец получил за него два серебряных. Мать просила вписать, чтобы её сына не ставили к большой печи, и ещё, что он боится темноты и засыпает, только если ему споют. Всё это вписано на полях. Законной силы приписка не имеет. Мастер прочитал и сказал, что петь не умеет, но попробует."},{"id":"forge_036","kind":"note","title":"Книга водоноса","text":"Сегодня я опустил ведро, а поднял цепь без ведра. Конец цепи стал мягким, как тесто, и светился. Старшина выдал мне жалованье вперёд и велел закрыть колодец. Каменная крышка треснула за ночь, поэтому кладём железную. Я ходил спрашивать про работу на мельнице и сказал вдове Лорси, что там хватит места на двоих. Она ответила, что подумает, и вынесла мне пирог в дорогу, хотя я ещё никуда не еду.","chain":"forge_well","part":4},{"id":"forge_037","kind":"note","title":"Заявка каменщику","text":"Мастер Клемент, порог у нас оплыл, как воск. С утра камень тёплый, к вечеру мягкий, и дверь снизу прихватило так, что она больше не открывается. Поправьте, пожалуйста, когда сможете. Пока мы ходим через окно. Жена лезет первой и ругает меня всю дорогу, а вчера застряла, и мы с ней впервые за год посмеялись. Бенедикт говорит, что у него то же самое."},{"id":"forge_038","kind":"note","title":"Порядок праздника","text":"Утром мы пройдём шествием с молотами. В полдень начнётся бег с наковальней, победитель получит окорок. Вечером старшины будут петь. Просим вас не расходиться раньше времени, в прошлом году они обиделись и плакали. Купание отменяется, потому что пруд опять кипит. Матери, присмотрите за детьми, особенно за Нэдом."},{"id":"forge_039","kind":"note","title":"Записка","text":"Рейнольд, брат, ребята спрашивают, что им делать. Сегодня ночью в запертых цехах опять стучали молоты. Мы заглянули в щель: горны гудят, а на наковальнях лежит готовое железо, ещё тёплое. Ворота заперты, ключи при мне, там никого не может быть. В понедельник многие выйдут на работу. Я тоже выйду, прости меня, у Кэтрин скоро срок. Не сердись и приходи крестить.","chain":"forge_strike","part":4},{"id":"forge_040","kind":"note","title":"Сбор железа","text":"На нужды совета собираем с каждого двора по ведру лома. Это уже восьмой сбор за год. Кто уже сдал котлы и вилки, может сдать дверные петли: двери мы всё равно держим открытыми от жары. Тётя Мод, не смотрите на меня так, я свою ложку сдал первым."},{"id":"forge_041","kind":"secret","title":"Секрет закалки","text":"Три поколения двор Хэдли хранит секрет закалки: железо надо калить в молоке рыжей козы, взятом до восхода. Отец шепнул мне это перед смертью и заплакал. Я всё проверил. В простой воде выходит то же самое. Сыну я про козу всё равно скажу, пусть и ему будет что шептать. Молоко я, кстати, пил."},{"id":"forge_042","kind":"secret","title":"Признание","text":"Кому-нибудь я должен признаться. Ночью я подпилил звено до половины, чтобы цепь лопнула, всё кончилось и мой сын пришёл наконец домой. Наутро пропил был заварен, и звено стояло целое. Рядом появилась зарубка, глубже и ровнее моей, как будто мне показали, как надо было пилить. На наковальне лежала моя пила, и кто-то её заточил. Сын утром спросил меня, хорошо ли я спал. Он никогда раньше такого не спрашивал."},{"id":"forge_043","kind":"secret","title":"Рассказ деда","text":"Дед говорил, что огонь в главном горне принесли снизу, из города, который был тут раньше. Принёс его старик на лопате и спросил у первых кузнецов, почему они так долго. Дед божился, что видел того же старика на прошлой неделе у рынка. Глаза у деда плохие, но спорить я не стал, его теперь и так мало кто слушает. Я сел рядом и попросил рассказать ещё раз."},{"id":"forge_044","kind":"secret","title":"Сбережения","text":"Здесь лежат двадцать восемь серебряных на дорогу к сестре в Холлоу, и вынимать их нельзя. Я вынула два на сапоги. Потом вынула три, потому что заболел мой Гарри. Вынула ещё шесть, но лучше ему не стало. Я написала себе, что больше не вынимаю, и тут пришлось вынуть на могильный камень. Осталось четыре. Сестре я напишу, чтобы не ждала. Гарри лежит здесь, и куда я от него поеду."},{"id":"forge_045","kind":"secret","title":"Клеймо","text":"Тут лежит клеймо двора Хэдли, которое я подделал сам. Восемь лет я ставил его на свои подковы и брал за них как за настоящие. Хэдли когда-то выгнал меня из учеников и сказал, что руки у меня кривые. На прошлой неделе он показывал одну из моих подков своим ученикам и говорил им: вот как надо. Гордиться мне нечем, но очень хотелось кому-нибудь сказать. Старик, ты меня всё-таки выучил."},{"id":"forge_046","kind":"secret","title":"Запись шлаковщика","text":"Я копал отвод для шлака и пробил свод. Внизу было темно, и оттуда капало. Я опустил фонарь на верёвке и увидел мокрую черепичную крышу, а на ней лодку, привязанную к трубе хорошим узлом, как будто хозяин собирался вернуться. Дыру я заделал и никому не сказал, даже жене, хотя говорю ей всё. Шлак теперь пускаю в другую сторону, вдруг там кто-нибудь живёт."},{"id":"forge_047","kind":"secret","title":"Детский клад","text":"это мой клад. тут лежит гвоздь золотой (красил сам), заклёпка Нэда и бусина из шлака для мамы на день рожденя. кто найдёт ничево не брать. заклёпку можно"},{"id":"forge_048","kind":"secret","title":"Про хлеб","text":"По четвергам хлеб на порог вдовы Лорси кладу я. Она думает, что его приносит покойный муж, рассказывает об этом соседкам, и лицо у неё при этом такое счастливое, что я молчу. Пускай думает. Он при жизни ни разу не принёс ей хлеба."},{"id":"forge_049","kind":"secret","title":"Запрещённая песня","text":"Это песня, за которую у нас штрафуют. «Мастер сказал: ещё звено. Мастер сказал: ещё одно. Жена сказала: ужин стынет. Мастер сказал: ещё звено». Поём мы её тихо, штраф пять медяков с головы. Гаррет глухой и поёт громче всех, поэтому платит за него вся смена, и никто ни разу ему об этом не сказал."},{"id":"forge_050","kind":"secret","title":"Холодное место","text":"За третьим столбом в погребе снизу тянет холодом. Это единственное прохладное место на весь квартал, и я хожу сюда посидеть после смены, пока жена думает, что я в трактире. Пусть лучше думает так. Здесь пахнет мокрым деревом. Иногда снизу постукивают, два раза, будто монетой о доску. Я один раз постучал в ответ и больше так не делаю."},{"id":"forge_051","kind":"boss","title":"Заказ совета","text":"«Цепь, чтобы поднять мост, когда придут с юга. Сто двадцать звеньев. Мастер: принято». Ниже другой рукой: «Совета больше нет, и моста тоже». Ниже, выжжено на железе: «Звено девять тысяч сорок. Цепь пока слабая».","boss":"boss_forge","floors":[5,6]},{"id":"forge_052","kind":"boss","title":"Книга звеньев","text":"Мастер велел мне записывать. Звено сто двадцатое мы сдали, и совет заплатил. Потом мастер сказал, что у сто двадцатого есть слабое место, и мы выковали сто двадцать первое. Теперь он говорит, что слабое место у сто двадцать первого. Я спросил его, сколько ещё, ведь я обещал жене вернуться к весне. Мастер посмотрел на меня и спросил, целы ли у меня обе руки. Я ответил, что целы. Он сказал: значит, ещё.","boss":"boss_forge","floors":[5,6]},{"id":"forge_053","kind":"boss","title":"Наказ новеньким","text":"Новенькие, слушайте меня, я тут дольше всех. Звенья носите по двое, иначе в первую же неделю надорвётесь. Слово «готово» при мастере не говорите, он на него сердится, говорите «пока держит». Если он спросит, пришли ли с юга, отвечайте: нет ещё. Тогда он успокаивается и берёт молот. Когда-то он учил меня держать клещи и ночью укрывал своей курткой. Не смейтесь над ним, если хотите дожить до ужина.","boss":"boss_forge","floors":[5,6]},{"id":"forge_054","kind":"boss","title":"Записка жены","text":"Старый мой, ужин третий день стоит на столе. Я грею его о стену, она теперь горячая, как печка. Совет разошёлся, и моста больше нет, я сама ходила смотреть, там просто течёт река. Вечером к нам приедут дети с внуками. Посиди с ними хоть один вечер, я прошу тебя, они уже не помнят твоего голоса. Молот можешь взять с собой.","boss":"boss_forge","floors":[5,6]},{"id":"forge_055","kind":"boss","title":"Извещение","text":"Мастеру цеха. Извещаю вас, что заказ исполнен и закрыт, совет распущен, а печать сдана. Прошу вас расписаться в получении. Это моё пятое извещение. Предыдущие четыре вернулись ко мне с числом звеньев, написанным поверх текста, и я вынужден подшивать их как переписку. Мы же с вами вместе учились считать. Распишитесь, пожалуйста, и заходите ко мне на пиво, как раньше.","boss":"boss_forge","floors":[5,6]},{"id":"forge_056","kind":"boss","title":"Письмо с юга","text":"Мастеру от Корвина из южных деревень. Пишу вам, потому что вчера мы с вами не договорили. Мне сказали, что вы куёте цепь от нас. Никто к вам не шёл, добрый человек: в тот год у нас случился неурожай, и все разошлись по домам. Я привёз вам пять банок грушевого варенья в знак мира, его варила моя жена. Вы спросили, сколько нас. Я ответил, что я один. Вы сказали: это пока.","boss":"boss_forge","floors":[5,6]},{"id":"forge_057","kind":"boss","title":"Письмо ученика","text":"Мастер, я ушёл ночью, а ключ оставил на гвозде. Двадцать лет я про себя звал вас отцом, поэтому не смог сказать вам это в лицо. Вы учили меня, что вещь готова, когда её можно отдать кому-то в руки. Эту цепь отдать некому. Я забрал только маленький молоток, которым вы делали дочке крючки для платья. Он давно лежал без дела, и мне он как раз по руке.","boss":"boss_forge","floors":[5,6]},{"id":"forge_058","kind":"boss","title":"Письмо дочери","text":"Папа, мне уже шестьдесят один год. Я принесла тебе новый фартук, потому что прежний на тебе сгорел. Ты меня не узнал и спросил, из какой я деревни на юге. Я сказала, что с нашей улицы. Ты кивнул и велел мне подержать клещи. Я подержала, и ты обрадовался так, как радовался, когда я была маленькой. Оставляю эту записку на наковальне, вдруг ты вспомнишь, что умеешь читать. Приду ещё в четверг.","boss":"boss_forge","floors":[5,6]},{"id":"forge_059","kind":"note","title":"Письмо часовщика","text":"Тэсс, родная, как ты там на новом месте? Башенные часы на Литейной площади стали отставать и за месяц потеряли почти час. Я полез наверх и всё понял: от жары маятник удлинился, железо ведь растёт, когда греется. Ты бы догадалась раньше меня, у тебя голова матери. Я поднял груз повыше, и часы снова идут верно. Без тебя на лестнице тяжело: колени у меня скрипят громче часов, очки я опять забыл дома, и никто меня за это не ругает. Напиши, не обижает ли тебя муж.","chain":"forge_clock","part":1},{"id":"forge_060","kind":"note","title":"Объяснительная","text":"Я, Вилли Картер, нёс через формовочную гуся моей бабушки, потому что во дворе жарко и гусь обижался. Гусь вырвался и прошёлся по песчаной форме для доски совета. Я заметил это, только когда доску уже отлили. Теперь по гербу совета идут двенадцать отпечатков лап. Бабушке прошу не говорить, ей восемьдесят лет, и она любит этого гуся больше меня. Приписка старшины: совет доску принял и похвалил узор. Штрафа Вилли не платит. Гуся в цех больше не пускать."},{"id":"forge_061","kind":"note","title":"Вывеска кузнеца","text":"Подковать лошадь стоит два медяка, а мула три, потому что у мула есть своё мнение. Ножи точу за медяк. Супругов я не мирю, хотя просят, у меня для этого только молот. Игрушки детям чиню бесплатно, только пусть приходят сами и рассказывают, как она сломалась, мне это нравится больше денег."},{"id":"forge_062","kind":"note","title":"Записка на калитке","text":"Господин Стоукс! Ваш молот будит мою курицу в пять утра, и она от этого перестаёт нестись. Вы стучите так уже тридцать один год, и всё это время я вежливо вас ненавижу. Прошу начинать хотя бы в семь. Эбигейл Ройс. Ниже ответ: Госпожа Ройс, ваша курица ни разу в жизни ничего не снесла, я видел, как вы покупаете яйца на рынке. Могу начинать в четыре. Стоукс.","chain":"forge_gate","part":1},{"id":"forge_063","kind":"note","title":"Как жить дальше","text":"Ральфу, мужу моему. Рубашки стирай раз в неделю, сами они чище не станут. Кашу вари на малом огне и не отходи от неё. Мэри скоро начнёт расти быстрее платьев, попроси Эдит подшить, она не откажет. Когда Робин спросит, где я, не говори ему, что я уехала, он будет ждать. Соль стоит за мукой, ты ищешь её двадцать лет. Лекарь сказал, что мне осталось немного. Тебе я этого не сказала, потому что ты сразу начнёшь со мной прощаться, а я ещё хочу поругаться из-за сапог."},{"id":"forge_064","kind":"note","title":"Письмо свахи","text":"Госпожа Хаксли, докладываю о первой невесте для вашего Тобиаса. Присцилла Вуд пришла нарядная, а он поднялся ей навстречу и уронил скамью. Потом он поднял скамью одной рукой и попросил у неё прощения, я имею в виду у скамьи. За весь вечер он сказал девушке только, что у неё хорошие зубы. Мальчик он золотой, это видно сразу, только говорить при девицах не умеет. Следующую я подберу глуховатую, ему так будет легче. С вас половина серебряного за первую попытку.","chain":"forge_match","part":1},{"id":"forge_065","kind":"note","title":"Наказание","text":"я не буду спрашывать господина старшину куда делся атец Тома. я не буду спрашывать господина старшину куда делся атец Тома. я не буду спрашывать господина старшину куда делся атец Тома. учитель велел написать сто раз а у меня рука устала. Том каждый день ходит к воротам цеха и стоит там. мне ево жалко. я не буду спрашывать"},{"id":"forge_066","kind":"note","title":"Донесение сержанта","text":"Совету от сержанта Брокса об учениях ополчения с Угольного ряда. Пики кузнецы держат крепко, и тут я доволен. Но по команде «стой» они ещё три раза бьют древком о землю, пока не закончат начатое. Команду «налево» слышат не все, и налево часто ухожу я один. Мой шурин Эрик спросил меня, кого мы ждём с юга, и я не смог ему ответить, потому что сам этого не знаю. Прошу прислать флаг побольше, чтобы ребята видели, куда идти."},{"id":"forge_067","kind":"note","title":"В узелке","text":"Сэм, в узелке лежат хлеб, сыр и луковица. Не отдавай половину Джону, я знаю, что ты отдаёшь. Ладно, отдавай, я потому и положила два куска сыра. У него дома сейчас нечего есть, только не говори ему, что я об этом знаю. Вечером приходи пораньше, если отпустят. Я скучаю по тебе, хотя от тебя пахнет луком, который я сама же тебе и кладу."},{"id":"forge_068","kind":"note","title":"Письмо часовщика","text":"Тэсс, вчера ко мне зашёл старшина Прайс и положил на верстак кошелёк. Он попросил больше не лазить к маятнику и оставить часы как есть. Смена у нас кончается по башне, понимаешь? Пока часы отстают, люди работают лишний час и сами этого не замечают. Я ответил, что подумаю. В кошельке двенадцать серебряных, а мне давно пора чинить крышу. Правда, дождя у нас не было с весны. Не знаю, зачем я тебе это пишу. Наверное, хочу, чтобы ты меня отругала.","chain":"forge_clock","part":2},{"id":"forge_069","kind":"note","title":"Для зятя","text":"Джеймс, раз ты теперь входишь в семью, вот тебе слова моего отца, он оглох в сорок лет. Кулак к груди значит, что пора есть. Два пальца по столу значат, что ты мало ешь. Ладонь на затылке означает, что ты дурак, но он это без злобы. Если он хлопнет тебя по плечу и отвернётся, значит, ты ему понравился. Больше он тебе этого не покажет, так что запомни тот день. Он знает, что я тебя люблю, я показала ему сама."},{"id":"forge_070","kind":"note","title":"Завещание","text":"Завещание Мэтью Беннета, кузнеца. Дом я оставляю жене, пусть живёт в нём сколько захочет. Молоты разделите поровну. Наковальню я завещаю обоим сыновьям вместе и делить её запрещаю. Один человек её с места не сдвинет. Джон и Адам, вы не разговариваете с тех пор, как не поделили покос. Если захотите её продать, вам придётся взяться за неё вдвоём и договориться, в какую сторону нести. Простите старика, ничего умнее я не придумал."},{"id":"forge_071","kind":"note","title":"Записка на калитке","text":"Стоукс, ваш молот молчит вторую неделю, и курица спит до полудня. Мне это не нравится, она толстеет. Лекарь сказал мне, что у вас плохо с лёгкими. Суп я поставила на ступеньку, кастрюлю верните вымытой. Умирать не вздумайте: мне некого будет ненавидеть, а новых людей в моём возрасте я уже не запоминаю. Э. Р. Ниже ответ: Суп пересолен. Пришлите ещё. С.","chain":"forge_gate","part":2},{"id":"forge_072","kind":"note","title":"Черновик стихов","text":"«Твои глаза горят, как горн, я весь тобою опалён». Ниже почерком друга: Клайв, не пиши ей про горн, она каждый день на него смотрит. «Молот» у тебя рифмуется с «холод», а холода тут ни у кого нет. Напиши ей просто, что думаешь о ней у печи и что у тебя дрожат руки, а мастер из-за этого ругается. Это правда, и ничего лучше ты пока не сочинил. И умоляю, вычеркни строчку, где её мать похожа на наковальню, даже если похожа."},{"id":"forge_073","kind":"note","title":"Письмо повитухи","text":"Агнес, сестричка, ты спрашивала про мою работу. Этой весной я приняла в квартале девятнадцать детей, и все родились здоровыми, только ни один не закричал. Они дышат и смотрят, а кричать не хотят. Я заворачиваю ребёнка и несу за Речные ворота, туда, где есть ветер. Там он наконец заходится, и мать, которая бежит за мной босиком, плачет и смеётся. Мне уже шестьдесят лет, Агнес, я устала бегать. Думала брать за это отдельно, но не беру."},{"id":"forge_074","kind":"note","title":"Письмо свахи","text":"Госпожа Хаксли, со второй невестой вышло хуже. Вдова Кэмпион пришла посмотреть жениха, а ушла с моим племянником, который носил чай. Тобиас весь вечер молчал и чинил ей пряжку на туфле, пока она жаловалась на жизнь. Потом он отдал ей туфлю и сказал: вот, теперь не будет натирать. Вдове этого оказалось мало. Зато он всё время смотрел в окно на рыжую Ивонн, которая напротив чинит мехи. Вы про неё что-нибудь знаете?","chain":"forge_match","part":2},{"id":"forge_075","kind":"note","title":"Решение старшин","text":"Заключение о мастерской работе Лоуренса Пайка. Замок на сундуке выдержал двенадцать взломщиков, причём двое из них были наши. Ключ Лоуренс предъявить не смог, потому что запер его в том же сундуке вместе со свадебным кольцом. Звание мастера ему присуждается. Старшины просят невесту проявить терпение. Приписка писаря: невеста велела передать, что выйдет за него и так, а сундук поставит у кровати, чтобы он каждое утро на него смотрел."},{"id":"forge_076","kind":"note","title":"Расписка","text":"Я, Уолтер Хиггс, должен Томасу Арчеру одну драку за то, что на прошлой ярмарке он назвал мою лошадь тощей. Драку откладываем до конца его свадьбы. Приписка: отложено до рождения ребёнка. Приписка: отложено, пока не поправится его мать. Приписка: отложено до конца большого заказа. Приписка: Томас, я сегодня заходил к тебе, а ты спал за столом, и Бетси сказала, что ты теперь всё время спишь. Долг я с тебя не снимаю, даже не надейся. Поправляйся и приходи драться."},{"id":"forge_077","kind":"note","title":"Отзыв","text":"Мастеру Дэвису от мастера Кларка. Ты спрашиваешь про Перри Оукса, который у меня работал. Подковы у него выходят кривые, гвозди он гнёт, а однажды он поджёг на себе шапку, не снимая её. Когда у меня умерла жена, Перри неделю носил мне ужин, садился напротив и ни разу не спросил, как я. Он и сейчас приходит по средам. Возьми его куда хочешь, только близко к огню не ставь. Обидишь его, я приеду к тебе сам."},{"id":"forge_078","kind":"note","title":"Письмо часовщика","text":"Тэсс, ты отругала меня так, что письмо можно было не распечатывать, я слышал тебя от самой почтовой станции. Кошелёк я вернул. Прайс пересчитал монеты при мне, и вот это было обидно. Ночью я поднялся на башню и поставил часы точно. Вчера смена впервые за полгода ушла домой вовремя, и Хэмиш Ролл зашёл пожать мне руку, а он девять лет со мной не разговаривал. Мне очень хорошо, дочка. Приезжай, пока я тут герой.","chain":"forge_clock","part":3},{"id":"forge_079","kind":"note","title":"Книга находок","text":"Найдено при Литейной за месяц. Зуб, один, крепкий. Заявлений не поступало, но Джек Тилли подозрительно улыбается, не разжимая губ. Левая рукавица с вышитой внутри буквой М, хозяин пусть заберёт, жена вышивала и будет спрашивать. Детская деревянная лошадка, её опять забыл Джон Харт, который носит её с собой с весны. Я отнёс ему домой и ни о чём не спрашивал. Сапог, левый. Храню его третий месяц, хозяин больше не придёт, а выбросить у меня рука не поднимается."},{"id":"forge_080","kind":"note","title":"Сочинение","text":"мой папа. мой папа делает звинья для большой цепи и от него пахнет дымом. он приходит домой когда я сплю и ложит мне руку на голову. рука гарячая и я всегда просыпаюсь но делаю вит что сплю. он думает что меня не разбудил и радуется. потом он уходит. когда я вырасту я хочу чтобы он пришёл днём. учитель сказал писать про работу папы а я про неё больше ничево не знаю"},{"id":"forge_081","kind":"note","title":"Записка на калитке","text":"Госпожа Ройс, петлю на вашей калитке я заменил, пока вас не было, старая держалась на честном слове. Денег не возьму, не выдумывайте. Скажите лучше, почему вы теперь сидите ночами на крыльце. Я вижу вашу свечу. У вас пол горячий, я знаю, у меня такой же, только мне об этом сказать было некому. Приходите утром, у меня есть чай. Курицу можете взять с собой, я постучу потише. С.","chain":"forge_gate","part":3},{"id":"forge_082","kind":"note","title":"На манжете","text":"Себе на экзамен. Железо греть до вишнёвого цвета, до белого не доводить. Молот держать за конец, а не так, как мама держит ложку. Если старшина Прайс спросит про закалку, спросить про его внука, и он забудет вопрос. Руками при них не махать, они и так видят, что дрожат. Отец говорил, что у него дрожали тоже, и заказ ему всё равно дали. Мать обещала пирог при любом исходе, это я записываю, чтобы помнить, когда буду стоять перед ними."},{"id":"forge_083","kind":"note","title":"Заявление","text":"В похоронную кассу Литейного ряда. Я, Арчибальд Мэй, плачу вам по медяку в месяц уже сорок один год. За это время я пережил двух ваших казначеев и мою Хильду, чьи похороны прошли очень хорошо, спасибо. Прошу вас либо вернуть мне половину, либо похоронить меня хотя бы наполовину, пока я могу проследить, чтобы не экономили на пирогах. Хильда любила, когда пирогов много, и я хочу, чтобы всё было как у неё."},{"id":"forge_084","kind":"note","title":"Про стук","text":"Элинор, скажу тебе то, чего не могу сказать здесь никому. Шестнадцать лет я узнаю молот моего Альберта среди всех молотов квартала. Он бьёт два раза быстро и один раз с ленцой, так же он и ходит. По этому стуку я знаю, когда ставить обед. Третью ночь я слышу из литейной два быстрых удара и один ленивый и лежу с открытыми глазами, потому что Альберт спит рядом со мной. Я его не бужу. Ты только не пиши об этом маме."},{"id":"forge_085","kind":"note","title":"Письмо свахи","text":"Госпожа Хаксли, прошу заплатить мне полную цену, хотя всё он сделал сам. Тобиас понёс рыжей Ивонн мехи, которые совсем не были сломаны. Она это сразу увидела и велела ему сесть. С тех пор он каждый вечер ломает у себя что-нибудь небольшое и несёт к ней. За три недели он сказал ей девять слов, а она говорит, что ей хватает, потому что сама разговаривает за двоих. Свадьбу назначайте после жатвы. Я сорок лет свожу людей и всякий раз реву на венчании, платок принесу свой.","chain":"forge_match","part":3},{"id":"forge_086","kind":"note","title":"Записка жильцу","text":"Господин Уоррен, вот уже пятый месяц вы платите мне подковами. У меня теперь сорок две подковы и ни одной лошади. Я прибила их над дверью, но соседки говорят, что столько удачи одной вдове неприлично. Я понимаю, что вам самому не платят вовремя. В воскресенье у меня будет баранина, приходите и заберите хотя бы пять штук, если унесёте. Рубашку наденьте чистую, это к делу не относится."},{"id":"forge_087","kind":"note","title":"Письмо другу","text":"Бен, старый ты пень, пишу тебе из Ларкхилла. Дети забрали меня сюда на покой. Воздух тут прохладный, кормят хорошо, а спать я не могу. Здесь так тихо, что слышно, как думает моя невестка. Я плачу соседскому мальчишке медяк в неделю, чтобы он по вечерам колотил в сковородку у меня под окном, ровно, как ты бил. Невестка считает, что я тронулся. Ты там хоть живой? Я всё время хочу сказать тебе что-нибудь обидное, а тут некому."},{"id":"forge_088","kind":"note","title":"Письмо часовщика","text":"Тэсс, я больше не лазаю на башню, незачем. Стрелки размягчились от жара и повисли вниз, обе, как усы у твоего дяди. С площади теперь всё время видно половину седьмого. Маятник ходит, и я слышу, что ходит он верно, только показать ничего не может. Со смены люди уходят, когда их отпустит мастер, и кошелька мне больше никто не предлагает. Ты спрашивала, не приехать ли за мной. Приезжай, родная, только не торопись, дорога плохая. И скажи мужу, что я согласен спать в сарае.","chain":"forge_clock","part":4},{"id":"forge_089","kind":"note","title":"Для мальчика","text":"Это тебе, раз ты теперь стоишь за стойкой. Рыжему Уилфу не наливай, он поёт. Оскару Лейну не наливай после третьей, он начинает дарить людям свой дом. Хью Маккею наливай, он женат на моей сестре, но ей говори, что не наливал. Старику Гиббону наливай в долг и делай вид, что записываешь. Долг на самом деле не пиши. Если он увидит, что ему наливают даром, он перестанет приходить, а больше ему идти некуда."},{"id":"forge_090","kind":"note","title":"Прошение","text":"Старшинам от Гилберта Соуна, сорок девять лет при цехе. Мастер Лэмб сказал мне, что я больше не могу держать молот. Он прав, третьего дня молот вылетел у меня из руки и разбил окно. Прошу только оставить мне табурет у задней двери. Работать я не стану, буду говорить молодым, что они всё делают неправильно, им это полезно. Дома у меня теперь никого нет, и там слишком чисто. Резолюция: табурет оставить, молот спрятать, Гилберту выдавать обед."},{"id":"forge_091","kind":"note","title":"Счёт","text":"Счёт Элли Браун, семи лет, за скобу на левую ногу. Железо и работа стоят четыре серебряных. Оплачено рисунком лошади, на котором лошадь похожа на меня. Расчёт закрыт. Матери передайте, что к весне нога вырастет и скобу придётся переделать. За это я возьму ещё один рисунок, и пусть на нём будет собака, лошадей у меня уже хватает. И пусть девочка бегает, я для этого и делал, вы её не останавливайте. Эд Фишер."},{"id":"forge_092","kind":"note","title":"Записка на калитке","text":"Хамфри, мы с тобой уезжаем в среду на одной телеге, потому что других уже не осталось. Сундук я поставлю посередине, чтобы не сидеть с тобой рядом. Молот бери, без него я всё равно уже не усну, хотя вслух я этого ни за что не скажу, поэтому и пишу. Курица поедет у тебя на коленях. Эбигейл. Ниже ответ: Тридцать один год я начинал в пять, чтобы ты выглядывала в окно. Х.","chain":"forge_gate","part":4},{"id":"forge_093","kind":"note","title":"На верстаке","text":"Вырезано ножом на краю верстака: «Тут работал Роб Эллис, двенадцать лет от роду». Чуть ниже: «Тут работал Роб Эллис, тридцать лет от роду, и ему не стыдно». Ещё ниже, аккуратно: «Мастер Роб Эллис просит мальчиков не портить верстак». В самом низу, неровно: «Тут работал Роб Эллис, двенадцать лет. Дедушка, не ругайся»."},{"id":"forge_094","kind":"note","title":"Письмо кузену","text":"Питер, пришли мне ещё косточек, сколько сможешь. Персики, которые ты подарил нам в шутку, на третий год дали плоды прямо у нас во дворе. У нас в краю таких никто не видел. Жена их боится, но ест. Соседи спрашивают, в чём мой секрет, и я напускаю на себя важный вид. Секрета у меня нет. Земля теперь тёплая круглый год, а если копать глубже, из неё пахнет палёным, и я стараюсь глубоко не копать. Приезжай на варенье, тётя всё время про тебя спрашивает."},{"id":"forge_095","kind":"note","title":"Протокол","text":"Собрание старшин. Присутствовали все, кроме мастера цеха. Мастер прислал вместо себя звено, и его посадили во главе стола, потому что спорить никто не решился. Поставили вопрос о сверхурочных и вопрос о воде. Мнение звена я записать затрудняюсь, старшина Хоббс предложил считать его несогласным, так будет вернее. Оба вопроса отложены. Писарь просит впредь заканчивать пораньше, жена уже не верит, что он ходит именно сюда."},{"id":"forge_096","kind":"note","title":"Ведро искр","text":"Гиббс, посылаю к тебе новенького за ведром искр. Подержи его до обеда и отправь к Малькольму за левой наковальней, как обычно. Рой. Ниже ответ: Рой, твоего новенького я оставлю у себя. Ведро он принёс вымытое. Пока ждал искр, он починил мне стул и накормил мою мать, а она приняла его за племянника. Оказалось, что родни у мальчика нет и идти ему некуда. Спасибо тебе, и пришли ещё кого-нибудь за искрами."},{"id":"forge_097","kind":"note","title":"Что берём","text":"Котёл берём. Одеяла берём, у моей матери зимой, говорят, холодно, мы уже забыли, как это бывает. Кур берём двух. Дальше детской рукой: ножик, камень из-под порога, чтобы грел. Ножик берём. Камень берём, потому что Джейми плакал, только греть он там перестанет. Джейми, сынок, снег не кусается, ты его просто не видел. Ладно, рукавицы тоже запишем, хотя надевать их ты не умеешь, научимся в дороге. Ключ от дома отдадим тёте Саре, если она не уедет раньше нас."},{"id":"forge_098","kind":"note","title":"Записка на двери","text":"Гектор, я ушла к маме. Я ухожу уже в четвёртый раз, просто в прошлые три ты этого не заметил, поэтому теперь пишу. Суп в кастрюле. Ниже его рукой: Прочитал. А ужин когда? Ниже третьей рукой: Гектор, это её мать. Ужин будет, когда ты придёшь к нам и скажешь ей хоть что-нибудь своими словами. Я ей про тебя всё уже сказала, теперь твоя очередь."},{"id":"forge_099","kind":"secret","title":"Кирпич","text":"В старой кладке под нашим домом я нашёл кирпич с отпечатком детской ладошки. Кто-то маленький потрогал ещё сырую глину, а кто-то большой не стал ругаться и отправил кирпич в печь. Таких у нас не делают уже очень давно, и город, который из них сложили, лежит под нами. Лили приложила к нему свою руку, и пальцы сошлись, мизинец в мизинец. Я вмазал кирпич в стену над её кроватью, и она с ним здоровается. Жене я сказал, что это для тепла."},{"id":"forge_100","kind":"secret","title":"Глухой","text":"Двадцать лет я притворяюсь глухим. При литейной оглохнуть не стыдно, и никто не удивился. Зато при мне теперь говорят всё: кто кому должен и что мастер думает о старшинах. Жена ругает меня вслух с утра до вечера, а ночью, когда думает, что я сплю, шепчет мне в затылок, что без меня ей было бы совсем худо. Я бы и рад сказать ей, что слышу. Но тогда она, пожалуй, перестанет."},{"id":"forge_101","kind":"secret","title":"Список храбрых","text":"список храбрых кто потрогал двер большой печи. Хэл потрогал. Молли потрогала и ревела но считается. Эйб потрогал два раза. кто потрогал клянётся никому не гаварить. когда Эйб трогал второй раз дверь тихонько стукнула ему в руку с той стороны. Эйб говорит он ей понравился. мы больше не трогаем. Эйб трогает"},{"id":"forge_102","kind":"secret","title":"Наследнику","text":"Тому, кто нашёл этот погреб. Здесь я гнал лучший самогон на Угольном ряду. Котёл греется от стены, даром, и за двадцать лет стена ни разу не остыла. Жена думает, что я хожу сюда за картошкой, и удивляется, как мало мы её едим. Теперь всё это твоё, мне лекарь запретил. Условие одно: каждую осень выливай чарку на могилу моего брата Рубена у северной ограды. Он первым попробовал мой самогон и сказал, что гадость. Извиниться он так и не успел."},{"id":"forge_103","kind":"secret","title":"Донесение старосте","text":"Староста Хендрик, ты послал меня узнать, правда ли в городе куют что-то против нас. Правда. Мне об этом рассказывают подмастерья и ещё угощают. Они куют цепь, чтобы мы не прошли по их мосту. Я спросил, что мы им сделали, и никто этого не знает. Домой я пока не вернусь. Я женился на дочери бондаря, и тесть считает меня человеком с севера, пусть и дальше считает. Передай моей матери, что я здоров, ем досыта и скоро привезу показать ей внука."},{"id":"forge_104","kind":"secret","title":"Тому, кто разберёт","text":"Тому, кто будет разбирать эту стену. Я знаю, что ты её разберёшь, мы ведь тоже разобрали ту, которая стояла тут до нас. Кирпичи хорошие, бери на здоровье. Третий снизу слева я клал после свадьбы брата, и он вышел кривой, положи его куда-нибудь, где не будет видно. Под подоконником лежит мой ножик, я прятал его от сына и забыл. Можешь оставить себе. У тебя, наверное, тоже есть сын. Береги спину, когда таскаешь, я вот не берёг."},{"id":"forge_105","kind":"secret","title":"Ведомость","text":"Про тех, кто перестал выходить на смену, мне велено писать в ведомости: уехал к родне. За этот год я написал так одиннадцать раз. Здесь я пишу, как было. Дик Марлоу никуда не уезжал, его мать живёт через улицу и каждый день меня спрашивает. Джозеф Рид тоже не уезжал, он сирота. Оба пошли вечером к большой печи и утром не вышли. Я держу эту бумагу за кирпичом, потому что кто-то должен знать их имена. Матери Дика я пока говорю, что письма идут долго."},{"id":"forge_106","kind":"secret","title":"Кости","text":"Эти кости залиты свинцом, я сделал их сам для одного-единственного игрока. Отец последние два года не вставал, и мы с ним каждый вечер играли на орехи. Он почти всегда выигрывал и очень гордился, говорил, что голова у него ещё работает, а сын у него дурак. Кости падали в его пользу. Когда он умер, я был должен ему триста орехов. Я их отдал, мать положила мешочек ему в гроб. Больше я в кости не играю."},{"id":"forge_107","kind":"secret","title":"Мёд","text":"Это мой мёд, и трогать его нельзя. В первый год после свадьбы я сказала Альфреду, что не люблю сладкое, чтобы ему досталось побольше. Он поверил, и вот уже двадцать шесть лет весь мёд в доме ест он один и меня жалеет. Поэтому горшок стоит здесь, за балкой. Если Альфред когда-нибудь его найдёт, пусть знает, что я его люблю и что мёд был вкусный."},{"id":"forge_108","kind":"secret","title":"Близнецы","text":"Мы с братом близнецы и уже девять лет работаем у Брэдшоу за одного человека по имени Фредерик. Настоящий Фредерик выходит с утра, а я, Фрэнсис, в ночь. Жалованье у нас одно на двоих, зато мы оба спим, а здесь больше никто этого не может сказать. Мать всё знает и смеётся. Позавчера брат не пришёл меня сменить. Я стою у горна вторые сутки, и Брэдшоу хвалит меня, говорит, что Фредерик сегодня особенно старается."},{"id":"forge_109","kind":"boss","title":"Письмо смотрителя","text":"Мастер, это пишет старый Джосая, смотритель моста. Я чинил тебе в детстве удочку, ты, наверное, не помнишь. Ты хоть раз ходил на мой мост? Он был двенадцать шагов в длину, через него гоняли коз. Поднимал я его сам, верёвкой, а цепь совет заказал для порядка. Та цепь, которую вчера везли мимо меня, толще этого моста. Приходи посмотреть, там теперь только сваи и вода. Я поставлю для тебя скамейку. Ты мне всё-таки как племянник.","boss":"boss_forge","floors":[5,6]},{"id":"forge_110","kind":"boss","title":"Письмо брату","text":"Брат, прочти и сожги. Двадцать лет назад, когда я был подмастерьем в Стоунбридже, мне поручили выковать звено для мостовой цепи. Я торопился на танцы к девушке, на которой потом женился, и ковал наспех. В ту ночь, когда пришли разбойники, мост не поднялся: цепь лопнула на одном звене. Я потом нашёл его в реке. Оно было моё. На том берегу сгорело сорок домов, а у меня родились дети. Теперь совет заказывает цепь мне. Я скажу им: принято.","boss":"boss_forge","floors":[5,6]},{"id":"forge_111","kind":"boss","title":"Семейная книга","text":"У нас на Молотовой теперь считают время по звеньям, потому что дни всё равно похожи один на другой. Мы с Кларой поженились на звене четыре тысячи двести, было жарко и весело. Ханна родилась на шести тысячах, и я понёс её показать мастеру. Он долго смотрел на неё, спросил, сколько она сможет потянуть, и сам засмеялся, и мы тоже засмеялись. Сейчас я пишу на звене девять тысяч. Ханне нужны новые башмаки, а мастер на прошлой неделе снова спросил, сколько ей лет.","boss":"boss_forge","floors":[5,6]},{"id":"forge_112","kind":"boss","title":"Жалоба пекаря","text":"Мастеру цеха от пекаря Тэлбота, вашего кума. Цепь лежит у меня в пекарне с прошлой осени. Я смирился, сушу на ней баранки и вешаю полотенца. Но вчера ваши люди вошли в нашу спальню и положили новые звенья поперёк кровати, а жена спросила меня, надолго ли это, и я не знал, что ей ответить. Вы крестили нашего Барта и ели за моим столом. Протяните её, прошу вас, с другой стороны дома. Спать мы пока согласны поперёк.","boss":"boss_forge","floors":[5,6]},{"id":"forge_113","kind":"boss","title":"Присяга цеха","text":"«Клянусь не отдавать заказчику вещи, в которой сомневаюсь». На полях рукой старого Уильяма Хейла: эту строчку мастер сочинил сам, когда ему было двадцать два года. Мы сидели в трактире, и он подсмеивался над лавочниками, которые торгуют подковами с трещиной. Мы все хохотали и выпили за неё. Теперь её читают вслух мальчики и боятся. Если бы я тогда знал, я дал бы ему по шее, по-дружески, и заказал бы ещё пива.","boss":"boss_forge","floors":[5,6]},{"id":"forge_114","kind":"boss","title":"Колечко","text":"дядя мастер дал мне колечко от цепи совсем маленькое на палец. он сказал оно слабое и для цепи не годится и если хочу могу забрать. я вешал на него ведро и оно не сломалось. потом я надел ево на гвоздь и повис сам и оно опять не сломалось. я пришёл сказать ему что оно хорошее. он посмотрел и сказал неси домой и больше не прихади тут жарко. он хороший только грусный","boss":"boss_forge","floors":[5,6]},{"id":"forge_115","kind":"boss","title":"Заключение","text":"По просьбе семьи мастера я приехал из Дарли и осмотрел цепь. За пятьдесят лет работы я не видел звеньев лучше, и слабого места у неё нет. Родные просили меня сказать это ему прямо, надеясь, что тогда он остановится, и я сказал. Он взял меня за руку и заплакал, и я сам едва не заплакал. Потом он спросил: ну а следующее? Денег с его жены я не взял, даже на дорогу. Она ждала меня у двери и всё поняла по моему лицу.","boss":"boss_forge","floors":[5,6]},{"id":"forge_116","kind":"boss","title":"Письмо священника","text":"Дочь моя, вы просили написать, приходил ли ваш отец на могилу матери. Приходил. Это было ночью, на кладбище оставался один сторож, он мне и рассказал. Ваш отец долго стоял и потом положил на могилу звено, потому что ничего другого у него давно нет. Он сказал ей, что оно пока слабое, и извинился, что не принёс получше. Я велел сторожу его не убирать. Железо ещё тёплое, и трава вокруг пожелтела, но ваша мать, я думаю, не стала бы сердиться.","boss":"boss_forge","floors":[5,6]},{"id":"halls_001","kind":"note","title":"Жалоба ректору","chain":"bell","part":1,"text":"Господин ректор! Магистр Рен продолжает уверять за обедом, что под полом нижней палаты по большим праздникам звонит какой-то другой колокол. Это эхо нашего собственного, о чём я писал ещё в трактате. Мы с этим упрямым ослом сидим за одним столом двадцать шесть лет, я знаю все его глупости наизусть и успел к ним привязаться, но эту прошу запретить, особенно при студентах и особенно за супом. Доктор Холт."},{"id":"halls_002","kind":"note","title":"Ответ магистра","chain":"bell","part":2,"text":"Господин ректор, наш колокол треснул ещё при прошлом мэре и звучит как ведро. А тот, что слышно снизу, звучит чисто и начинает раньше нашего. Эхо, насколько мне известно, вперёд звука не забегает. Доктор Холт спускался в подвал последний раз в день получения степени, и то за вином. Передайте ему, пожалуйста, что он глух как пень и что моя жена ждёт его в воскресенье к гусю, как всегда. Магистр Рен."},{"id":"halls_003","kind":"note","title":"Записка доктора","chain":"bell","part":3,"text":"Рен, старый ты осёл, я спустился в нижнюю палату с двумя студентами и лампой, чтобы опровергнуть тебя при свидетелях. В час большого звона я приложил ухо к полу, и студенты подтвердят, что я простоял так до самого вечера. Опровержение пока откладываю. Ты забыл там свой шарф. Он мокрый, хотя пол сухой, и мне это не нравится. Надень другой, а то опять сляжешь, и с кем я тогда буду спорить?"},{"id":"halls_004","kind":"note","title":"Объявление","chain":"bell","part":4,"text":"Лекции доктора Холта и магистра Рена отменяются до окончания спора. Оба спустятся через люк под нижней палатой лично и вместе, по верёвке, поскольку ни один из них не верит другому на слово. Проигравший до конца жизни будет мыть чернильницы победителя. Ключ от кафедры я оставил у сторожа. Студентов прошу не занимать их стулья: спор закончится к четвергу. Ректор."},{"id":"halls_005","kind":"note","title":"Записка сторожа","chain":"bell","part":5,"text":"Господин ректор, я третью зиму храню ключ от кафедры, как мы договаривались. Чернильницы на обоих столах высохли, но мыть их я не стал, вдруг это повлияет на результат. В дни большого звона снизу теперь слышно ещё и стук, будто двое спорят и перебивают друг друга. Прошу выдать новую верёвку, у старой нижние шесть саженей всё время мокрые. Супруга магистра Рена по-прежнему жарит по воскресеньям гуся и спрашивает меня, не слышно ли чего. Я не знаю, что ей отвечать."},{"id":"halls_006","kind":"note","title":"Прошение","chain":"step","part":1,"text":"В канцелярию. Третья ступень парадной лестницы шатается уже шестой год. На прошлой неделе мой муж Гарольд упал с неё и сломал ногу, а шёл он к вам как раз с жалобой на эту самую ступень. Я сорок лет прошу его смотреть под ноги, и сорок лет он отвечает, что смотрит. Теперь он лежит дома и злится, а мне его жалко. Прошу починить. Милдред Оукс, Кожевенная улица."},{"id":"halls_007","kind":"note","title":"Ответ канцелярии","chain":"step","part":2,"text":"Госпоже Оукс. Лестницами у нас ведает Палата Входов, а ступенями Палата Мощения, поскольку ступень есть поднятая мостовая. Просим указать, какая именно ступень третья, считая снизу и считая сверху, и приложить справку о ноге. Пошлина за справку составляет две монеты. От себя добавлю, сударыня, что мне очень жаль вашего мужа. Постарайтесь уместить следующее прошение на одном листе, так вам выйдет дешевле. Младший писарь Симон."},{"id":"halls_008","kind":"note","title":"Прошение второе","chain":"step","part":3,"text":"В Палату Мощения. Речь идёт о третьей ступени снизу, она же девятая сверху, она же та, возле которой всегда стоит лужа. Справку о ноге прилагаю. Нога у мужа срослась криво, а справку на кривую ногу лекарь пишет отдельно, за три монеты, которых у нас нет. Гарольд ворчит, что я зря хлопочу, а сам каждый день спрашивает, нет ли ответа. В корзине лежит пирог для писаря Симона, который в прошлый раз был со мной вежлив. Милдред Оукс."},{"id":"halls_009","kind":"note","title":"Извещение","chain":"step","part":4,"text":"Госпоже Оукс. Прошение ваше удовлетворено, ступень будет починена весной. Извещаем также, что ваш супруг замечен на площади среди прочих горожан. Он стоит хорошо, на обеих ногах, и костыли ему больше не нужны. Просим забрать их из гардероба, они мешают. Приписка от руки: сударыня, пирог был очень вкусный, и мне жаль. Не ходите на площадь его звать. Я вчера пробовал, он не оборачивается. Симон."},{"id":"halls_010","kind":"note","title":"Письмо домой","chain":"percy","part":1,"text":"Дорогая матушка! Книга по риторике стоит шесть монет, и без неё меня отчислят. Пришлите шесть, а лучше семь. Я очень скучаю по вашим блинам и ем здесь одну репу, так и передайте отцу. Вчера у шляпника Пинчера я видел шляпу точь-в-точь как у отца, только зелёную. Это к делу не относится. Целую ваши руки, не болейте и не таскайте воду сами. Ваш любящий сын Перси."},{"id":"halls_011","kind":"note","title":"Письмо домой","chain":"percy","part":2,"text":"Дорогая матушка! Книгу я купил, спасибо. Она зелёная, с полями и очень мне идёт. Денег пока больше не присылайте, у нас творится странное: снег не лежит, печи никто не топит, в спальне жарко, и все сидят с открытыми окнами. Лекции пока идут. Доктор Брэдли уверяет, что это к хорошей погоде, но выглядит он нездорово. Вы писали, что отец кашляет, пусть пьёт горячее. Я приеду, как только просохнут дороги, и признаюсь вам кое в чём насчёт книги."},{"id":"halls_012","kind":"note","title":"Письмо ректора","chain":"percy","part":3,"text":"Сударыня! С прискорбием сообщаю, что студент Перси Вуд отчислен за пропуски. С первого снега он не был ни на одном занятии. С утра он стоит на площади вместе с прочими и на все вопросы отвечает, что ему хорошо. Я сам подошёл к нему и протянул ваше письмо, но он его не взял. Шляпу, зелёную, он оставил в спальне. Можете забрать её у привратника в любой день, кроме среды. Мальчик он был способный и очень ею гордился."},{"id":"halls_013","kind":"note","title":"Табличка","text":"Просьбы принимаются по вторникам, жалобы по средам. Жалобы на то, что просьбы принимаются по вторникам, не принимаются. Обращайтесь к младшему писарю, старший болеет с весны. Мать младшего писаря просит на него не кричать."},{"id":"halls_014","kind":"note","title":"Протокол","text":"Первым вопросом совет рассмотрел ремонт моста и отложил его. Вторым вопросом совет выяснял, кто съел пирог, принесённый к первому вопросу. Прения заняли четыре часа. Постановили образовать комиссию по пирогу, председателем назначили советника Тибальда, а его мантию с крошками приобщили к делу. Председатель просил записать, что пирог был с капустой, как у его покойной матушки, и что больше он ничего не скажет."},{"id":"halls_015","kind":"note","title":"Налог на окна","text":"Кожевенная улица. Реннер платит за шесть окон шесть монет, Хэтч за три окна три монеты. Фиддл заложил кирпичом пять окон из шести и платит одну монету. Жена Фиддла подала жалобу на Фиддла, потому что в доме стало темно и она не видит, что вяжет. Жалобу мы приняли, пошлина две монеты. Фиддл заплатил пошлину за жену сам и сказал, что так всё равно дешевле."},{"id":"halls_016","kind":"note","title":"Упражнение","text":"Логика, задача четвёртая. Если Тибальд берёт взятки, Тибальд покупает лошадь. Тибальд купил лошадь. Следует ли из этого, что Тибальд берёт взятки? Ответ ученика: да. Учитель написал чернилами: «Неверно, зачеркни и перепиши». Ниже тот же учитель спросил карандашом: «А какой масти лошадь, ты сам её видел?»"},{"id":"halls_017","kind":"note","title":"Ученику писаря","text":"Перо чини от себя, а чернила на ночь закрывай. Если проситель плачет, дай ему сесть, только не на стул с целой ножкой, он у нас один и стоит для советника. Слово «немедленно» в наших бумагах означает «весной». По пятницам подметаешь ты. Твоя мать просила меня следить, чтобы ты ел, так что обедаешь ты теперь в полдень, и это приказ."},{"id":"halls_018","kind":"note","title":"Записка","text":"Хильда, я нашёл в архиве дело твоего деда, того самого, что украл гуся. Теперь оно закрыто в его пользу, потому что сегодня после обеда я сам его закрыл. Приходи в среду к полке с соляными податями, там никто не бывает. Там немного дует, так что надень что-нибудь тёплое. Мне очень хочется увидеть, как ты будешь смеяться. Твой Оливер."},{"id":"halls_019","kind":"note","title":"Молитва","text":"Святая Ида Чернильная, сделай так, чтобы на экзамене меня спросили про реки. Рек я выучил две. Если про реки нельзя, пусть заболеет доктор Холт, только не сильно и на один день. Мать продала козу, чтобы я мог здесь учиться, и я не могу вернуться домой и сказать ей, что провалился. Обещаю поставить свечу, как только у меня появятся деньги."},{"id":"halls_020","kind":"note","title":"Счёт трактира","text":"Трактир «Перо и кружка», счёт за месяц. Кафедра риторики выпила четырнадцать кружек. Кафедра логики выпила девять и разбила окно. Кафедра богословия выпила две и просила никому не говорить. Кафедра счисления итог оспаривает. Доктор Холт и магистр Рен снова ругались, кто за кого платит, и в конце концов оба заплатили за обоих. Я не стал их поправлять."},{"id":"halls_021","kind":"note","title":"Эпитафия","text":"Списано с надгробия для книги совета. «Здесь покоится Бертрам Флэкс, сорок лет секретарь совета. Слушали. Постановили». Ниже кривыми буквами кто-то нацарапал гвоздём: «Он хорошо пел. Каменщику за эту строчку мне заплатить было нечем, и я написала её сама. Берти, мне без тебя очень тихо»."},{"id":"halls_022","kind":"note","title":"Акт порчи","text":"Мыши съели все дела на букву Г, целиком. Граждане на букву Г временно считаются незарегистрированными и налогов не платят. С понедельника мы получили двенадцать прошений о перемене фамилии на Гудмен. Прошения принимаются за одну монету, очередь стоит вдоль левой стены. Первой в очереди стоит моя тёща, и она впервые за девять лет мне улыбнулась."},{"id":"halls_023","kind":"note","title":"Опись редкостей","text":"Опись за год. У нас хранится сушёная рыба с ногами, одна штука. Хранится череп, и ни одна кафедра не признаёт его своим. Есть ящик с надписью «не для ректора», я его не вскрывал. Есть левая перчатка, всегда тёплая, и при каждой описи она лежит на другом столе. Прошу вынести перчатку из описи, она портит мне отчётность. Сторож говорит, что она просто ищет вторую, и теперь мне её жалко."},{"id":"halls_024","kind":"note","title":"Шпаргалка","text":"Королей звали Эдмунд Первый, Эдмунд Второй и Эдмунд Хромой, который, кажется, и есть Второй. Налог на дым ввели при ком-то из них. Если спросят дату, надо закашляться. Не забыть спросить у Перси, что такое десятина, и вернуть ему перо. И написать маме, что я жив, а то она опять приедет и будет при всех поправлять мне воротник."},{"id":"halls_025","kind":"note","title":"Правила читальни","text":"Прошу не слюнить страницы и держать свечу на блюдце. С трактатом о ядах работайте в перчатках, с трактатом о подвалах не работайте вовсе. Профессор Фабиан спит в третьем ряду со дня открытия. Не будите его, пока мы не решим, кому это поручить. Каждую осень дочь приходит укрыть его новым пледом и просит вас не шуметь."},{"id":"halls_026","kind":"note","title":"Квитанция","text":"Получен от мясника Гранта один окорок на нужды комиссии по проверке весов. Комиссия состоит из меня одного. Весы признаны верными, окорок тоже. Половину окорока комиссия отправила своей матери, которая жалуется, что комиссия ей не пишет. Д. Ларкин, сборщик."},{"id":"halls_027","kind":"note","title":"Объявление секретаря","text":"Кто взял большую печать, верните её, пожалуйста. Всё, что скреплено малой печатью с прошлого четверга, считается скреплённым большой. Малая печать тоже пропала, и пока мы пользуемся пуговицей. Из-за этой путаницы вдова Крэм третий день числится замужем за Хейзом. Просим не беспокоить по этому поводу её и особенно Хейза: он двадцать лет не решался с ней заговорить и теперь боится, что бумагу исправят."},{"id":"halls_028","kind":"note","title":"Выдача дров","text":"Первая неделя после сбора яблок, поставка последняя. На Кожевенную мы выдаём по вязанке на дом, а где есть больной, по две. Школе не досталось ничего, детям велено приходить в отцовских куртках. Совету ушло шесть возов, в подвал, под замок. На полях чужой рукой: «Лоренс, куда делся седьмой воз? Моя мать третий день жжёт стулья, а я думал, что мы с тобой друзья»."},{"id":"halls_029","kind":"note","title":"Записка жене","text":"Гвен, к ужину меня не жди, я стою в очереди у весовой. Говорят, у ворот снова раздают муку, хотя я уже не знаю, кто её раздаёт. Если к темноте не вернусь, возьми с полки чёрную кружку, в ней лежит расписка, и сходи к Винсенту, он должен нам с лета. На ночь закрой дверь на оба засова и дров не жалей, потом разберёмся. Поцелуй за меня Дэйви и не сиди у окна, я постараюсь вернуться скоро."},{"id":"halls_030","kind":"note","title":"Сочинение","text":"Моя зима. зимой холодно а этой зимой тепло. у нас сняли двери патамушта незачем. папа сказал пишы что хочеш толко про ворота непиши. я непишу про ворота. мы отпустили собаку она ушла туда и не вернулась но она взрослая. я каждый вечер оставляю ей кость на пароге."},{"id":"halls_031","kind":"note","title":"Замеры снега","text":"Тимоти, проверьте, пожалуйста, мою линейку. В первый день снег у ратуши лежал по локоть. На второй день у ратуши стало сыро, а за стеной снега было по колено. На третий день площадь совсем высохла, а часовые говорят, что снаружи намело по грудь и край снега идёт вдоль стены ровно, будто его отрезали ножом. Я двадцать лет измеряю снег и никогда ни о чём вас не просил. Зайдите ко мне вечером, мне страшно."},{"id":"halls_032","kind":"note","title":"На полях","text":"Автор дурак. Ниже, другими чернилами: Сам дурак, автор это я. Ниже, третьей рукой: Автор умер в прошлом веке. Снова второй рукой: Знаю. Я сам удивился."},{"id":"halls_033","kind":"note","title":"Письмо сыну","text":"Симон, сынок, передаю с Бетт пирог и чистые манжеты. Писарь в грязных манжетах никогда не выйдет в секретари, вот и отец твой не вышел, хотя человек был хороший. Твой кашель слышно через всю площадь, и люди спрашивают меня, чей это. Я отвечаю, что мой. Попроси кого-нибудь посмотреть твою печь, она у тебя дымит, а ты и не замечаешь. Ешь горячее и пиши матери хоть раз в неделю, я уже забываю твой почерк."},{"id":"halls_034","kind":"note","title":"Приютская книга","text":"Девочка лет семи, найдена у ворот в первый снег. Назвать своё имя не может. На вопрос, как её зовут, отвечает «потом», потому что так ей сказала мать, уходя. Записана в приютскую книгу как Потом Воротная. Ест хорошо. Каждый вечер она садится у окна лицом к воротам, и я сажусь рядом с шитьём, чтобы ей не было одиноко. Сестра Агнес."},{"id":"halls_035","kind":"note","title":"Преемнику","text":"Шкаф слева не закрывается, а шкаф справа не открывается. Вдова Кэрью приходит по пятницам, дела у неё давно нет, поэтому не спорь с ней и дай ей сесть. Мёд в третьем ящике оставляю тебе. В четвёртый не заглядывай, там лежит мой обед с прошлой осени. Береги спину и уходи домой вовремя: я просидел здесь тридцать лет, и за это мне никто спасибо не сказал. Вдова Кэрью, правда, сказала, так что ты с ней поласковей."},{"id":"halls_036","kind":"note","title":"Анекдот","text":"Вчера в трактире рассказали про сборщика податей. Умер он, пришёл к вратам и спрашивает: «Куда мне, вверх или вниз?» Ему говорят: «Как совесть подскажет». Он задумался и спрашивает: «А где дешевле?» Смеялись все, кроме сборщика Ларкина, он записывал, кто смеялся. Его мать как раз принесла ему обед и смеялась громче всех, её он записал первой."},{"id":"halls_037","kind":"note","title":"Дневник переписчика","text":"Сегодня я переписывал четвёртый том венчаний и нашёл свадьбу своих родителей. У тогдашнего писаря был плохой почерк, и мать он записал как Эдит, а она всю жизнь была Эдна. Я исправил. Потом я долго сидел над этой страницей, потому что отец расписался там так старательно, будто сдавал экзамен. Лёг поздно, свечу списал на канцелярию."},{"id":"halls_038","kind":"note","title":"Расписание стражи","text":"Ночная стража у ворот. Понедельник: Нед. Вторник: Нед. Среда: Нед, потому что Тобиас занят. Четверг: Нед просит его заменить, потому что ночью кто-то снаружи спрашивает его, не холодно ли ему. Пятница: Нед, замены мы не нашли. Выдать Неду шарф. Приходила его мать, спрашивала, почему всё время он, и я сказал ей, что Нед у нас лучший. Она ушла довольная. Прости меня, Нед."},{"id":"halls_039","kind":"note","title":"Табличка","text":"Казначейство закрыто на сверку и откроется, когда всё сойдётся. Суп ставьте у двери, миску заберёте утром, она будет пустая и чистая. Просьба не стучать, он сбивается. Ниже приписано другой рукой: «Генри, ты считаешь уже четвёртый год. Пусть не сходится, выходи, я соскучилась»."},{"id":"halls_040","kind":"note","title":"Афиша лекции","text":"В четверг в большой палате доктор Брэдли прочтёт лекцию «О природе тепла и её благодетельных последствиях». Шубы сдавать в гардероб не нужно, шубы в этом году вообще никому не нужны. Лекция «О природе холода» отменена, потому что лектор не отвечает на наши запросы. Его сестра просит всех, кто его видел, зайти к ней на Хлебную улицу."},{"id":"halls_041","kind":"secret","title":"Книга очагов","text":"Старик, который смотрит за костром на площади. Подать за очаг мы с него не берём, потому что он значится в этой книге и при моём деде, и при деде моего деда, всякий раз в одной и той же графе. Откуда он прибыл, он не сказал. Когда я пришёл его записывать, он спросил, почему писарь так долго, и налил мне чаю с мёдом. Он сказал, что мой дед любил именно с мёдом, и это правда."},{"id":"halls_042","kind":"secret","title":"Статья устава","text":"Устав совета, статья без номера. Если город падёт, огонь с площади надлежит вынести наверх прежде казны. Тот, кто принял ведро с углями, уходит и не оглядывается, даже если здесь остаются его родные. Кому идти, решает старик у костра. Совет на этот счёт не совещается и протокола не ведёт. На полях карандашом: «Я переписал это и весь вечер просидел у матери, ничего ей не объясняя»."},{"id":"halls_043","kind":"secret","title":"План города","text":"Ректору не показывать. Я купил у старьёвщика план города, очень старый. Площадь на нём находится на нашем месте, и костёр отмечен там же, а на Хлебной улице нарисованы канал и пристань. Никакого канала у нас нет. Возчик Гарт говорит, что в его подвале весной пахнет тиной и что он давно привык. Покажу план брату: он смеётся над всем, что я покупаю, но тут, пожалуй, смеяться не станет."},{"id":"halls_044","kind":"secret","title":"Настоящий подсчёт","text":"Пишу для себя. Чёрных камешков было двести шесть, белых триста сорок, и за белыми люди ходили на реку, раз на рынке их не оказалось. Совет велел записать наоборот, потому что сын угольщика обходится городу дешевле. Мне приказано сжечь эту бумагу, но бумага нынче дорога. А ещё я видел, как моя старая соседка Нэн шла на реку пешком, по морозу, с больными ногами, за одним белым камешком. Пусть это хоть где-то будет записано."},{"id":"halls_045","kind":"secret","title":"Дровяной список","text":"Вот кому в последнюю зиму я приписал дров по поддельной бумаге: вдове Кэрью две вязанки, детям Арденов четыре, слепому Нату три. Если это найдёт ревизор, прошу учесть, что почерк у меня красивый и что я раскаиваюсь, только не сейчас. Слепому Нату я сказал, что дрова от совета. Он рассмеялся, похлопал меня по щеке и велел беречь себя."},{"id":"halls_046","kind":"secret","title":"Признание","text":"Степень я получил за трактат, который переписал у покойного. Покойного звали Хью, он был мой брат и писал лучше всех, кого я знал, а я умел разговаривать с ректором. При жизни он отдавал мне всё, что у него было, и я решил, что он не обидится. Я и теперь так думаю, только по ночам хуже. Если кто-нибудь это найдёт, прошу поставить его имя на книге. Она стоит на пятой полке, кажется. В тот ряд я давно не захожу."},{"id":"halls_047","kind":"secret","title":"Устав братства","text":"Устав Братства Подвальной Свечи. Наша цель: узнать, что находится внизу. Собираемся по четвергам. Нас трое, взнос составляет одну свечу. Последнее собрание не состоялось: Бен боится, Клара боится, я тоже боюсь, но я секретарь и обязан это записать. Следующее собрание проведём у Клары, её мама печёт яблочный пирог, и там совсем не страшно."},{"id":"halls_048","kind":"secret","title":"Смета","text":"Каменщики просят доплаты: на дне котлована под ратушу им попалась чужая крыша, целая, с трубой. Совет заплатил, велел считать крышу фундаментом и в бумагах больше не упоминать. Черепица оказалась хорошая, её забрали на кухню. Записываю уже не для сметы: старый Уилл снял шапку, прежде чем класть на эту крышу первый камень, и велел снять остальным. Мастер его обругал, а потом снял и сам."},{"id":"halls_049","kind":"secret","title":"Письмо матери","text":"Сынок, я понимаю, что тебе теперь некогда. Помнишь воробьёв, которых ты зимой приносил домой в шапке? Отец ругался, а ты клал их к печке и ревел, если какой не отогревался. Мне передали, что ты плохо спишь. Поешь чего-нибудь горячего, ради меня. В городе теперь тепло, все говорят, что это ты, а я всё равно мёрзну. Зайди ко мне, когда сможешь. Я не буду ни о чём спрашивать."},{"id":"halls_050","kind":"secret","title":"За шкафом","text":"За шкафом я нашёл листок, очень старый, на незнакомом письме. Прочесть его я не смог, но кто-то нарисовал там домик с дымком. Я положил его обратно и рядом оставил вот этот. Рисую тоже: домик, дымок и ещё собаку, у нас есть собака, её зовут Пуговка. Дочка подрисовала солнце и велела сказать тебе, кто бы ты ни был, что у нас тут хорошо. Если найдёшь, добавь своё."},{"id":"halls_051","kind":"boss","title":"Хроника","chain":"mayor","part":5,"boss":"boss","floors":[1,8],"text":"Ключи от ворот ему вручили в ночь первого снега. К утру в городе стало теплее, и люди вышли благодарить мэра на площадь. У мэра было хорошее лицо, а тень от него ложилась к костру."},{"id":"halls_052","kind":"boss","title":"Предвыборный листок","chain":"mayor","part":1,"boss":"boss","floors":[1,8],"text":"Горожане! В мэры идёт сын угольщика. Четыре зимы он развозил дрова вдовам и денег с них не брал, и многие из вас сами видели его на своём пороге. Он говорит, что больше в этом городе никто не замёрзнет, а мать его подтверждает, что слов на ветер он не бросает. Голосуем в четверг у рыночных весов: чёрный камешек за него, белый против. Белых камешков на рынке сейчас нет, мы выясняем почему."},{"id":"halls_053","kind":"boss","title":"Письмо сестре","chain":"mayor","part":2,"boss":"boss","floors":[1,8],"text":"Мэрион, дрова подорожали втрое, обозов нет с самого сбора яблок. Новый мэр сам принёс старой Иде вязанку и сел чистить ей печь, представляешь? А вечерами он ходит к воротам и подолгу там стоит, и стражники говорят, что он с кем-то разговаривает. Привези шерсти, если доедешь, Робину совсем не в чем ходить. А лучше просто доедь, сестрёнка. Мне без тебя здесь неспокойно."},{"id":"halls_054","kind":"boss","title":"Постановление","chain":"mayor","part":3,"boss":"boss","floors":[1,8],"text":"Совет постановил: ввиду нехватки дров и болезни привратника передать ключи от ворот господину мэру, чтобы он мог принять обоз, когда обоз придёт. Вручить их в первый снег, как велит обычай. Шесть советников проголосовали за. Советник Тибальд проголосовал против и просил записать, что обоза никто не видел и что привратник, его друг с детства, вчера вечером был совершенно здоров. Записано."},{"id":"halls_055","kind":"boss","title":"Расписка привратника","chain":"mayor","part":4,"boss":"boss","floors":[1,8],"text":"Я, Вальтер Кросс, привратник, сдал господину мэру два ключа, большой и от калитки, которые носил сорок один год. На обороте, уже дома: Марта, ты спала, и я не стал тебя будить. Господин мэр расписался и спросил, слышу ли я, как снаружи дышат. Я сказал, что туговат на ухо. Он сказал, что это хорошо, и велел идти домой спать. Я слышал, Марта. Шёл снег, первый в этом году. Я лёг не раздеваясь, а ты утром, прошу тебя, не открывай дверь."},{"id":"halls_056","kind":"boss","title":"Указ","boss":"boss","floors":[1,8],"text":"Указ господина мэра. Налог на дрова отменяется за ненадобностью. Трубочистам выдать жалованье вперёд и распустить. Горожанам разрешается не носить шапок. На обороте записка для писаря: подпись опять прожгла лист, закажи бумагу потолще и не жалуйся на запах. Писарь отправил эту копию домой и приписал снизу: «Мама, шапку всё равно носи»."},{"id":"halls_057","kind":"boss","title":"Письмо дяде","boss":"boss","floors":[1,8],"text":"Дядюшка Кларенс, приезжайте к нам, шубу можете не брать. Всю зиму у нас тепло, снег не лежит, на улицах даже ночью можно спать, и дети спят, им нравится. Вороны улетели, а так всё хорошо. Мэр говорит, что ворота теперь открыты для всех, и спрашивал про вас, он вообще про всех спрашивает. Вы давно не видели маленькую Лотти. Она теперь совсем не плачет и не просит есть. Приезжайте и тётю привозите, мы все по вам соскучились."},{"id":"halls_058","kind":"boss","title":"Счёт живописца","boss":"boss","floors":[1,8],"text":"За парадный портрет господина мэра двенадцать монет. За второй холст ещё две, потому что первый покоробился, пока господин мэр стоял рядом. За вторую коробку охры три монеты. Лицо получилось хорошее, заказчик доволен. На обороте этой копии: Бесс, получи деньги по счёту и собирай детей. В ратуше я сказал, что уезжаю к сестре, а сестры у меня, как ты знаешь, нет. Я жду вас на мельнице у Хэтчей. Вещей много не бери."},{"id":"halls_059","kind":"boss","title":"Детской рукой","boss":"boss","floors":[1,8],"text":"мэр падарил мне прянек. он был горячий. мама сказала ешь и скажи спасибо. я сказал спасибо. он сказал пажалуста а рот неоткрывал. я спрятал прянек под кравать он там до сих пор горячий. мне страшна но маме я неговарю а то она тоже забоица."},{"id":"halls_060","kind":"boss","title":"Прошение в совет","boss":"boss","floors":[1,8],"text":"Просим вернуть ключи от ворот привратнику Вальтеру. Мы знаем его всю жизнь, и он ни разу нас не подвёл. Подписи: Хьюберт, сапожник. Мод Арден, вдова. Ниже кто-то дописал ровным почерком: Хьюберт отзывает подпись и благодарит за заботу. Мод Арден отзывает подпись и благодарит за заботу."},{"id":"halls_061","kind":"note","title":"Требование в читальню","chain":"slips","part":1,"text":"Прошу выдать второй том сочинения «О пчёлах». Первый том я возвращаю и должен предупредить, что оставил в нём закладку с признанием: у вас очень красивый почерк. Если это неуместно, сожгите закладку, книга тут ни при чём. Я хожу к вам уже второй год и каждый раз боюсь, что вы спросите, зачем переписчику столько знать про пчёл. Ансельм Прайс."},{"id":"halls_062","kind":"note","title":"Бланк выдачи","chain":"slips","part":2,"text":"Господину Прайсу. Второй том выдан. Закладка изъята как посторонний предмет и хранится у меня в ящике, потому что правила читальни не позволяют сжигать имущество читателей. Почерк у меня самый обычный, а вот у вас на слове «красивый» стоит клякса. Рекомендую вам взять третий том. Он самый скучный из всех, но я всё равно буду рада, если вы за ним придёте. Розамунд Грей, хранительница."},{"id":"halls_063","kind":"note","title":"Новое требование","chain":"slips","part":3,"text":"Госпожа Грей, третий том я прочёл и теперь знаю о трутнях больше, чем мне хотелось бы. Вчера я проверил каталог: четвёртого тома не существует. Мне больше нечего у вас просить, и это меня пугает, потому что ходить к вам без дела я не умею. В воскресенье на лугу будет ярмарка. Вы пошли бы туда со мной? Ответьте на этом бланке, он всё равно испорчен."},{"id":"halls_064","kind":"note","title":"Запись в каталоге","chain":"slips","part":4,"text":"В каталог внесён четвёртый том сочинения «О пчёлах», рукопись, один экземпляр, автор Р. Грей. Выдаётся только читателю Прайсу, только в воскресенье и только на ярмарке. Читать его придётся вслух и вдвоём, потому что я его ещё не написала. Наденьте, пожалуйста, шляпу, Ансельм. Я давно заметила, что вы ходите с красными ушами."},{"id":"halls_065","kind":"note","title":"Читательская карточка","chain":"slips","part":5,"text":"Читатель: Ансельм Прайс. Сочинение «О пчёлах», том четвёртый, выдан тридцать один год назад. Продлено. Продлено. Продлено. Внизу рукой хранительницы: «Анс, шестой год я продлеваю твою книгу без тебя. Этой зимой стало тепло, наши пчёлы вылетели в январе и не вернулись. Ты бы мне всё объяснил. Продлеваю ещё на год, пусть книга пока полежит у твоей кровати»."},{"id":"halls_066","kind":"note","title":"Договор","chain":"coat","part":1,"text":"Мы, Джаспер Лоу и Нил Арчер, студенты, имеем на двоих один приличный кафтан. Договорились так: в понедельник, среду и пятницу кафтан носит Джаспер и ходит на лекции. Во вторник, четверг и субботу кафтан носит Нил и ходит на лекции. В свободный день каждый сидит дома и переписывает записи другого. Кто посадит на кафтан пятно, тот чистит его сам и извиняется. Мы знаем друг друга с шести лет и подписываем это больше для порядка."},{"id":"halls_067","kind":"note","title":"Записка соседу","chain":"coat","part":2,"text":"Нил, у нас беда. Доктор Хэмлин похвалил меня за ответ, который вчера дал ты, а сегодня спросил, почему я так внезапно поглупел. В его ведомости мы записаны как один студент по фамилии Лоу-Арчер, который ходит каждый день и очень старается. Стипендию этому студенту дадут одну, зато полную. Я подумал и решил не поправлять доктора. Кафтан я повесил на гвоздь. Там в кармане лежит хлеб, он твой."},{"id":"halls_068","kind":"note","title":"Экзаменационный лист","chain":"coat","part":3,"text":"Студент Лоу-Арчер в первый день экзамена блестяще отвечал по риторике и совершенно не знал счёта. На второй день всё было наоборот. За сорок лет службы я не встречал такого странного ума. Кафтан у студента заметно вытерся на локтях. Экзамен я ему засчитываю, и пусть оба, сколько бы их там ни было, зайдут ко мне в воскресенье на кухню, моя жена их покормит. Доктор Хэмлин."},{"id":"halls_069","kind":"note","title":"Записка в кармане","chain":"coat","part":4,"text":"Нил, сегодня четверг, твой день. Вчера ты ушёл на площадь в одной рубахе и домой не вернулся, поэтому я принёс кафтан туда. Руки ты не поднял, так что я накинул его тебе на плечи и застегнул верхнюю пуговицу. Все говорят, что теперь тепло и кафтаны никому не нужны, но договор никто не отменял. В пятницу я приду его забрать, а в субботу принесу обратно. Ты мне только скажи, если он жмёт."},{"id":"halls_070","kind":"note","title":"Голубиная почта","chain":"pigeon","part":1,"text":"Кора, долетел ли Рыжий? Ректор теперь выдаёт бумагу по счёту, так что пишу мелко. Я здоров и очень скучаю. Как твоя матушка, всё ещё считает меня никчёмным? Передай ей, что с осени я младший хранитель свитков и теперь никчёмен за жалованье. Ответ привяжи к левой лапке, к правой он не даётся и клюётся. Твой Эдвин."},{"id":"halls_071","kind":"note","title":"Голубиная почта","chain":"pigeon","part":2,"text":"Эдвин, Рыжий долетел и съел всё матушкино просо. Она считает тебя никчёмным и велела спросить, есть ли у тебя шерстяные носки. У нас на хуторе замело по самые окна. Что значит, у вас оттепель и ты сидишь с открытым окном? Сосед Огден вчера съездил к вашим воротам, вернулся очень быстро и теперь забивает ставни. Напиши мне толком, что у вас творится, и закрой окно. Кора."},{"id":"halls_072","kind":"note","title":"Голубиная почта","chain":"pigeon","part":3,"text":"Рыжий прилетает ко мне уже пятый раз без записки, и лапка у него тёплая. Я всё равно пишу тебе и отправляю его обратно. Матушка сама накрошила ему хлеба и велела написать тебе, что она была неправа. Ты слышишь, никчёмный мой? Она сказала это при мне и при соседях, вслух. Напиши хоть одно слово. Один носок я уже довязала, сижу над вторым и к весне как-нибудь тебе их привезу."},{"id":"halls_073","kind":"note","title":"Рассадка гостей","text":"Брэм, вот как мы сажаем гостей на свадьбу. Тётю Беатрис не сажай рядом с тётей Гертрудой, они шестнадцать лет не разговаривают из-за ложки. Советника Мэллори посади подальше от пирога. Твоего отца посади возле двери, он всё равно уйдёт курить трубку. Мою сестру посади рядом с писарем Эндрю, только ты ей об этом не говори и ему не говори. Нас с тобой посади во главе стола, и я хочу, чтобы хоть в этот день ты смотрел на меня и не считал вилки."},{"id":"halls_074","kind":"note","title":"Записка профессору","text":"Господин профессор анатомии, я двенадцать лет протираю вашего скелета по субботам и зову его Альбертом, простите, если это против науки. Вы велели ничего в зале не двигать, но он стоял под самым окном, а там ужасно дует. Я перенесла его ближе к печке. Одна косточка от ступни закатилась за шкаф, я её достала и положила вам на стол, потому что не знаю, куда её вставлять. Дорис."},{"id":"halls_075","kind":"note","title":"Объяснительная","text":"Господину ректору от студента Годфри Пула. Овца оказалась на кафедре богословия не по моей вине. Я только вёл её по коридору и только до лестницы, а дальше она пошла сама. Профессор Тэлбот действительно читал лекцию целый час, не замечая овцу, но в этом я тоже не виноват. Прошу не сообщать отцу: у него всего двенадцать овец, и он пока считает, что их двенадцать."},{"id":"halls_076","kind":"note","title":"Рецепт чернил","text":"Возьми дубовые орешки, истолки и залей дождевой водой на три дня. Добавь железного купороса на кончике ножа и немного камеди, чтобы чернила держались. Мой учитель велел добавлять ещё стакан вина. Я добавлял его двадцать лет, пока не понял, что на чернила вино никак не влияет, а учитель всегда сперва пробовал его сам. Я всё равно добавляю, потому что скучаю по этому старому жулику. Храни горшок в тени, а ложку потом не пускай на кухню, мне за это уже попадало."},{"id":"halls_077","kind":"note","title":"Стихи с правкой","text":"Упражнение по стихосложению, студент Мэтью Дин. «Матушка, вы как рассвет, вам уж сорок восемь лет». Правка доктора Эллиса: возраст дамы в стихах не указывают, а рассвет бывает каждый день, и это не комплимент. Рифма самая дешёвая на всей кафедре. Удовлетворительно, с натяжкой. А теперь, Мэтью, не переписывай и отправь ей как есть, сегодня же. Я тоже когда-то написал матери плохие стихи и собирался сперва их улучшить. Мне сейчас семьдесят лет."},{"id":"halls_078","kind":"note","title":"Карточка словаря","text":"Любовь: смотри Лидия. Лидия: смотри Любовь. Наборщику: не исправляй, ошибки тут нет. Я составляю этот словарь тридцать семь лет и дошёл только до буквы Л, и за всё это время она ни разу не сказала мне, что ей надоело носить мне чай. В остальных статьях можешь править запятые."},{"id":"halls_079","kind":"note","title":"Журнал наблюдений","text":"Ночь сорок первая, небо ясное. Кольцо вокруг луны держится с полуночи. В два часа Элеонор принесла горячего молока и спросила, что я там высматриваю. Я усадил её к трубе, и она сказала, что луна кривая, а у меня на локте дырка. В журнал положено заносить всё, что случилось за ночь, поэтому заношу: наблюдений мы больше не делали и просидели на крыше до рассвета."},{"id":"halls_080","kind":"note","title":"Правила диспута","text":"Оппонент имеет право говорить, пока горит малая свеча. Цитировать покойных можно, а вот покойных родственников оппонента нельзя. Книгами разрешается стучать по столу, кидать их запрещено, особенно те, что тяжелее одного фунта. Проигравший жмёт руку победителю и поздравляет его. Жён прошу не приводить: в прошлый раз супруга магистра Эйвери встала и объяснила всему залу, где он ошибся, и была права."},{"id":"halls_081","kind":"note","title":"Рекомендация","text":"Податель сего, Роланд Ши, пять лет учился у меня счёту и так и не научился. Дважды он сложил налоговую книгу так, что город остался должен нам. Зато однажды он заметил, что наш истопник ходит зимой без пальто, пришёл ко мне и потребовал записать пальто в расходы кафедры, потому что замёрзший истопник обойдётся дороже. Я записал, и это единственный его расчёт, который сошёлся. Возьмите его на любую работу, где не надо считать. Доктор Мортон."},{"id":"halls_082","kind":"note","title":"Крышка парты","text":"Вырезано ножом: «Доктор Эллис за лекцию сказал итак сорок раз». Ниже другой рукой: «Пятьдесят два, ты спал». Ниже: «Шестьдесят один, и он кашляет, когда забывает, что хотел сказать». В самом низу, ровными буквами: «Шестьдесят три. Господа, эта парта видна с кафедры, а кашляю я от вашего мела. Итак, тот, кто это вырезал, останется после лекции и вырежет то же самое на моём столе, он у меня очень скучный»."},{"id":"halls_083","kind":"note","title":"Заявление","text":"В налоговую палату. Прошу считать моего пса Барона кошкой, потому что налог на кошек у нас не берётся. Он целыми днями спит на печи, людей не трогает и на улицу идёт неохотно. Мышей он, правда, не ловит, но и кошка моей соседки их не ловит, а с неё не берут. Мы с Бароном живём вдвоём с тех пор, как не стало мужа, и двух монет у меня нет. Лаять при проверяющем он не станет, я с ним поговорю. Вдова Пеппер."},{"id":"halls_084","kind":"note","title":"Тетрадь по счёту","text":"Задача. в доме было 6 чилавек. 2 ушли на плошадь. сколько асталось. ответ 4. Задача. в доме было 4 чилавека. 1 ушол на плошадь. сколько асталось. ответ 3. учитель задаёт про яблоки а я решаю про наш дом патамушта так удобней считать. Задача. в доме было 3 чилавека вместе сомной. мама сказала что ей жарко и пошла подышать. сколько асталось. ответ я пока непишу. Приписка учителя: решено верно. Последнюю задачу решим вместе. Приходи сегодня к нам ужинать и оставайся, кровать есть."},{"id":"halls_085","kind":"note","title":"Закладная","text":"Сынок, ты опять принёс отцовские часы. Это уже девятый раз, и каждый раз ты говоришь мне, что они тебе надоели. Я даю тебе за них четыре монеты, хотя они стоят две и не ходили с самого начала. Заберёшь, когда разбогатеешь. Я их почистил и починил пружину, а ты не обязан это замечать. Книгу по праву закладывать не советую, она тебе ещё пригодится на экзамене. Сэмюэл, у моста."},{"id":"halls_086","kind":"note","title":"Об отпуске","text":"Господину секретарю от Николаса Фенна, копииста. Прошу освободить меня от службы на один день, в четверг, по случаю тридцатилетия моей женитьбы. В прошлый раз я просил о таком дне четырнадцать лет назад, и мне отказали, потому что шла сверка. Жена не сердится. Именно это меня и беспокоит. Если четверг никак нельзя, прошу хотя бы разрешить мне уйти после обеда."},{"id":"halls_087","kind":"note","title":"Глашатаю","text":"Текст для глашатая, читать в полдень с балкона. Первое: колодец на Хлебной улице закрыт на чистку до субботы. Второе: на рынке пропала чёрная свинья с белым ухом. Третье: жена глашатая Беннета просит объявить, что он не будет ужинать дома, пока не извинится перед её матерью. Беннет, я знаю, что читать этого тебе не хочется, но она заплатила пошлину, и теперь ты обязан. Секретарь."},{"id":"halls_088","kind":"note","title":"Сбор на подарок","text":"Сбор на подарок господину Барлоу к сорока годам службы. Советник Мэллори дал одну монету и просил упомянуть об этом в речи. Советник Дрейк дал две и просил упомянуть, что дал больше Мэллори. Прачка Тесс дала три и просила никому не говорить, потому что в прошлую зиму господин Барлоу выписал ей дрова и думает, что она об этом не знает. Всего собрано шесть монет. Этого хватит на подушку для его стула, спина у него болит давно."},{"id":"halls_089","kind":"note","title":"Лист шестой","text":"Хелен, ты всё смеёшься, что я тридцать лет черчу улицы и ни разу не сводил тебя по ним погулять. Посмотри на городской план, лист шестой, за Хлебной улицей. Там есть маленький тупик с тремя деревьями. На самом деле его нет, я его пририсовал. Совет утвердил план и ничего не стал проверять, так что теперь переулок Хелен существует по закону. В субботу я тебя туда свожу, надень башмаки покрепче."},{"id":"halls_090","kind":"note","title":"Признание часовщика","text":"Господин секретарь, пока вы не вызвали проверяющего, я должен признаться, что часы на ратуше отстают на семь минут по моей вине. Тридцать два года назад моя невеста Адель опаздывала к венчанию, а священник был человек строгий. Я полез на башню и перевёл стрелки назад. С тех пор я так и не собрался вернуть их обратно. Адель до сих пор уверена, что пришла вовремя, и я был бы вам благодарен, если бы ваш проверяющий считал так же."},{"id":"halls_091","kind":"note","title":"Распродажа","text":"У меховщика Огилви на Кожевенной улице шубы теперь продаются за полцены, шапки за треть, рукавицы почти задаром. Зима в этом году никому не нужна, как мне объяснили. Я сорок лет шью на этот город и знаю, какие у вас плечи. Придите, пожалуйста, и купите хоть что-нибудь, хотя бы детям. Сам я хожу в тулупе и снимать его пока не собираюсь, смейтесь сколько хотите."},{"id":"halls_092","kind":"note","title":"Письмо повитухи","text":"Дора, ты спрашивала, много ли у меня работы. Работы нет. Жена Бейли ходит на сносях уже одиннадцатый месяц и говорит мне, что ей хорошо и торопиться некуда. У младшей Найт то же самое, только месяц десятый. Я кладу ей руку на живот, и живот у неё тёплый и спокойный. Тридцать лет я боялась только того, что ребёнок пойдёт неправильно. Приезжай, если сможешь, мне не с кем об этом поговорить."},{"id":"halls_093","kind":"note","title":"Записка учительницы","text":"Госпожа Тейт, ваш Корин вчера написал диктант без единой ошибки. Три года я воевала с этим мальчиком, он ел мел, дёргал девочек за косы и клялся мне, что слово «корова» пишется через «а». Теперь он сидит прямо, смотрит на дверь и не спрашивает, когда мы закончим. Я поставила ему высшую оценку и потом долго не могла успокоиться. Зайдите ко мне, пожалуйста, и скажите, дома он тоже такой?"},{"id":"halls_094","kind":"note","title":"В карман","text":"Десмонд, речь я положила в правый карман, а завтрак в левый. В прошлый раз ты перепутал и прочитал совету про ветчину. Не размахивай руками, не говори «как известно» и не смотри на Мэллори, ты на него злишься, и это сразу видно. Я буду сидеть на галерее. Если заговоришь слишком долго, я уроню веер."},{"id":"halls_095","kind":"note","title":"Календарь на год","text":"Февраль: подати с мельниц. Девятое марта: именины Эммы, купить лент, иначе я опять буду спать в конторе, как в прошлом году. Май: отвезти отца к морю, он просит уже четвёртый год. Август: проверка весов. Сентябрь: поговорить с Эммой о переезде, только сначала надо поговорить с отцом. Октябрь: дрова. Ноябрь: отвезти отца к морю, если весной опять не выйдет."},{"id":"halls_096","kind":"note","title":"Приписка писца","text":"Здесь кончается книга о законах водяных мельниц. Пальцы у меня не разгибаются, а спина болит так, будто эти законы писали на ней. Кто будет читать, помяни добрым словом брата моего Эрика, который шесть ночей держал мне свечу и ни разу не пожаловался, только один раз заснул и поджёг мне рукав. Семнадцатую страницу я переписал с ошибкой и исправлять не стану."},{"id":"halls_097","kind":"note","title":"Нужен помощник","text":"Объявление пишу я, дочь профессора Уэста, потому что у него опять перевязаны руки. Кафедре огненных наук нужен помощник. Мы хорошо платим, кормим обедом и даём отдельную комнату. Прежний помощник ушёл от нас сам, на своих ногах, и брови у него уже почти отросли. Папа очень добрый человек и всегда извиняется. Только не позволяйте ему зажигать горелку без вас, и пусть он больше не говорит «сейчас будет красиво»."},{"id":"halls_098","kind":"note","title":"Показания","text":"Записано со слов вдовы Прю Хендри по делу о заборе. Господин Гейтс поставил забор на два дюйма на мою сторону, это правда, и я подала на него жалобу. Писарь спрашивает, почему я подала её только теперь, через девятнадцать лет. Потому что он овдовел, из дому не выходит и ни с кем не видится. А повестку ему прочитать придётся, и в суд прийти придётся, и там я на него посмотрю. Забор прошу оставить на месте. Дело прошу разбирать подольше."},{"id":"halls_099","kind":"note","title":"В подкладке мантии","text":"Корнелиус, если ты это читаешь, значит, у тебя опять распоролась подкладка. Не вздумай зашивать её сам, как в тот раз, когда ты пришил мантию к штанам и стоял так перед всей кафедрой. Я зашила сюда эту записку в день, когда купила тебе мантию, и если с тех пор прошло много лет, значит, шью я хорошо. Неси мантию домой и заодно скажи мне, что я была права, мне будет приятно."},{"id":"halls_100","kind":"note","title":"Записка тюремщика","text":"Сюзан, ужинать я опять приду поздно. Двери с камер сняли ещё в прошлом месяце, и все мои разошлись на площадь, остался один пьяница Гиббс. Я ему говорю: иди, никто тебя не держит. А он отвечает, что ему присудили шесть недель, сидеть ещё двадцать дней, и чужого времени он брать не станет, он человек порядочный. Вот я и ношу ему кашу. Мы играем в кости и ругаем погоду, и знаешь, рядом с ним мне как-то спокойнее."},{"id":"halls_101","kind":"secret","title":"Записка под камнем","text":"Дядя Кит, старик у костра выбрал меня. Он сказал, что руки у меня подходящие, потому что я шесть лет ношу горячие противни у пекаря и ни разу ничего не уронила. Ведро тяжёлое, а на угли надо всё время тихонько дуть, чтобы они не погасли. Мне велели идти наверх и не оглядываться. Пожалуйста, скажите маме, что я вышла одна и ни капельки не боялась. Письмо оставляю под камнем у колодца, вы там всегда набираете воду. Эбигейл."},{"id":"halls_102","kind":"secret","title":"Письмо из раскопа","text":"Марго, я пишу из ямы за площадью, ректор разрешил копать, пока не замёрзнет земля. Под нашей мостовой лежит вторая, сложенная совсем иначе, а ниже яму заливает водой с тиной, хотя реки тут нет. Самое странное я увидел в стенке ямы: прямо под нашим костром зола уходит вниз столбом, толщиной с колодец, и мы никак не доберёмся до её конца. Я велю всё закопать. К ярмарке приеду и привезу тебе орехов."},{"id":"halls_103","kind":"secret","title":"Записи студента","text":"Кафедра истории велела мне расспросить старика у костра, как давно он здесь живёт. Я ходил к нему три раза. В первый раз он спросил, кто мой дед, начал рассказывать что-то про нашу семью, а потом велел мне подбросить дров, потому что гаснет. Во второй раз я нарубил ему дров. В третий раз тоже. Поленницы ему теперь хватит до весны. Кафедре я напишу, что старик ничего не помнит. Про деда он так и не договорил, поэтому завтра я снова к нему пойду."},{"id":"halls_104","kind":"secret","title":"Дверь из завала","text":"Когда мы разбирали завал под новый дом, мне попалась дубовая дверь, совсем целая. На ней гвоздём нацарапано, как дети писали друг другу: Анна дура. Сам дурак. Пол, мама зовёт. Не пойду. Жена хотела её отскоблить, а потом отложила нож. Мы навесили дверь как есть, и наша Мэри уже приписала внизу, что Анна не дура. Теперь Лу каждое утро ходит проверять, не ответил ли кто."},{"id":"halls_105","kind":"secret","title":"Письмо издателю","text":"Любезный господин Кокс, высылаю вам четвёртую главу «Графини в снегах». Как мы договорились, книга выйдет под именем госпожи Эвелины Лейн. Прошу вас ни в коем случае не сообщать кафедре, кто автор: я как раз читаю им курс о нравственном вреде романов. Граф вернётся в шестой главе, читательницы могут не волноваться. Первые две главы я написал для покойной жены, чтобы читать ей вслух, пока она болела. Деньги прошу высылать на имя сторожа."},{"id":"halls_106","kind":"secret","title":"Список в подвале","text":"В подвале соляного архива сейчас сидят двенадцать человек, и я записываю их, чтобы никого не потерять: Дженет Бейл с тремя детьми, двое Пикеров, пекарь, старая Фанни, братья Росс, я и моя внучка. Огня мы здесь не разводим. Мы уже заметили, что кто согреется, тот поднимается наверх и больше не приходит. Дети целыми днями ругаются на холод, и я слушаю их с большой радостью. Внучка сегодня обозвала меня злой старухой."},{"id":"halls_107","kind":"secret","title":"Третий ключ","text":"Ключей от ворот записано два, а на самом деле их три. Прошлой весной я чинил калитку и сделал себе лишний, чтобы выходить на рыбалку раньше смены, и Джуди всегда ругала меня за эту рыбалку. Этой зимой я вывел через калитку тридцать одного человека. Выводил ночью, по четыре за раз, и за стеной они сразу надевали на себя всё, что я им принёс. Сегодня Джуди сама собрала мне мешок и спросила, сколько я поймаю."},{"id":"halls_108","kind":"secret","title":"На обороте трактата","text":"Рен, ты спишь, и я пишу это на обороте твоего же трактата, потому что другой бумаги у нас внизу не осталось. Ты был прав, старый упрямец. Колокол звучит чисто и начинает раньше нашего, я сам слышал. Мне больно это записывать. Когда проснёшься, я скажу тебе, что это эхо, и мы будем спорить дальше, потому что до верёвки нам ещё далеко, а идти молча здесь нельзя. Холт."},{"id":"halls_109","kind":"secret","title":"Семейный обычай","text":"Лили, раз ты теперь хозяйка в доме, запомни наш обычай. На исходе весны, в день большой воды, положи в ведро с водой две монеты и на ночь поставь его у порога. Утром можешь забрать их и потратить. Так делала моя мать и её мать, а почему, никто в нашей семье толком не помнит. Прабабка рассказывала только, что кто-то однажды держал на спине её лодку и платы с неё так и не взял. Не сердись, если это покажется тебе глупостью, и всё равно делай."},{"id":"halls_110","kind":"secret","title":"Замер отвеса","text":"Кэтрин, ты единственная, кто не поднимет меня на смех. В самой нижней палате я шестой год держу отвес над отметкой на камне. Раз в несколько месяцев весь зал приподнимается на толщину волоса и потом медленно садится обратно. Мы с тобой видели, как носильщик перехватывает мешок поудобнее, когда думает, что никто не смотрит. Выглядит это точно так же, только я не знаю, кто у нас носильщик. Если меня переведут, следи за отвесом и не говори ректору."},{"id":"halls_111","kind":"boss","title":"Письмо поварихи","chain":"kitchen","part":1,"boss":"boss","floors":[1,8],"text":"Ханна, новый мэр пришёл ко мне на кухню в первый же день и съел миску ячменной похлёбки стоя, потому что не решился сесть при мне. Сказал, что такая похлёбка была только у его матери, а потом вымыл за собой миску. Двадцать лет я кормлю этот совет, и ни один из них не знает, как меня зовут. Этот спросил. Теперь буду варить ему каждый вторник, и не смей надо мной смеяться, я старая женщина и знаю, кто чего стоит."},{"id":"halls_112","kind":"boss","title":"Записка поварёнку","chain":"kitchen","part":2,"boss":"boss","floors":[1,8],"text":"Том, миску господина мэра неси наверх с полотенцем и не хватайся за неё голой рукой. Он опять не ел. Похлёбка стояла у него на столе с утра и вернулась ко мне такой горячей, что я обожгла пальцы. Вылей её во дворе, только подальше от собаки. Если он спросит, хорошо ли я себя чувствую, отвечай, что хорошо. И не смотри ему подолгу в лицо, мальчик. Я тебе этого не объясню, просто не смотри."},{"id":"halls_113","kind":"boss","title":"Кухонная книга","chain":"kitchen","part":3,"boss":"boss","floors":[1,8],"text":"Вторник. Сварила ячменную похлёбку, как всегда. Господин мэр зашёл сам и встал у очага, и огонь потянулся в его сторону. Он спросил, как меня зовут, будто забыл, и я ему снова сказала. Потом он спросил, не холодно ли мне одной на кухне. Я ответила, что у собственной плиты мне холодно не бывает, и велела ему съесть хоть ложку. Он поднёс ложку ко рту и стоял так, пока я не отвернулась."},{"id":"halls_114","kind":"boss","title":"Письмо поварихи","chain":"kitchen","part":4,"boss":"boss","floors":[1,8],"text":"Ханна, не приезжай. Кухня опустела, мальчик Том ушёл на площадь, и теперь я одна топлю очаг, хотя мне говорят, что это незачем. По вторникам я всё так же варю похлёбку и ставлю ему под дверь. Я знаю, что там уже никто не ест, но в первый день он вымыл за собой миску, а такое я не забываю. Кто-то же должен помнить, что он был голодный мальчик и любил ячмень. Соль у меня кончается, а в остальном я держусь."},{"id":"halls_115","kind":"boss","title":"Долговая книга","boss":"boss","floors":[1,8],"text":"Угольный двор, долги. Сын мой взял телегу на четыре зимы и развёз на ней вдовам дров на сорок одну монету, а денег мне не принёс ни разу. Оси он поломал, сапоги сносил, две пары. Ругал я его за это каждый вечер, как положено отцу. Теперь он мэр, и запись надо закрывать. Долг я списываю, пусть ему люди скажут спасибо. Отдельно записываю, что в последний раз, когда он заходил, я пожал ему руку и с тех пор хожу с перевязанной ладонью. Жене я об этом не говорю."},{"id":"halls_116","kind":"boss","title":"Записка конюха","boss":"boss","floors":[1,8],"text":"Господин секретарь, прошу запретить господину мэру ходить на конюшню. Он приходит к нашей Гнедой, которую кормил с рук все четыре зимы, пока возил дрова вдовам, а теперь она лягается, бьётся о стену и вся дрожит, едва он откроет ворота. Вчера он стоял в проходе и долго уговаривал её тихим голосом, а она забилась в угол. Мне показалось, что он плакал, только мокрого на лице у него не было. Кобылу я отведу на дальний двор, запишите это как болезнь."},{"id":"halls_117","kind":"boss","title":"Письмо настоятелю","boss":"boss","floors":[1,8],"text":"Отец настоятель, прошу перевести меня из этого прихода. Тайну исповеди я бы не нарушил, но этот разговор был на паперти. Перед первым снегом господин мэр остановил меня и спросил, грех ли пообещать что-то за других, если иначе они умрут. Я ответил ему, что надо подождать и помолиться. Он поблагодарил меня и ушёл к воротам. Теперь я не могу слышать, как люди благодарят за тепло."},{"id":"halls_118","kind":"boss","title":"Письмо жениху","boss":"boss","floors":[1,8],"text":"Возвращаю кольцо, мой дорогой, через твою мать, потому что прийти сама я не могу. Под ним у меня на пальце остался белый след от ожога, и лекарь спрашивал, кто это сделал. Я сказала, что сама, у печки. Четыре зимы я ждала, пока ты раздашь свои дрова и вспомнишь о свадьбе. Ты говорил мне, что сперва надо, чтобы никто не мёрз. Теперь никто не мёрзнет. Скажи мне, пожалуйста, ты ещё тот человек, за которого я собиралась, или мне лучше уехать к тётке?"},{"id":"halls_119","kind":"boss","title":"Черновик речи","boss":"boss","floors":[1,8],"text":"Речь господина мэра в день первого тепла, правка секретаря. «Дорогие мои! Я знаю каждого из вас по имени». Вы велели вычеркнуть «дорогие», господин мэр, а вчера велели вписать обратно, я оставил. «Больше никто из вас не будет один». Прошу пояснить, что это значит, люди спрашивают. «Выходите на площадь и ни о чём не беспокойтесь». Я написал, как вы продиктовали. Можно мне в этот день остаться дома с женой? Она плохо себя чувствует и всё время просит открыть дверь."},{"id":"halls_120","kind":"boss","title":"На обёртке","boss":"boss","floors":[1,8],"text":"Внутри этой обёртки лежит страница про старого мэра, которую мой отец вынес снизу и спрятал у нас в сундуке. Сорок лет она там пролежала и всё время оставалась тёплой, а моя Кейт прошлой зимой стала спать у открытой двери. Я несу бумагу обратно вниз и положу там, где отец её взял. Ноги у меня плохие, а дороги я толком не знаю. Если ты нашёл её на полпути, значит, я устал. Не сердись и неси дальше, только в дом не заноси."},{"id":"hint_banner_01","kind":"hint","how":"banner","title":"Записка сестре","text":"Лиза, я спрятала твоё приданое там, куда мама никогда не заглядывала. Сними со стены знамя, что висит у дальней кладки, и за ним откроется ниша. Прости, что так сложно, просто дядя опять считает ложки."},{"id":"hint_banner_02","kind":"hint","how":"banner","title":"Письмо брату","text":"Ты всё спрашивал, куда я дел отцовские часы. Они за знаменем в нижнем зале, за тканью кладка пустая. Сорви тряпку и забери их, а мне напиши хоть строчку."},{"id":"hint_banner_03","kind":"hint","how":"banner","title":"Завещание портного","text":"Всё шитьё я завещаю дочери. А то, что дороже шитья, лежит за знаменем, которое я сам и вешал. Ткань держится на одном гвозде, дёрни посильнее."},{"id":"hint_banner_04","kind":"hint","how":"banner","title":"Записка на обороте счёта","text":"Хозяин думает, что знамя повесили для красоты. Мы с Томом повесили его, чтобы он не видел дыру в стене. Потяни за край, и всё упадёт, только сделай это, пока он спит."},{"id":"hint_banner_05","kind":"hint","how":"banner","title":"Слова старой служанки","text":"Внучка, я не умею писать красиво, так что скажу прямо. Знамя в подвале закрывает дверку, за которой лежит твоё серебро. Тряпка старая и рвётся легко, я проверяла."},{"id":"hint_banner_06","kind":"hint","how":"banner","title":"Письмо другу","text":"Берн, если ты читаешь это, значит, я не вернулся за нашим добром. Оно за знаменем, у той стены, где мы пили в день свадьбы. Выпей и за меня, ладно?"},{"id":"hint_banner_07","kind":"hint","how":"banner","title":"Записка мужа","text":"Марта, не плачь над счётами. Я заложил в стену кошель и завесил это место знаменем с нашим гербом. Сними его, когда будет совсем трудно, и купи детям зимнюю обувь."},{"id":"hint_banner_08","kind":"hint","how":"banner","title":"Запись в тетради певчего","text":"Настоятель велел повесить знамя выше, чем следует, и я понял зачем. Под ним кладка сухая и звучит пусто. Я снял ткань всего на минуту, увидел, что за ней, и повесил обратно. Сердце стучало, как у вора."},{"id":"hint_shelf_01","kind":"hint","how":"shelf","title":"Записка библиотекарю","text":"Ключ тебе больше не понадобится. Книжный шкаф у стены стоит на петлях, потяни его за правый край, и он отойдёт как дверь. Сердись сколько хочешь, но деньги спрятаны у меня лучше, чем у тебя."},{"id":"hint_shelf_02","kind":"hint","how":"shelf","title":"Письмо ученика","text":"Мастер, я нашёл то, что вы прятали. Шкаф с пыльными томами стоит без единой пылинки на полу перед ним, а значит, его двигают. Я отодвинул его и всё увидел. Простите мне моё любопытство."},{"id":"hint_shelf_03","kind":"hint","how":"shelf","title":"Записка жене","text":"Анна, если придут за долгами, не пускай никого к шкафу с книгами. Сам шкаф легко отворяется, и за ним лежит всё, что нам осталось. Никто не станет искать деньги там, где я храню свои скучные книги."},{"id":"hint_shelf_04","kind":"hint","how":"shelf","title":"Заметка переплётчика","text":"Шкаф пришлось ставить на петли, иначе жена заставила бы меня продать всё, что за ним лежит. Он поддаётся одной рукой, если знать, с какого края тянуть. Прости, дорогая, мне ещё не всё удалось дочитать."},{"id":"hint_shelf_05","kind":"hint","how":"shelf","title":"Письмо племяннице","text":"Дочка, запомни про шкаф в библиотеке. Он не стоит, он только притворяется. Потяни его к себе, и старая кладка за ним окажется дверью. Там лежит то, что мы с твоей матерью берегли для тебя."},{"id":"hint_shelf_06","kind":"hint","how":"shelf","title":"Записка сторожа","text":"Каждую ночь шкаф в западном зале стоит чуть иначе, чем вчера. Сегодня я потянул его сам, и он отошёл, как дверь в кладовке. За ним темно, и я пока не решился войти."},{"id":"hint_shelf_07","kind":"hint","how":"shelf","title":"Слова аптекаря","text":"Сын, травы, что остались от меня, стоят за книжным шкафом. Ты вечно смеялся, что я читаю одно и то же, а на самом деле шкаф открывается как створка. Не держи на меня зла за эту шутку."},{"id":"hint_shelf_08","kind":"hint","how":"shelf","title":"Просьба книжника","text":"Кто бы ни читал это, не жгите мои книги. Отодвиньте шкаф, он сделан лёгким нарочно, и заберите то, что за ним лежит. Книги оставьте, кому-нибудь внизу пригодится чтение."},{"id":"hint_lever_01","kind":"hint","how":"lever","title":"Записка каменщика","text":"Мы строили это в спешке, поэтому рычаг торчит на виду, кто захочет, увидит. Потяни его вниз, и камень за стеной поползёт в сторону. Хозяин заплатил нам за молчание, а я всё равно пишу, потому что он нам недоплатил."},{"id":"hint_lever_02","kind":"hint","how":"lever","title":"Письмо дочери","text":"Я велела вделать в стену рычаг, чтобы ты не мучилась с ключами, которые вечно теряешь. Потяни его, когда будешь рядом, и стена откроется. Я ведь знаю тебя, родная."},{"id":"hint_lever_03","kind":"hint","how":"lever","title":"Заметка слесаря","text":"Рычаг на стене ходит туго, смажьте его, если получится. Стоит его опустить, как за кладкой щёлкает и открывается ход. Я делал его для одного человека, а он ни разу не пришёл, чтобы им воспользоваться."},{"id":"hint_lever_04","kind":"hint","how":"lever","title":"Записка вдовы","text":"Сама я не решаюсь, поэтому пишу тому, кто придёт после меня. На стене есть рычаг, которого нет на старых чертежах. Опусти его, и увидишь, что муж прятал от нас столько лет."},{"id":"hint_lever_05","kind":"hint","how":"lever","title":"Письмо брату","text":"Рычаг у стены не для света и не для воды. Я проверил. Опусти его, и там, где была глухая стена, появится проход. Не говори матери, она до сих пор думает, что дом у нас честный."},{"id":"hint_lever_06","kind":"hint","how":"lever","title":"Записка ученика кузнеца","text":"Мастер сказал не трогать рычаг, и я честно терпел целый месяц. Потом всё-таки потянул его вниз, и стена отползла. Теперь я знаю, куда девалось железо, но говорить ему об этом побаиваюсь."},{"id":"hint_lever_07","kind":"hint","how":"lever","title":"Заметка в счётной книге","text":"Плата мастеру за рычаг в стене, пять монет. Плата за то, чтобы он забыл, зачем этот рычаг, ещё пять. Если я не вернусь, сын, просто потяни его вниз."},{"id":"hint_lever_08","kind":"hint","how":"lever","title":"Записка старухи","text":"Я стара и до рычага мне теперь не дотянуться. А ты дотянешься. Он на стене недалеко отсюда, опусти его вниз, и пускай хоть кому-нибудь достанется то, что мы столько лет копили."},{"id":"hint_plate_01","kind":"hint","how":"plate","title":"Записка мальчика","text":"Папа сказал, что камень в полу качается просто от старости. Но я наступил на него двумя ногами, и за стеной что-то заскрипело. Теперь я хожу по нему каждый день, когда никто не видит."},{"id":"hint_plate_02","kind":"hint","how":"plate","title":"Письмо другу","text":"Каменщик сделал одну плиту в полу немного выше других. Наступи на неё, друг, и стена рядом сама уйдёт в сторону. Плата была немалая, зато теперь я сплю спокойно."},{"id":"hint_plate_03","kind":"hint","how":"plate","title":"Заметка смотрителя","text":"На полу есть плита, которая проседает под весом. Я заметил это, когда споткнулся об неё с полными вёдрами. Наступи на неё, и там, где стена, станет пусто. Вёдра, кстати, я так и не собрал."},{"id":"hint_plate_04","kind":"hint","how":"plate","title":"Записка жене","text":"Ланна, не спрашивай, зачем я каждое утро обхожу зал кругом. На одной плите стоять нельзя никому, кроме нас с тобой, потому что под её весом открывается стена. Встань на неё, когда меня не станет."},{"id":"hint_plate_05","kind":"hint","how":"plate","title":"Записка в сапоге","text":"Камень у стены чуть выпирает из пола. Наступи на него всей ногой и увидишь, что будет. Я ведь обещал тебе подарок, Марта, а я всегда держу слово, хоть и с опозданием."},{"id":"hint_plate_06","kind":"hint","how":"plate","title":"Слова старого стража","text":"Внук, я сорок лет ходил мимо той плиты и ни разу на неё не вставал. А ты встань, и стена перед тобой откроется. Что там лежит, я так и не узнал, потому что мне было страшно."},{"id":"hint_plate_07","kind":"hint","how":"plate","title":"Письмо подруге","text":"Я нашла в полу плиту, которая проседает под ногой совсем чуть-чуть, и за стеной сразу что-то сдвигается. Обязательно приходи, вместе наступим и посмотрим. Одной мне как-то боязно."},{"id":"hint_plate_08","kind":"hint","how":"plate","title":"Запись хозяина подвала","text":"Велел положить в полу плиту, что проседает от шага. Сторожу сказал, что пол кривой от сырости. Наступите на неё, дети, когда меня унесут, и стена откроет вам то, что я копил."},{"id":"hint_sconce_01","kind":"hint","how":"sconce","title":"Записка поварихи","text":"Один светильник на стене висит неправильно, ты сразу увидишь. Потяни его вниз, как за ручку двери, и камень отойдёт. Я нашла это, когда пыталась поправить огонь, и чуть не уронила сковороду."},{"id":"hint_sconce_02","kind":"hint","how":"sconce","title":"Письмо сестры","text":"Марта, тот светильник у лестницы вовсе не сломан, он так и задуман. Потяни его на себя, и в стене рядом откроется дверца. Там письма, которые ты мне писала, и больше ничего, но мне они дороже денег."},{"id":"hint_sconce_03","kind":"hint","how":"sconce","title":"Заметка фонарщика","text":"Я заправляю все светильники в подвале сорок лет. Один из них качается, если потянуть. За ним шевелится стена. Никому не сказал и не скажу, но бумага стерпит."},{"id":"hint_sconce_04","kind":"hint","how":"sconce","title":"Записка в свечном ящике","text":"Сын, не верь тому, что все лампы одинаковые. Одна сидит на шарнире. Потяни её вниз, и откроется место, куда я клал всё, что откладывал тебе на учёбу."},{"id":"hint_sconce_05","kind":"hint","how":"sconce","title":"Письмо брату","text":"Я долго думал, почему в этой комнате столько ламп, если никто здесь не читает. Потяни за любую, какая подастся. Одна подастся, и стена за ней уйдёт в сторону. Вот зачем их столько."},{"id":"hint_sconce_06","kind":"hint","how":"sconce","title":"Заметка маляра","text":"Красил стены и случайно задел светильник. Он повернулся вниз, а стена рядом щёлкнула. Я быстро поставил его на место и докрасил. Хозяин платит мало, но я всё-таки предпочитаю оставаться живым."},{"id":"hint_sconce_07","kind":"hint","how":"sconce","title":"Записка мужа","text":"Если темно, не бойся. Потяни один из светильников вниз, тот, что висит ближе других к стене. Он откроет ход. А когда выйдешь, поставь его обратно и подумай обо мне, ладно?"},{"id":"hint_sconce_08","kind":"hint","how":"sconce","title":"Слова слепого звонаря","text":"Я не вижу ламп, но слышу их. Одна из них скрипит, когда её трогают, и за нею шуршит камень. Потяни её вниз, добрый человек, и забери, что там лежит. Мне это уже без надобности."},{"id":"hint_statue_01","kind":"hint","how":"statue","title":"Записка скульптора","text":"Статую у стены я поставил на полозья, потому что хозяин боялся воров, а я боялся хозяина. Толкни её вбок, вдоль стены, и за ней окажется то, что он прятал. Я свою часть денег уже получил."},{"id":"hint_statue_02","kind":"hint","how":"statue","title":"Письмо дочери","text":"Каждый раз, когда ты спрашивала, почему статуя стоит не посередине, я отшучивался. Толкни её вдоль стены, родная. Она сдвинется легко, и за ней лежит всё, что я успел для тебя отложить."},{"id":"hint_statue_03","kind":"hint","how":"statue","title":"Заметка уборщика","text":"Подметал у статуи и упёрся в неё плечом. Она отъехала вбок, как тележка, а там, где стояла, в стене дыра. Я задвинул её обратно и никому ни слова. Подметаю теперь только вокруг."},{"id":"hint_statue_04","kind":"hint","how":"statue","title":"Записка вдовца","text":"Не думай, что твой отец был совсем дурак. Статуя в зале стоит на катках, и стоит толкнуть её вбок, как откроется ниша. Я клал туда по монете каждый год, пока ты росла."},{"id":"hint_statue_05","kind":"hint","how":"statue","title":"Письмо другу","text":"Две статуи стоят одинаково, а одна всё-таки лжёт. Толкни ту, что поддастся, вдоль стены. За ней не клад, а наша с тобой старая переписка, но я всё равно рад, что ты её найдёшь."},{"id":"hint_statue_06","kind":"hint","how":"statue","title":"Записка каменотёса","text":"Я сам её вытесал, поэтому знаю, какая она тяжёлая. Тем удивительнее, что толкнуть её вбок может даже ребёнок. Попробуй, и за ней увидишь, зачем мне столько платили и почему велели молчать."},{"id":"hint_statue_07","kind":"hint","how":"statue","title":"Слова няни","text":"Деточка, в том зале статуи стоят и смотрят, как будто что-то стерегут. Одна и правда стережёт. Сдвинь её в сторону вдоль стены, она поедет, и не бойся её взгляда, он каменный."},{"id":"hint_statue_08","kind":"hint","how":"statue","title":"Запись в дневнике сторожа","text":"Вчера одна статуя стояла на два шага левее, чем сегодня. Я подумал, что спятил, и навалился на неё плечом. Она поехала вдоль стены, а за ней открылась чёрная дыра. Схожу с ума, но очень аккуратно."},{"id":"hint_levers_01","kind":"hint","how":"levers","title":"Записка механика","text":"Три рычага у стены нельзя тянуть как попало. Под каждым я нацарапал зарубки: одна, две, три. Тяни по порядку, и если ошибёшься, всё просто встанет на место, ничего страшного."},{"id":"hint_levers_02","kind":"hint","how":"levers","title":"Письмо сестре","text":"Ты никогда не умела считать, поэтому я пометил рычаги зарубками. Сначала тот, что с одной, потом с двумя, потом с тремя. Перепутаешь, начнёшь сначала, и никто тебя не укусит."},{"id":"hint_levers_03","kind":"hint","how":"levers","title":"Заметка в чертеже","text":"На стене три рычага, и каждый отмечен царапинами снизу. Опускать надо по числу царапин, от меньшего к большему. Хозяин считает это хитростью, а я считаю ленью, но работает."},{"id":"hint_levers_04","kind":"hint","how":"levers","title":"Записка ученику","text":"Посчитай зарубки под рычагами, прежде чем за них хвататься. Это всё, чему я успел тебя научить, но этого хватит. Ошибка ничего не сломает, рычаги просто вернутся назад."},{"id":"hint_levers_05","kind":"hint","how":"levers","title":"Записка вдовы","text":"Муж делал зарубки под рычагами и считал вслух, чтобы я запомнила. Одна, две, три, говорил он. Я до сих пор помню его голос, хотя сама так и не решилась потянуть."},{"id":"hint_levers_06","kind":"hint","how":"levers","title":"Слова старого слесаря","text":"Рычаги не любят спешки, внук. Смотри, сколько черт процарапано под каждым, и опускай их от одной черты к трём. Промахнёшься, и они сами вернутся вверх, как будто ничего и не было."},{"id":"hint_levers_07","kind":"hint","how":"levers","title":"Письмо брату","text":"Ни один вор не догадается считать царапины на стене, вот на что я надеюсь. Тот рычаг, где царапина одна, тяни первым, потом дальше по счёту. А ты, брат, догадаешься, я в тебе уверен."},{"id":"hint_levers_08","kind":"hint","how":"levers","title":"Заметка на дощечке","text":"Три рычага, три метки. Начинай с единицы. Перепутал, начинай снова, рычаги не обижаются. Жаль, что с людьми так не выходит, но об этом уже в другой записке."},{"id":"hint_candles_01","kind":"hint","how":"candles","title":"Записка сестры","text":"Рядом со свечами я процарапала на полу чёрточки: одна, две, три. Зажигай их именно в таком порядке, иначе все сразу погаснут, и придётся начинать сначала. Это я нарочно, чтобы никто случайный не вошёл."},{"id":"hint_candles_02","kind":"hint","how":"candles","title":"Письмо брату","text":"Помнишь, как мама заставляла нас зажигать свечи по старшинству? Так и здесь: у каждой свечи царапины на полу, сколько царапин, такой ей и черёд. Спутаешь, они погаснут, и попробуешь ещё раз."},{"id":"hint_candles_03","kind":"hint","how":"candles","title":"Заметка служки","text":"Свечи в этой комнате зажигают не как придётся. Около каждой есть метки на полу, и начинать надо с той, где метка одна. Ошибёшься, и огонь уйдёт сразу со всех, но тебе ничего не будет."},{"id":"hint_candles_04","kind":"hint","how":"candles","title":"Записка жене","text":"Анна, зажги свечи по чёрточкам, что у них на полу, от одной к трём. Я так устроил, чтобы только ты могла войти. Если перепутаешь, они просто погаснут, и ты улыбнёшься и начнёшь снова."},{"id":"hint_candles_05","kind":"hint","how":"candles","title":"Слова монахини","text":"Три свечи стоят рядом и ждут своего череда, дитя. Посчитай царапины у подножия и зажигай по счёту. Огонь гаснет, если поторопиться, но это единственное наказание."},{"id":"hint_candles_06","kind":"hint","how":"candles","title":"Записка в подсвечнике","text":"Не лей воск куда попало, смотри на пол. Там чёрточки, сколько чёрточек, такой и порядок. Я вырезала их, пока отец спал, и мне до сих пор немного стыдно."},{"id":"hint_candles_07","kind":"hint","how":"candles","title":"Письмо племяннику","text":"Я знаю, что ты зажигаешь свечи как попало, вот и попал. Погляди, что нацарапано на полу у каждой, и зажигай от одной черты к трём. Не торопись, родной, тут спешить некуда."},{"id":"hint_candles_08","kind":"hint","how":"candles","title":"Заметка смотрителя","text":"Когда свечи гаснут все разом, значит, порядок был неверный. Порядок написан на полу чёрточками, по одной, по две и по три. Я каждый день хожу и зажигаю их заново, и это, в сущности, неплохая работа."},{"id":"magma_001","kind":"note","title":"Законы","text":"Закон первый: чужое не брать. Закон второй: что чужое, скажет Орин. Если вам понадобится третий закон, приходите к Орину днём. Вечером он устаёт и путает чужое со своим, это я вам говорю как его жена."},{"id":"magma_002","kind":"note","title":"Решение схода","text":"Сегодня решили ставить стену. От кого мы будем ею отгораживаться, решим, когда достроим. Камень носят все, кто ходит на двух ногах. Дункан сказал, что у него болит спина, и я так и записал: Дункан, спина. Вчера эта спина несла домой целого барана, но я ему друг и про барана писать не стану.","chain":"stena_dunkana","part":1},{"id":"magma_003","kind":"note","title":"Закон о воде","text":"Воду для питья берите выше всех по ручью. Мойтесь ниже, а скотину поите ещё ниже. Тот, кто живёт ниже всех, сам выбрал, где сесть, и извиняться перед ним никто не будет. Рольф, это про тебя. Мы тебя всё равно любим, но пить из ручья у своего дома я тебе не советую."},{"id":"magma_004","kind":"note","title":"Надпись у двери","text":"Это дверь, первая у нас. Сначала стучите рукой, а потом ждите, пока я скажу входить. Кто войдёт по-старому, получит ковшом. Муж мой тоже получит, он уже получал. Эдна."},{"id":"magma_005","kind":"note","title":"Первая расписка","text":"Я, Берт, взял у Иды козу на один день, потому что младшему нужно молоко. Завтра я её верну. Ида велела нацарапать это на глине, она говорит, что так надёжнее, чем помнить. Ида, мы с тобой шли сюда рядом сорок дней, и мне обидно. Но за козу спасибо.","chain":"pervyi_dolg","part":1},{"id":"magma_006","kind":"note","title":"Запись схода","text":"Вчера весь вечер собирались назвать место, где мы живём. Одни предложили Здесь, другие Тут, третьи У Трещины. Гарт предложил Дом Гарта, но жена посмотрела на него, и он сел. До темноты мы так и не решили. На глине пока пишем Здесь."},{"id":"magma_007","kind":"note","title":"Распоряжение","text":"Гартов у нас двое, и это путает людей. С этой луны высокий будет зваться Длинный Гарт, а второй Другой Гарт. Другой Гарт просил записать, что он против. Я записал. Не дуйся, Гарт, никакой ты нам не другой."},{"id":"magma_008","kind":"note","title":"Ночь при огне","text":"Сегодня моя первая ночь при огне. Хэмиш велел мне не спать, давать щепки по одной и не ставить горшок на мокрое, а утром показать ему запись, как прошла ночь. Огонь размером с кулак и кашляет, когда ему дают сырое. Мне стало его жалко, и я сказала ему своё имя, всё равно делать нечего. Мама думает, что я боюсь темноты. Рядом с ним я не боюсь. Фрея.","chain":"nochnaya_ochered","part":1},{"id":"magma_009","kind":"note","title":"Дело об огне","text":"Тобин пришёл заявить о краже огня. Ночью Хоб взял у него уголь. Огонь у Тобина остался, и теперь у Хоба он тоже есть, поэтому мы не знаем, как судить. Тобин настаивает, что огня у него стало меньше. Они братья и всю дорогу спали спина к спине, так что мы подождём до утра, и судить, может быть, не придётся."},{"id":"magma_010","kind":"note","title":"Первый торг","text":"На шестой день всем велели нести к камню, что у них есть лишнего, чтобы меняться. Пришли шестеро. Лишнего не нашлось ни у кого. Мы постояли и поговорили про больную ногу Мод, а потом Вилл отдал ей свою палку просто так. В следующий шестой день придём ещё."},{"id":"magma_011","kind":"note","title":"Объявление школы","text":"Открылась школа. Учит Осберт, он знает двенадцать знаков. Приносите свой сланец и свой камешек. Сегодня учим «хлеб» и «нет хлеба». Это один и тот же знак, только во втором есть черта. Матери, накормите детей перед школой, а то они запомнят только второй.","chain":"shkola_na_slance","part":1},{"id":"magma_012","kind":"note","title":"Первый суд","text":"Фиск взял гуся. Судить мы не умеем, поэтому Фиск сам подсказывал, кому где встать и кто говорит первым. Решили вернуть гуся хозяйке, но гуся не нашли. Хозяйка сказала, что гусь щипал её каждое утро и что она уже скучает. Фиску велели и дальше подсказывать, когда будем судить кого-нибудь ещё."},{"id":"magma_013","kind":"note","title":"Молитва","text":"Огонь, мы дали тебе сухого, хотя сами спим на мокром. Сделай, пожалуйста, чтобы дождь кончился и чтобы у Эдны родился живой. Она двоих схоронила по дороге и больше об этом не говорит. Если это дело не к тебе, передай тому, к кому надо."},{"id":"magma_014","kind":"note","title":"Закон о тепле","text":"Тёплую сторону, где земля греет спину, делим так: первыми идут старые, потом те, у кого младенец, потом те, кто сильно просит. Кто просит сильно, определяет Орин. Орин просит сильно и говорит, что это ради жены, потому что она мёрзнет. Жена говорит, что не мёрзнет.","chain":"teplaya_storona","part":1},{"id":"magma_015","kind":"note","title":"Надгробный камень","text":"Здесь лежит Мод, первая, кого мы тут положили. Место она выбрала сама и при жизни ругала всех, кто по нему ходил. Мы и теперь обходим его стороной. Мама, не ругайся."},{"id":"magma_016","kind":"note","title":"Запись о похоронах","text":"Ульрик умер этой ночью. Раньше мы клали своих под камни и шли дальше, а теперь дальше мы не идём. Его жена спросила, где его положить, чтобы не видеть могилу из двери. Вечером она пришла снова и спросила, где положить, чтобы видеть."},{"id":"magma_017","kind":"note","title":"Обмер стены","text":"Стена пошла прямо, как велел каменщик, и дом Дункана остался с той стороны. Дом у него кривой и всем мешал, но Дункана мы любим, и никто не хочет говорить ему первым. Сейчас он гостит у сестры. Мы тянули камешки, кому объяснять, когда он вернётся, и вытянул я. Дайте мне с собой лепёшек.","chain":"stena_dunkana","part":2},{"id":"magma_018","kind":"note","title":"Записка Коре","text":"Кора, я вернусь к жатве. Пишу это, чтобы ты показала мне глину, когда я скажу, что не обещал. Корм козам я оставил у стены. Не таскай воду одна, попроси Вилла, и ложись пораньше. Я буду скучать, только никому этого не показывай. Бран."},{"id":"magma_019","kind":"note","title":"Записка Виллу","text":"Вилл, я отдала тебе свою очередь у тепла, потому что у тебя кашель. Другой причины нет, и ты ничего такого не думай. Вечером я буду у ручья. Приходи, там кашлять тоже можно. Нелл."},{"id":"magma_020","kind":"note","title":"Детской рукой","text":"я видела как камень тёк. он тёк как суп. мама сказала не ври. я сунула в него палку и палка пропала. я принесла другую палку и сказала смотри а мама всё равно говорит не ври и держит меня за руку очень крепко"},{"id":"magma_021","kind":"note","title":"Жалоба Иды","text":"Берт обещал вернуть козу завтра. С тех пор прошло сорок завтра, а коза всё ещё у него. Я хожу на неё посмотреть, она узнаёт меня и блеет, и я ухожу. Берт говорит, что коза теперь другая, потому что у неё козлёнок, а козлёнка он у меня не брал. Я знаю Берта всю жизнь и скажу прямо: я его побью.","chain":"pervyi_dolg","part":2},{"id":"magma_022","kind":"note","title":"Подпись к рисунку","text":"это наш дом. это мама. это огонь. это дядя он стоит внизу в трещине и машет мне рукой. папа сказал рисуй только то что есть. я и нарисовала что есть"},{"id":"magma_023","kind":"note","title":"Рецепт супа","text":"Дочка, суп теперь варят так. Опусти горшок на верёвке в щель, верёвку бери с запасом, посчитай до сорока и тяни. Кто считает плохо, тот ест сырое. Кто отпустит верёвку, идёт к Альде просить новый горшок, а Альда нас с тобой и так не любит, так что держи крепче."},{"id":"magma_024","kind":"note","title":"Наказ гончара","text":"Глину, сынок, мни, пока она не станет мягкая, как мочка уха. Потом суши её в тени шесть дней и только после этого ставь на жар. Если горшок треснул, значит, ты спешил, как и я в твои годы. Черепки выноси ночью, чтобы Альда не считала."},{"id":"magma_025","kind":"note","title":"Наказ писцу","text":"Глины на всех не хватает, поэтому табличка эта для ячменя, и писать на ней надо только про ячмень. Твою вчерашнюю табличку про жену я по ошибке обжёг вместе с остальными, и теперь то, что ты там написал, будет всегда. Я прочитал, сынок. Написано хорошо, только ячменя там нет ни горсти."},{"id":"magma_026","kind":"note","title":"Ночь при огне","text":"Огонь вырос! Мы переложили его в большой горшок, потому что старый треснул. Хэмиш долго ходил смотреть на черепки и вздыхал, как будто хоронил родню. Я принесла ему поесть и посидела рядом. Щепки я теперь даю по две, и огонь, по-моему, стал ко мне добрее. Фрея.","chain":"nochnaya_ochered","part":2},{"id":"magma_027","kind":"note","title":"Жалоба соседу","text":"Рольф, твоя коза съела мою крышу. Крыша была из травы, это я признаю. Теперь у меня нет крыши, у твоей козы был обед, а ты стоишь и говоришь, что коза молодая. Мы с тобой были соседями ещё тогда, когда у нас не было домов, поэтому злиться долго я не буду. Приходи завтра и неси траву, а козу привяжи."},{"id":"magma_028","kind":"note","title":"Запись о старшем","text":"Старшего мы выбирали поднятой рукой. Орин в это время чесался, и его выбрали. Потом он сказал, что отказывается, но ему велели со старшим не спорить. Жена обняла его и сказала, что рука у него всегда поднималась не вовремя."},{"id":"magma_029","kind":"note","title":"Упражнение","text":"хлеп хлеп хлеп хлеп хлеп хлеп. осберт сказал напиши ещё пять раз. у меня камешек стёрся. хлеп. можно я нарисую собаку. она у нас хорошая и тоже любит хлеп","chain":"shkola_na_slance","part":2},{"id":"magma_030","kind":"note","title":"Перепись к зиме","text":"Мы пересчитали всех на зиму, и нас сорок один. С младенцем Эдны будет сорок два, но он родился только этой ночью и ещё очень маленький. Я пишу сорок один, а рядом оставляю место. Эдна, весной я допишу его сам, обещаю."},{"id":"magma_031","kind":"note","title":"Знак у тропы","text":"Здесь идёт дорога. Дальше дороги нет, потому что мы устали. Кто пойдёт дальше, пусть утаптывает сам. А если ты тоже устал, возвращайся к нам, у нас есть суп."},{"id":"magma_032","kind":"note","title":"Жалоба сторон","text":"Жители тёплой стороны жалуются, что у них воняет тухлым яйцом и плавятся подошвы. Жители холодной стороны жалуются, что у них дует и что им завидно. Старший велел им поменяться на неделю, и они поменялись. Теперь обе стороны говорят, что на той было лучше, и ходят друг к другу в гости, чтобы это сказать.","chain":"teplaya_storona","part":2},{"id":"magma_033","kind":"note","title":"Решение о знаках","text":"Мы договорились о знаках для камня, воды, ячменя и долга. Гвен просит придумать ещё знак для «извини». Рольф сказал, что до сих пор мы без него обходились. Тогда его жена спросила с лавки, кто это мы. Решение отложили."},{"id":"magma_034","kind":"note","title":"Дни на сланце","text":"Я царапаю на сланце дни с тех пор, как мы пришли. Бет говорит, что один день я нацарапал дважды, тот, когда она рожала. Исправлять я не стал, тот день и был за два."},{"id":"magma_035","kind":"note","title":"Письмо Дункана","text":"Вы заложили мне вид. Я теперь живу снаружи, один, и это, как я понял, называется другая страна. Воду из моего ручья вы берёте? Берёте. Поэтому с каждого ведра вы должны мне одну лепёшку. И передайте Дэви, что я всё ещё считаю его другом, пусть приходит, только тоже с лепёшкой. Дункан, хозяин всего, что за стеной.","chain":"stena_dunkana","part":3},{"id":"magma_036","kind":"note","title":"Долговая глина","text":"Я, Тобин, должен Гвен одну пощёчину. Она сама велела это записать, потому что сейчас у неё руки в тесте. Гвен, я знаю, за что, и я виноват. Щёку принесу, когда скажешь."},{"id":"magma_037","kind":"note","title":"Счёт Рэна","text":"Счёт за ячменную воду. Тобин выпил шесть кружек, Хоб пять, а Орин две и говорит, что одну. Прошу заплатить сегодня, пока вы все помните, что было вкусно. Вчера Тобин и Хоб пели про маму и плакали, и за это я с них ничего не беру. Рэн."},{"id":"magma_038","kind":"note","title":"Решение старшего","text":"Старший рассудил, что коза принадлежит Иде, а козлёнок им обоим пополам. Как это пополам, он сказать отказался. Ида предлагает держать козлёнка у себя по очереди, неделю она, неделю Берт. Знаков для этого не хватило, поэтому дальше они нарисовали сами, и Берт на рисунке Иды вышел с рогами.","chain":"pervyi_dolg","part":3},{"id":"magma_039","kind":"note","title":"Наказ ученику","text":"Шов над швом не клади, клади поперёк. Углы ставь первыми. Когда положишь верхний ряд, сядь рядом и посиди. Если стена молчит, значит, всё хорошо, иди ужинать. Если заскрипит, зови меня и не бойся, сынок, я и сам в твои годы ронял стены."},{"id":"magma_040","kind":"note","title":"Знак у трещины","text":"У трещины не играть. Детям нельзя, собакам нельзя и Гарту нельзя, ему уже пятьдесят. Это писала его мать, и она всё видит."},{"id":"magma_041","kind":"note","title":"Где ночует огонь","text":"Сегодня огонь ночует у Гвен, завтра у Хоба, а потом у Другого Гарта. У Тобина он ночевать не будет, пока Тобин не извинится. Перед Гвен или перед огнём, пусть выберет сам. Мы все надеемся, что перед Гвен."},{"id":"magma_042","kind":"note","title":"Жалоба на пепел","text":"Опять пепел на белье, третий раз за эту луну, а я стирала его утром у ручья. Жаловаться на это некому, поэтому я пишу и кладу глину на камень. Мой покойный муж сказал бы, что надо было вешать с другой стороны, и был бы неправ. Я бы дорого дала, чтобы он это сказал. Альда."},{"id":"magma_043","kind":"note","title":"Ночь при огне","text":"Третий день идёт дождь. Мы несли огонь на сухое место под пятью плащами и менялись на бегу. У меня прогорел рукав и немного рука. Хэмиш сказал, что так огонь благодарит. Я думаю, он просто горел. Но Хэмиш сам завязал мне руку тряпкой и долго ругался, так что я ему это прощаю.","chain":"nochnaya_ochered","part":3},{"id":"magma_044","kind":"note","title":"Запись о свадьбе","text":"Сегодня мы женили Кейт и Дэви. Слов для этого у нас ещё нет, поэтому Орин посмотрел на обоих и сказал: ну вот. Потом все пошли есть. Дэви плакал и говорил, что это от дыма. Кейт говорит, что запомнила и «ну вот», и дым."},{"id":"magma_045","kind":"note","title":"Родился тут","text":"Тэм родился уже здесь, и он единственный из нас, кто никуда не шёл. Старшие дети зовут его Гостем. Мать просит, чтобы кто-нибудь объяснил ему, когда он подрастёт, что такое дорога. Сама она не может, потому что начинает говорить и плачет."},{"id":"magma_046","kind":"note","title":"Запись о яме","text":"Я рыл яму под ячмень. На глубине локтя земля была тёплая, как хлеб из печи. На втором локте она стала такая горячая, что я перестал копать и всё засыпал. Всем, и жене тоже, я сказал, что в горшках ячмень сохраннее. Так им спокойнее спать."},{"id":"magma_047","kind":"note","title":"Жребий","text":"Мы тянули камешки на зиму, и чёрный камешек значит тёплое место. Длинный Гарт вытянул чёрный четвёртый раз подряд. Решили, что теперь он тянет первым, а руки ему будет держать Ида. Мои дети опять будут спать у холодной стены. Скажу им, что Гарт очень хорошо умеет тянуть.","chain":"teplaya_storona","part":3},{"id":"magma_048","kind":"note","title":"Про колодец","text":"Колодец сегодня тёплый, а вчера был холодный. Я набрала воды, и она пахнет как мокрый нож. Детям пока не давайте, а взрослым можно, они и не заметят. Особенно ты, Дэви, но ты всё равно пей поменьше, пожалуйста."},{"id":"magma_049","kind":"note","title":"Записка соседке","text":"Ренна, у вас стены тоже гудят по ночам? У нас они гудят негромко, как жук в горшке. Наша собака слушает, потом встаёт и ложится в другом месте, и скоро у неё кончатся места. Приходите к нам ночевать с детьми, если страшно. Если не страшно, всё равно приходите."},{"id":"magma_050","kind":"note","title":"Приписка","text":"Ида отдала эту глину Хобу за шесть лепёшек, и теперь Берт должен козу Хобу. Хоб не хочет козу, он хочет лепёшки обратно, но глину у него уже взяла Мод за воду. Берт ходит весёлый и говорит, что никогда ещё не был должен столько хорошим людям.","chain":"pervyi_dolg","part":4},{"id":"magma_051","kind":"note","title":"Про порог","text":"Я измерил порог, он ушёл вниз на палец. Левая половина дома теперь ниже, и наши горшки сами съезжают к соседке Ренне. Ренна довольна и говорит, что посуда знает, где её любят. Я подбил под стену клин. Вечером Ренна принесла горшки обратно, и в одном была каша."},{"id":"magma_052","kind":"note","title":"Записка у двери","text":"Кто увидит Джосса, скажите ему, что обед стоит у двери. Он ушёл к трещине посмотреть, откуда идёт тепло. Это было на прошлой неделе. Я каждый день ставлю ему новый обед, сегодня каша с салом, как он любит. Джосс, если ты читаешь это сам, я не сержусь."},{"id":"magma_053","kind":"note","title":"Записка Хэмишу","text":"Хэмиш! У нас двое детей, и ни одного из них ты ночью не укрывал. А к огню ты встаёшь три раза и накрываешь его от ветра. Ему от твоего одеяла только хуже, я проверяла. Дети спрашивают, когда ты придёшь домой. Я тоже спрашиваю."},{"id":"magma_054","kind":"note","title":"Закон об общем","text":"Каждую десятую лепёшку надо отдавать на общее. Что такое общее, нам показали: это горшок у камня. Горшок пуст, старший сыт, а спрашивать про это можно только по шестым дням. В прошлый шестой день я спросила. Орин покраснел, достал из-за пазухи лепёшку и отдал её моим детям."},{"id":"magma_055","kind":"note","title":"Дневник","text":"Мимо шли трое чужих и попросили воды. Мы дали. Один спросил, что это за место. Мы переглянулись, и Гарт сказал: город. До ночи мы ходили и смотрели, похоже ли. Один угол вроде похож, и Бет взяла меня за руку и долго там стояла."},{"id":"magma_056","kind":"note","title":"Письмо учителя","text":"Старшему от Осберта. Тринадцатого знака у меня нет. Дети просят показать, как написать, что брат умер. Я показал им черту, ту самую, из «нет хлеба». Тилли провела её рядом с именем брата и спросила, будет ли теперь хлеб. Я не знал, что ей ответить, и отдал ей свою лепёшку. Орин, придумай что-нибудь, мне нечем им это объяснить.","chain":"shkola_na_slance","part":3},{"id":"magma_057","kind":"note","title":"Мера горсти","text":"Теперь горсть у нас одна на всех, по руке Эдны. Её руку слепили из глины и положили у камня, чтобы мерить ячмень. Люди проходят мимо и жмут глиняную руку на удачу. Эдна говорит, что с неё хватит и что ей это не нравится, но по утрам сама ходит вытирать с руки пыль."},{"id":"magma_058","kind":"note","title":"Письмо сестре","text":"Сестра, мы остановились. Снизу идёт тепло, и плохо пахнет. Дом всё время стоит на одном месте, и мне всё хочется его куда-нибудь перенести. Эту глину я кладу у тропы, на камень с белой меткой, ты знаешь, как мы метили стоянки. Приходи, если найдёшь нас. Я всё ещё сплю на своей половине, а твоя пустая. Брида."},{"id":"magma_059","kind":"note","title":"Про деда","text":"Дед каждое утро собирает мешок, как тогда, когда мы ходили за стадом, а к вечеру разбирает. Мы ему ничего не говорим, мешок у него хороший. Вчера он положил туда и мою кружку. Значит, меня он всё ещё берёт с собой."},{"id":"magma_060","kind":"note","title":"Донос старшему","text":"Орин, я не люблю доносить, но Дункан ставит вторую стену, вокруг нашей. Камень он таскает по ночам, и камень этот наш. Вчера он спрашивал, не хочет ли кто переехать, потому что у него просторно. Двое ходили смотреть, и один из них был я. Там правда просторно. Он поставил нам две миски и всё спрашивал, не дует ли.","chain":"stena_dunkana","part":4},{"id":"magma_061","kind":"note","title":"Шутка Дорна","text":"Дорн опять рассказывал свою шутку. Гарт приходит к Гарту. Гарт спрашивает: ты кто? Гарт отвечает: Гарт. Тут надо подождать. Дорн ждёт очень долго, и в этом вся шутка. Оба Гарта её запретили, а жена Дорна смеётся каждый раз, хотя слышала её уже раз сорок."},{"id":"magma_062","kind":"note","title":"Кто лечит","text":"Если болит живот, идите к Альде. Если страшно, идите к Хобу, он умеет сидеть рядом. Зуб дёргает Рольф, верёвка у него есть, но привязывать будете сами."},{"id":"magma_063","kind":"note","title":"Счёт ячменя","text":"В горшке Эдны девять горстей ячменя, в горшке Рольфа четырнадцать. В общем горшке лежит одна горсть и мышь. Мышь не считаем. Дети просили её не выгонять, у неё там, оказывается, мышата."},{"id":"magma_064","kind":"note","title":"Ночь при огне","text":"Сегодня безветренно. Всякий огонь тянется вверх, а этот тянется туда, где трещина. Я поднесла щепку с другого бока, он поглядел на неё и повернулся обратно. Хэмишу я пока об этом не говорю, он и так плохо ест. Я положила ему в миску свою лепёшку, он съел и не заметил. Фрея.","chain":"nochnaya_ochered","part":4},{"id":"magma_065","kind":"note","title":"Карта на сланце","text":"Вот колодец. Вот трещина, туда не ходи. Вот дом Гвен. А вот ты, если стоишь у дома Гвен и читаешь это. Заходи, не стой, Гвен всех кормит."},{"id":"magma_066","kind":"note","title":"Правила игры","text":"Кто наступил на трещину, тот стал пеплом. Пепел лежит, пока ему не сосчитают до двадцати. Кто лёг без причины, пеплом не считается. Дети Гарта играют нечестно, с ними не играйте. Младшего можно взять, он ещё маленький и плачет, если его не берут."},{"id":"magma_067","kind":"note","title":"Записка мужу","text":"Ты опять таскал камень до темноты и опять за едой рассказывал про угол. Я не знаю, что такое угол, и слушаю тебя только потому, что ты при этом улыбаешься. Суп стоит на горячем камне. Поешь и ложись, пожалуйста, ты совсем худой."},{"id":"magma_068","kind":"note","title":"Вторая приписка","text":"Теперь глина у Кенрика, ему отдали её за крышу. Прочесть её он не может, но говорят, что там про козу. Завтра он отдаст её Гвен за сало. Кто кому должен, все уже забыли, а глину берут охотно. Коза давно умерла от старости. Ида с Бертом закопали её вместе и поругались над ямой, как в лучшие годы.","chain":"pervyi_dolg","part":5},{"id":"magma_069","kind":"note","title":"Про Рольфа","text":"Рольф придумал запираться. Дверь у него теперь закрывается изнутри на палку. Вчера он закрылся, палку заклинило, а как открыть, он не придумал. Жена кормит его через окно. Окно пришлось сделать вчера же. Она говорит, что ей так нравится: муж дома, а спорить неудобно."},{"id":"magma_070","kind":"note","title":"Первая строка","text":"Мне шестьдесят лет, и я пишу первый раз. Вот знак: вода. Осберт посмотрел и спросил, откуда тут собака. Я рисовала долго и переделывать не буду. Внук сказал, что собака хорошая."},{"id":"magma_071","kind":"secret","title":"Письмо в нише","text":"Тому, кто будет тут жить после нас. Правый колодец горький, не пей из него, а левый хороший. Крышу у моего дома чинить не надо, она так и задумана. Жена ругала эту крышу до самой смерти, и я ни разу её не поправил, потому что любил, как она ругается. Будь здоров, кто бы ты ни был."},{"id":"magma_072","kind":"secret","title":"Про ступень","text":"Мы копали яму под домом старшего и нашли ступень, тёсаную. Ниже нашли ещё одну. Мы шли сюда сорок дней и пришли первые. На сходе договорились, что первые, и ступень засыпали. Я пишу это здесь, потому что детям я сказал то же самое, и мне от этого нехорошо."},{"id":"magma_073","kind":"secret","title":"Уголёк","text":"Говорят, что огонь не гас с тех пор, как его принесли. Он гас три раза. Я зажигала его снова от уголька, который лежит тут, в горшке с песком. Хэмишу я не скажу никогда, он так им гордится, и пусть гордится, он уже старый. Огонь-то всё равно тот же. Фрея."},{"id":"magma_074","kind":"secret","title":"Чужие знаки","text":"Эти знаки мы придумали с Тилли, кроме нас двоих их никто не прочтёт, так что пишу как есть. Хоб дурак. Его нож лежит у меня под камнем. Гвен нравится Вилл. Тилли, ты лучше всех, только не задавайся."},{"id":"magma_075","kind":"secret","title":"Карта ухода","text":"До старой стоянки четыре дня, если идти по ручью. Я рисую эту карту, чтобы уйти отсюда. Рисую третий год и всё поправляю ручей. На этой неделе уйти не получится, у младшей режется зуб. Муж про карту не знает. Он каждый вечер приносит мне воды и спрашивает, что я там царапаю, и я говорю, что ручей."},{"id":"magma_076","kind":"secret","title":"Кто у трещины","text":"Записываю, потому что мне никто не верит. Мы шли сорок дней и пришли сюда первые. А у трещины на камне уже сидел человек и грел руки. Он спросил, чего мы так долго. Каждая семья подумала, что он из другой семьи. Он и сейчас там сидит, и дети носят ему хлеб. Жена говорит, что я выдумываю, и кладёт мне каши побольше."},{"id":"magma_077","kind":"secret","title":"Признание","text":"Гуся взял я. Фиска судили за это, и он держался хорошо, дольше, чем смог бы я. Гусь, если кому интересно, был жёсткий. Фиск, ты ни разу не сказал, что видел меня. Я знаю, что ты видел. Рэн."},{"id":"magma_078","kind":"secret","title":"Про жребий","text":"Чёрные камешки мы с Длинным Гартом держим у очага всю ночь. В темноте рука сама находит тёплый. У него дети кашляют, и у меня кашляют. Другому Гарту об этом ни слова, он хороший человек и сразу всем расскажет."},{"id":"magma_079","kind":"secret","title":"Детской рукой","text":"это моё место. тут никто не ходит. снизу тепло и я ложусь ухом и слышу оно дышит. оно дышит медленно. дольше чем папа когда спит. я рассказываю ему про собаку. маме не скажу а то заберёт меня домой"},{"id":"magma_080","kind":"secret","title":"Про трещину","text":"Я мерил трещину верёвкой и никому об этом не сказал. За год она разошлась на длину руки. Дома мы только поставили, люди радуются, у Кейт родился второй, и она принесла мне его подержать. Я подержал и улыбался. Верёвку храню здесь, узел завязан на прошлогодней мерке."},{"id":"magma_081","kind":"boss","title":"Жалоба улицы","text":"Старшему от всей улицы. Каменщик опять поёт и начинает до света. Слов он не знает и вместо них называет камни, какой куда класть. Нота у него одна, и та чужая. Просим перенести пение на тот конец, где козы. С козами мы договорились. Только не говори ему, что это мы, он обидится, а он нам всем дома ставил.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_082","kind":"boss","title":"Детской рукой","text":"мой папа самый громкий. он носит камень на спине а меня на камне. когда он поёт тётя Эдна закрывает дверь. у неё дверь первая у нас. папа её и делал. он говорит пусть закрывает дверь хорошая","boss":"boss_colossus","floors":[13,16]},{"id":"magma_083","kind":"boss","title":"Записка соседки","text":"Ренна, каменщику выпала тёплая сторона, а он отдал её старой Мод и лёг у двери. Всю ночь он жаловался, что дует, и жаловался громко, чтобы все слышали, как ему холодно. Ему всегда холодно. Я отнесла ему шкуру, в эту зиму уже третью. Куда он их девает, я знаю: две теперь лежат у Мод.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_084","kind":"boss","title":"Расписка","text":"За подпорку под домом Орина получен мешок ячменя. Каменщик ячмень взял, потом вернул половину и сказал, что подпорка вышла так себе. Если дом осядет, пусть зовут его, он подопрёт плечом, так выйдет дешевле. Орин велел мне, жене, это записать. Я пишу и смеюсь, а Орин говорит: не смейся, этот придёт.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_085","kind":"boss","title":"Школьное задание","text":"Напиши, что умеет твой отец. Мой папа умеет поднять двух коз сразу. Ещё он умеет делать угол. Петь он не умеет, но мы ему не говорим. Меня он никогда не роняет. Нэн.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_086","kind":"boss","title":"Нэн, на сланце","text":"нас вела тётя Ренна всех на одной верёвке. было темно и пыль. папа стоял там где потолок шёл вниз. он сказал идите и что ему не тяжело. он пел как всегда плохо и я долго его слышала. тётя сказала не оборачивайся но слышать же можно","boss":"boss_colossus","floors":[13,16]},{"id":"magma_087","kind":"boss","title":"Список выведенных","text":"Мы вывели по верёвке Нэн, Робина, обоих мальчиков Длинного Гарта, Тилли с младшей и младенца Эдны, а всего двадцать три человека. Мы считали дважды, потом Эдна пересчитала сама, потому что не поверила. Всем дать воды и уложить спать. Верёвка эта каменщика, положите её ему на порог, он будет ругаться, если потеряем.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_088","kind":"boss","title":"Записка Ренны","text":"Нэн не спит и просит папину песню. Мы пели ей всей улицей. Слов никто не знает, там одни камни, какой куда. У Дорна вышло слишком хорошо, и она велела ему перестать. Гарт поёт хуже всех, и мы оставили Гарта. Он поёт ей уже четвёртую ночь и охрип. Наверное, за её отцом кто-то уже сходил. Завтра спрошу.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_089","kind":"note","title":"Объявление","text":"Найден сапог, правый. Кто потерял, приходите ко мне, к Теду, мой дом у самой стены. Сапог вам может оказаться велик, потому что он, честно говоря, мой, но вы всё равно приходите. Я живу один с тех пор, как мы пришли, и по вечерам мне не с кем поговорить."},{"id":"magma_090","kind":"note","title":"Письмо Хильде","text":"Хильда, ты сестра моей Марион, и только ты знаешь, как она пекла лепёшки. Я пробую уже девятый раз, и у меня получается подошва. Младшая не жалуется и ест, а старший молчит и грызёт. Скажи мне, сколько брать воды и когда класть жир. Я её об этом никогда не спрашивал, думал, что успею. Ансель.","chain":"lepeshki_vdovca","part":1},{"id":"magma_091","kind":"note","title":"Письмо под диктовку","text":"Дочка, пишет тебе мать, а внук царапает за меня. У нас всё хорошо. Спина болит, но это не пиши. Внук, я сказала, этого не пиши. Зачем ты написал? Сотри. Как это со сланца не сотрёшь? Тогда напиши, что я здорова, что пелёнки надо сушить подальше от дыма и что я скучаю. Про скучаю напиши большими знаками. Всё, неси."},{"id":"magma_092","kind":"note","title":"Договор","text":"Мы с невесткой договорились при свидетелях. Кашу варю я, хлеб печёт она. Какая каша вышла у меня, мы не говорим, и какой хлеб у неё, тоже. Сын у нас один на двоих, и никто из нас не будет спрашивать его, что вкуснее. Он честный мальчик, и его жалко."},{"id":"magma_093","kind":"note","title":"Полдень","text":"Мне поручили кричать полдень. Посреди площади воткнули палку, и когда тень дойдёт до белого камня, я кричу: обед! Кричу я очень громко, папа говорит, что это у меня от мамы. Раньше меня никто не слушал, а теперь все бросают работу и идут есть, стоит мне только крикнуть. Пип.","chain":"palka_poldnya","part":1},{"id":"magma_094","kind":"note","title":"Мазь от ожогов","text":"Дочка, раз ты пошла работать у трещины, запомни мазь. Возьми жир, вотри в него мокрую золу из печи, чтобы вышло как густая каша, и намажь там, где болит. Тряпку завязывай чистую, а если чистой нет, приходи за моей. Руку к жару не подноси, пока не заживёт. Я знаю, что ты меня не послушаешь, ты и в детстве совала руку в горшок."},{"id":"magma_095","kind":"note","title":"Записка на печи","text":"Уна, печь у нас одна на две семьи, и зола в ней опять твоя. Я с тобой не разговариваю с прошлой весны, поэтому велела внуку написать это на глине и положить на печь. Выгреби золу и не отвечай. Марта.","chain":"ssora_u_pechi","part":1},{"id":"magma_096","kind":"note","title":"Находка","text":"У трещины я нашла камень, лёгкий, как сухая лепёшка. Положила его в горшок с водой, и он поплыл. Дэви сказал, что камни не плавают и что у меня устали глаза. Я молча взяла этот камень и потёрла ему пятки, потому что он как раз сидел разувшись. Теперь Дэви просит потереть ещё и про глаза больше не говорит."},{"id":"magma_097","kind":"note","title":"Про купальню","text":"За дальними камнями есть горячая лужа, и Орин вчера вымылся в ней первым из нас. Жена не пустила его домой, потому что не узнала. Он стоял у двери и называл ей вещи, которые знает только он, и соседи всё это слышали. Теперь все знают, какого цвета у Орина шея и где у него родинка. Вечером у лужи стояла очередь."},{"id":"magma_098","kind":"note","title":"Про пчёл","text":"Я донесла пчёл! Сорок дней я несла горшок на спине, завязанный тряпкой, и придавила только пятерых. Муж всю дорогу говорил, что я сумасшедшая и что от пчёл нам никакой пользы, и всю дорогу шёл чуть сбоку, чтобы заслонять горшок от ветра. Улей я поставила на тёплом месте. Оуэн, я слышала, как ты вчера с ними разговаривал. Линет.","chain":"pchely_linet","part":1},{"id":"magma_099","kind":"note","title":"Приписка писца","text":"По этой глине прошла курица, пока глина была мягкая. То, что написано под лапой, читать не надо: там было про ячмень и кто кому сколько должен. Рольф говорит, что под лапой был его долг, и просит считать его прощённым. Я обжёг табличку как есть. Рольф, я помню твой долг и без курицы."},{"id":"magma_100","kind":"note","title":"Про соль","text":"Соль у нас кончилась двенадцать дней назад. Вчера Гвен варила на всех и всё плакала над котлом, вспоминала сына, и суп впервые за эти дни вышел вкусный. Никто ей об этом не сказал. Хоб попросил добавки, а потом долго сидел и смотрел в миску, и ему было стыдно. Кенрик завтра пойдёт к старой стоянке за солью."},{"id":"magma_101","kind":"note","title":"Наказ внуку","text":"Олли, я всю жизнь вёл людей по звёздам, и теперь вести некого. Чтобы это не пропало, я нацарапал тебе здесь всё, что знаю. Три яркие звезды в ряд всегда стоят над старой стоянкой. Та, что ниже всех и дрожит, показывает на воду. Ты спросишь, зачем тебе это, раз мы никуда не идём. Я и сам не знаю, внучек, садись и учи.","chain":"zvezdy_kedmona","part":1},{"id":"magma_102","kind":"note","title":"Чёрный камень","text":"Муж отполировал мне кусок чёрного камня от трещины, и в нём видно лицо. Я посмотрела и увидела свою мать, которую схоронила ещё в дороге. Потом я, конечно, поняла, что это я сама. Теперь по утрам я смотрю в него дольше, чем нужно. Мужу я сказала, что проверяю, нет ли на мне сажи."},{"id":"magma_103","kind":"note","title":"Про ящерку","text":"у ящерки отвалился хвост он потом сам бегал. я положила его к ней но она не взяла. мама сказала вырастет новый. я спросила а бабушкин зуб вырастет. мама сказала это другое. я спросила а бабушка. мама сказала иди гуляй"},{"id":"magma_104","kind":"note","title":"Ответ Хильды","text":"Ансель, воды бери столько, чтобы тесто перестало липнуть к руке. Жир клади в конце. Она сыпала щепоть соли и всегда плевала через плечо, но плевать, думаю, необязательно. Держи лепёшку на камне, пока она не начнёт пахнуть. И не пиши мне так, я потом весь вечер ничего не могу делать. Ты сам-то ешь? Хильда.","chain":"lepeshki_vdovca","part":2},{"id":"magma_105","kind":"note","title":"Записка учителю","text":"осберт это пишет мама. хэл сегодня не придёт потому что у него очень болит нога и он лежит. он хороший мальчик и надо дать ему лепёшку. мой почерк такой потому что я мама. до свидания осберт"},{"id":"magma_106","kind":"note","title":"Записка на печи","text":"Марта, золу оставила ты, потому что у твоего хлеба горелая корка, а у моего нет. Глину ты положила на мою сторону печи, и я на неё не смотрела. Внук прочитал её вслух, пока я смотрела в другую сторону. Я с тобой тоже не разговариваю. Уна.","chain":"ssora_u_pechi","part":2},{"id":"magma_107","kind":"note","title":"Записка сыну","text":"Кенрик, сынок, я посчитала: от моей двери до твоей девять шагов. За эту луну ты их ни разу не прошёл. Жена твоя ходит ко мне каждый день, говорит, что ты занят, и прячет глаза, добрая душа. Глину эту я передаю с ней. Каши я наварила на двоих, и если она остынет, я разогрею. Мать у тебя старая, но считать ещё умеет."},{"id":"magma_108","kind":"note","title":"Камень у тропы","text":"Здесь лежит Рыжий. Он шёл с нами сорок дней и ни разу не спросил, долго ли ещё. На стоянках он ложился рядом с тем, кому было хуже всех. Дети просили положить с ним кость, и мы положили."},{"id":"magma_109","kind":"note","title":"Жалоба Пипа","text":"Старшему от Пипа. Тень сегодня дошла до камня слишком рано. Я присмотрелся и увидел, что камень лежит ближе к палке, чем вчера. Рольф говорит, что ничего не знает, но у него под ногтями земля, и обедать он пошёл первым. Я вернул камень на место и сел рядом сторожить. Мама принесла мне поесть, чтобы я не голодал на работе, и всё время смеялась.","chain":"palka_poldnya","part":2},{"id":"magma_110","kind":"note","title":"Прошение","text":"В зимнем доме все просят переложить Тобина к дальней стене, потому что он храпит. Я прошу положить его рядом со мной. С тех пор как не стало моего Гэвина, по ночам у меня очень тихо, и я лежу и слушаю эту тишину. Пусть Тобин храпит сколько хочет, мне нужно только, чтобы кто-нибудь рядом дышал. Ханна."},{"id":"magma_111","kind":"note","title":"Завещание","text":"Я, Огден, пока ещё в своём уме, оставляю ложку дочери и мешок сыну. Долг Рольфу прошу считать уплаченным, потому что я всё равно не отдам. Положите меня так, чтобы была видна тропа, мне будет интересно, кто по ней идёт. Дочка, ты хорошая. Скажи брату, что он тоже, мне было неловко говорить ему это самому."},{"id":"magma_112","kind":"note","title":"Первый мёд","text":"Сегодня мы сняли первый мёд, всего две ложки, и разделили его между детьми, каждому по капле на палец. Тэм сначала плакал, потому что не знал, что это, а потом плакал, потому что мёд кончился. Пахнет он дымом, как и всё у нас, и нам это даже нравится. Оуэн сказал, что ему мёда не надо, а я нарочно не выскребла ложку до конца, дала ему помыть и смотрела из-за двери, как он моет её языком.","chain":"pchely_linet","part":2},{"id":"magma_113","kind":"note","title":"Загадка","text":"загадка. кто всё время сердится и всё время кладёт тебе побольше. подумай. подумала? это мама. вторая загадка. что выросло большое и никто не видел как. это я"},{"id":"magma_114","kind":"note","title":"Про сапоги","text":"Вдова старого Ульрика отдала Мику мужнины сапоги, потому что у Мика совсем развалились свои. Сапоги хорошие и скрипят на левую ногу, как скрипели у Ульрика. Когда Мик проходил мимо, вдова выходила на порог и потом долго там стояла. Теперь Мик идёт мимо её дома босиком, а сапоги несёт в руках. Он мне об этом не говорил, я сам видел из окна."},{"id":"magma_115","kind":"note","title":"Закон о перекличке","text":"Как стемнеет, пусть из каждого дома кто-нибудь крикнет со двора: у нас все дома. Так проще, чем ходить и считать. Вчера крикнули тринадцать раз, а домов у нас двенадцать. Кейт говорит, что последний голос шёл снизу и был похож на детский. Я думаю, что это Другой Гарт крикнул дважды, чтобы его заметили. Прошу всех кричать по одному разу. Детям про это не говорите."},{"id":"magma_116","kind":"note","title":"Вторая запись","text":"Олли, сегодня ночью ты нашёл звезду над водой сам, без подсказки, и я притворился, что не удивился. Твоя мать говорит, что тебе надо учиться класть камень, потому что камень кормит. Она права. Ты всё равно приходи ко мне, только после ужина, и не говори ей, что я тебя хвалил.","chain":"zvezdy_kedmona","part":2},{"id":"magma_117","kind":"note","title":"Объявление","text":"Покажу, где течёт камень. Плата одна лепёшка. Я иду впереди, а вы идёте за мной и ступаете туда, куда ступил я. Обратно веду бесплатно. Маме не говорите, она думает, что я помогаю Альде. Если вы и есть моя мама, то я правда помогаю Альде, а это написал кто-то другой. Хэл."},{"id":"magma_118","kind":"note","title":"Записка Мейв","text":"Мейв, я пока выучил только двенадцать знаков, поэтому пишу как умею. Ты хлеб. Ты вода. Когда ты идёшь мимо, у меня нет хлеба. Я камень, и ячмень мне не нужен. Осберт посмотрел и сказал, что ошибок нет. Я знаю, что хотел сказать, только для этого нужно ещё знаков восемьдесят, и я их выучу. Родри."},{"id":"magma_119","kind":"note","title":"Что я оставила","text":"На старой стоянке я оставила гребень, потому что думала, что мы вернёмся через неделю. Ещё я оставила чашку с отбитым краем, яблоню, которая только начала цвести, и могилу мамы, за которой теперь некому смотреть. Орин велел каждому записать, что осталось, чтобы потом попросить тех, кто пойдёт туда торговать. Кроме гребня, ничего не просите."},{"id":"magma_120","kind":"note","title":"Записка на печи","text":"Уна, твоя сторона печи холодная уже третий день. Если ты так со мной воюешь, то это низко, и я скажу об этом твоей дочери. Хлеб у меня вышел лишний, и я поставила его на твой порог. Корка горелая, как ты любишь говорить. Заберёшь ты его или нет, мне всё равно, я просто посмотрю в окно.","chain":"ssora_u_pechi","part":3},{"id":"magma_121","kind":"note","title":"В рубахе","text":"Рукава длинные, потому что ты растёшь. Не говори мне, что они длинные, просто подогни. Шила я при огне, и левый шов вышел кривой, зато правый хороший. Носи, мой родной, и не отдавай её Пипу за камешки."},{"id":"magma_122","kind":"note","title":"Праздник прихода","text":"Сегодня год, как мы сюда пришли, и все сказали, что надо это отпраздновать. Как это делается, никто не знает. Орин велел всем взять мешки, выйти на тропу, пройти полдня назад и прийти ещё раз. Мы пошли. Дети бежали впереди, старики бранились, а на подходе многие почему-то заплакали, хотя мы сами только что отсюда вышли. Суп за это время подгорел, потому что оставить при нём было некого."},{"id":"magma_123","kind":"note","title":"Пасмурный день","text":"Сегодня весь день тучи, тени нет, и никто не знает, когда кричать. Я спросил у своего живота и крикнул, когда он сказал. Все пришли. Орин сказал, что живот у меня точнее палки, и похлопал меня по спине, и теперь все зовут меня Живот. Мама говорит, что это почётно. Я думаю, она так говорит, чтобы я не ревел.","chain":"palka_poldnya","part":3},{"id":"magma_124","kind":"note","title":"Про слово","text":"Дочка, перед свадьбой спроси жениха, что у него дома значит слово недалеко. У нас недалеко значило, что дойдёшь к обеду. Когда твой отец сказал мне, что его родня живёт недалеко, мы шли двадцать шесть дней, и по дороге я родила твоего брата. Он и сейчас говорит, что до ручья недалеко. Я его люблю, но пока сама не спрошу кого-нибудь ещё, за водой с ним не пойду."},{"id":"magma_125","kind":"note","title":"Записи повитухи","text":"Здесь у нас родилось уже девять, и я записываю, кто как закричал, потому что матери потом спрашивают. Тэм молчал, пока за дверью не заорал Рольф, и тогда ответил ему. Дочка Кейт кричала так, будто у неё что-то украли. Мальчик Эдны не закричал совсем, и я дула ему в рот, пока сама на него не закричала, и тогда он закричал тоже. Эдна потом смеялась, плакала и просила записать, что он послушался сразу."},{"id":"magma_126","kind":"note","title":"Про мёд","text":"Пчёлы стали летать только в одну сторону, к трещине. Цветов там нет, я ходила и смотрела сама: там голый камень и жар. Они возвращаются тяжёлые, с серым на лапках, и садятся у летка, как будто устали. Оуэн сказал, что пчёлы знают своё дело. Он это сказал, чтобы я спала, и я притворилась, что сплю.","chain":"pchely_linet","part":3},{"id":"magma_127","kind":"note","title":"Про запах","text":"Гвен утром вышла и спросила, кто печёт. Никто не печёт, ячменя нет уже неделю, но из трещины идёт запах свежего хлеба, и с каждым утром он всё сильнее. Дети ходят туда нюхать, и я их не держу, больше мне нечего им дать. Хочу спросить у старшего, кто там внизу печёт, и боюсь, что он ответит."},{"id":"magma_128","kind":"note","title":"Про верёвку","text":"Мой Гилл ходит по ночам во сне к трещине, поэтому я привязываю его к своей ноге. Вчера он встал, пошёл и стащил меня с лежанки до самого порога. Там мы оба проснулись и долго бранились шёпотом, чтобы не будить детей. Потом он заплакал и сказал, что ему снится, будто его кто-то зовёт обедать. Я укоротила верёвку на два локтя."},{"id":"magma_129","kind":"note","title":"Считалка","text":"Дети опять считаются, кому водить: раз шажок и два шажок, сорок дней, и все идут, кто дошёл, тот будет тут, а кто сел, тот и водит. Я спросила Тилли, откуда это. Она сказала, что это все знают. Мы никогда не рассказывали им про тех, кто сел. Я велела считаться по-другому, а они посмотрели на меня и стали считаться дальше."},{"id":"magma_130","kind":"note","title":"Лишняя лепёшка","text":"Это не тебе, это Дэви, отнеси и не ешь по дороге. Я знаю, что он на всех так смотрит, у него такое лицо. Но вчера я заметила, что он теперь обходит наш костёр стороной, чтобы не смотреть, и мне это не нравится. Скажи ему, что лепёшка лишняя и что я пекла не считая. Приходи засветло."},{"id":"magma_131","kind":"note","title":"Очередь на гребень","text":"Гребень у нас один на всю улицу, поэтому очередь такая. С утра он у Ренны, днём у Бет, вечером у Гвен. Верните его со всеми зубьями, у него их и так осталось девять. Сегодня гребень сначала получает Кейт, потому что она вечером куда-то идёт. Куда именно, мы не спрашиваем и все знаем."},{"id":"magma_132","kind":"note","title":"Про ласточек","text":"Под крышей у нас завелись ласточки, первые птицы, которые решили, что тут можно жить. Рольф пошёл сбить гнездо, потому что ему капает на порог, а жена встала перед ним с метлой и сказала: попробуй. Сорок дней мы шли, сказала она, и ни одна птица за нами не шла. Теперь Рольф обходит порог стороной и ворчит, а по утрам выходит посмотреть."},{"id":"magma_133","kind":"note","title":"Про поле","text":"Ячмень с тёплой стороны вырос выше Другого Гарта. Такого мы раньше не видели: зерно тяжёлое, соломы на всю зиму, а земля под ним чёрная, и в ней полно пепла. Орин сказал, что это награда нам за всё. Мой муж молча смотрит на это поле и берёт зерно только с краю. Я сварила кашу, и она очень вкусная. Дети просят ещё."},{"id":"magma_134","kind":"note","title":"Записка внука","text":"Тётя Марта, это пишет внук Уны. Бабушка лежит четвёртый день и очень кашляет. Хлеб она есть не может, но она его понюхала и сказала, что корка горелая. Она велела передать вам, что не разговаривает с вами. Потом позвала меня обратно и велела написать, чтобы вы пришли и услышали это от неё сами.","chain":"ssora_u_pechi","part":4},{"id":"magma_135","kind":"note","title":"Про стул","text":"У нас появился стул. Вилл сколотил его из двух жердей и куска доски и первым делом позвал всех посмотреть. Мы по очереди посидели, и никто не понял, зачем это, когда есть земля. Потом стул отдали Альде, потому что у неё колени. Теперь она сидит на нём возле двери очень прямо и смотрит на всех сверху, а мы ходим мимо и здороваемся, как со старшим."},{"id":"magma_136","kind":"note","title":"Про два дня","text":"Все говорят, что мы шли сорок дней. Мы шли сорок два. Орин велел говорить сорок, потому что так легче считать и легче запомнить детям. Те два дня мы хоронили мою Анну, рыли каменистую землю и никуда не шли. Орин сказал, что это не считается, раз мы стояли на месте. Я не держу на него зла. Я только хочу, чтобы эти два дня где-нибудь были записаны."},{"id":"magma_137","kind":"note","title":"Про козу","text":"Младшая не засыпает без песни про козу, а песню про козу никто из нас до конца не помнит. Гвен спела мне совсем другое. Альда сказала, что коза там в конце умирает, и велела не вспоминать. Поэтому я пою, сколько знаю: спи, коза стоит у стены, спи, коза не видит сны. Кто там ходит? Это дождь. Дальше я мычу. Младшая говорит, что мычу я неправильно, и засыпает."},{"id":"magma_138","kind":"note","title":"Про палку","text":"Я никому не показываю эту запись. Палка наклонилась к трещине, и обед приходит всё позже. Вчера я воткнул её заново, прямо, и обложил камнями, а сегодня она опять стоит криво, и земля вокруг неё съехала. Папа посмотрел и велел кричать как обычно. Он сказал: люди хотят обедать, сынок, вот и пусть обедают. А сам в обед ничего не ел.","chain":"palka_poldnya","part":4},{"id":"magma_139","kind":"note","title":"Про круг","text":"Кенрик вытесал из бревна круг и сказал, что теперь камень поедет сам, надо только положить его сверху. Камень сам не поехал. Поехал круг, без камня, через весь склон и прямо в трещину. Кенрик стоял и смотрел ему вслед, как смотрят вслед сыну, и я взяла его за руку. Он уже рубит второй круг, и я сказала: этот хотя бы привяжи."},{"id":"magma_140","kind":"note","title":"Снег для Тэма","text":"У нас снег тает, не долетев до крыши, и Тэм за всю жизнь его не видел. Вчера я отвела его за стену, полдня вверх по горе, только затем, чтобы показать. Он взял снег в рот и сказал, что его обманули. Обратно я несла его на спине, он спал и держал в кулаке мокрую рукавицу."},{"id":"magma_141","kind":"note","title":"Пари","text":"Тобин и Хоб поспорили, кто из них проживёт дольше. Ставка одна кружка, и табличку держу я. Условие такое: кто останется, тот выпьет кружку на могиле и скажет покойнику, что он был дурак. Оба уже приходили ко мне по отдельности и просили, если выиграет другой, налить ему полную. Рэн."},{"id":"magma_142","kind":"note","title":"Сказать пчёлам","text":"Мать учила меня, что пчёлам про смерть надо сказать самой, иначе они уйдут. Вслух я не смогла, поэтому пишу и кладу глину на крышку улья. Пчёлы, Оуэн умер этой ночью. Он заслонял вас от ветра сорок дней, а вы этого, наверное, не заметили. Мёда в этом году можно поменьше. Не уходите, пожалуйста. Мне ещё надо вас кормить на зиму.","chain":"pchely_linet","part":4},{"id":"magma_143","kind":"note","title":"Маме","text":"мама вставай я сварил кашу. она чёрная снизу но сверху хорошая. папа сказал не будить. я не бужу я положил это на тебя чтобы ты сама проснулась. папа потом прочитает тебе. я съел только немного сверху"},{"id":"magma_144","kind":"note","title":"Записка на печи","text":"Уна, я приходила, ты спала, и я посидела. Золу с твоей стороны печи я выгребла, раз уж всё равно стояла рядом. Я с тобой не разговариваю, я говорила с твоей подушкой. Поправляйся. Мне без тебя не на кого злиться, и от этого у меня плохо поднимается тесто. Марта.","chain":"ssora_u_pechi","part":5},{"id":"magma_145","kind":"note","title":"Предложение","text":"Элспет, мне семьдесят один год, у меня есть дом с крышей и девять зубов. Ты знаешь, что я храплю. Я знаю, что ты ругаешься. Мы оба уже похоронили кого могли, и каждый вечер я хожу к тебе через грязь за углём, хотя свой уголь у меня есть. Выходи за меня, и ходить никому не придётся. Если нет, я всё равно приду завтра. Мартин."},{"id":"magma_146","kind":"note","title":"Про дочку","text":"Дочка теперь умеет читать, и это очень неудобно. Всё, что я царапаю про её мать, мне приходится прятать, а всё, что про неё, она находит. Вчера она нашла запись о том, как она родилась и как я боялся. Подошла, обняла меня за шею и ничего не сказала. Потом спросила, почему хлеб написан с ошибкой."},{"id":"magma_147","kind":"note","title":"Про мальчика","text":"Те трое, что просили воды, ушли дальше, а мальчик у нас остался. Они сказали, что вернутся за ним через луну, и с тех пор прошёл год. Мы записали его как нашего и зовём Дилан, потому что своё имя он нам так и не сказал. Жена шьёт ему вторую рубаху и каждый вечер спрашивает, не прошла ли та луна. Я говорю ей, что ещё нет."},{"id":"magma_148","kind":"note","title":"Поправка писца","text":"Писец просит прощения. На прошлой табличке у меня смазался знак, и вышло, что Хоб умер. Хоб жив. За вчерашний день ему принесли две миски каши и сказали про него много хорошего, и он просит пока не исправлять. Жена Хоба велела исправить сегодня, пока он не начал принимать ещё и подарки."},{"id":"magma_149","kind":"note","title":"Письмо Хильде","text":"Хильда, на этот раз вышло лучше, и младшая сказала, что совсем как у мамы. Врать она тоже научилась у мамы. Старший посмотрел на меня, откусил, ничего не сказал, но съел всё и попросил ещё одну, и я вышел на улицу постоять. Соль я кладу, как ты велела. Плевать через плечо я тоже стал, на всякий случай.","chain":"lepeshki_vdovca","part":3},{"id":"magma_150","kind":"note","title":"Про лестницу","text":"Кто вчера взял лестницу, знай, что я в это время сидел на крыше. Я просидел там до темноты и кричал, пока не охрип, а потом от скуки починил всю крышу, которую жена просила починить с весны. Лестницу верни. Жена просила передать тебе спасибо и сказала, что, если понадобится, она сама её унесёт ещё раз."},{"id":"magma_151","kind":"note","title":"Присмотри за курами","text":"Вилл, мы уходим за хворостом на два дня, и кур кормишь ты. Чёрная клюётся. Ей надо по утрам говорить, что она хорошая, иначе она перестаёт нестись. Я знаю, как это звучит, но ты всё равно скажи, и скажи вслух. Никто, кроме неё, тебя не услышит. Жена говорила ей это всю прошлую зиму и теперь не хочет признаваться."},{"id":"magma_152","kind":"note","title":"Последняя запись","text":"Дым от трещины теперь висит над нами всю зиму, и звёзд не видно уже вторую луну. Я нарисовал их тебе на этом сланце, все, какие помню, и твоя мать сказала, что нарисовал я криво. Я и правда помню их немного хуже, чем раньше. Когда я умру, поднимись за стену на гору, там дыма нет. Посмотри, правильно ли я нарисовал, и если нет, поправь.","chain":"zvezdy_kedmona","part":3},{"id":"magma_153","kind":"note","title":"Через трещину","text":"Сибил, трещина прошла между нашими домами, и теперь я живу на этой стороне, а ты на той. Эту глину я кину тебе вместе с хлебом, поэтому лови внимательнее. Вчера ты не поймала, и мы обе стояли и смотрели, как он падает, и долго не слышали, чтобы он упал. Завтра я кину повыше. Руки держи шире и кричи мне, если что, я услышу."},{"id":"magma_154","kind":"note","title":"Про колено","text":"Колено Эльмы сказало, что завтра пойдёт дождь. Кому надо сушить, сушите сегодня. В прошлый раз колено ошиблось, и Эльма неделю не выходила из дому от стыда. Потом мы все пришли к ней и сказали, что дождь в тот день всё-таки был, просто не у нас, и она сразу захотела есть."},{"id":"magma_155","kind":"note","title":"Решение детей","text":"Мы тоже собрали сход и решили. Взрослым после темноты не кричать. Лук в суп не класть. Кто старше, тот не бьёт, а кто младше, тот не ябедничает, если его не били. Старшая у нас Тилли, потому что у неё самый большой камешек, и её выбрали все, кроме Пипа. Пип может не соглашаться, мы записали. У него тоже есть камешек, но он маленький."},{"id":"magma_156","kind":"note","title":"Записка Анселя","text":"Хильда, спасибо, что пришла и показала, как мять. Дети весь вечер тебя не отпускали, а младшая заснула у тебя на коленях, и я не стал её будить. На улице уже говорят про нас с тобой. Пусть говорят, я всем всё объясню. Или не буду объяснять, если ты не против. Приходи в шестой день, тесто я поставлю сам.","chain":"lepeshki_vdovca","part":4},{"id":"magma_157","kind":"note","title":"Надпись на двери","text":"Тише, пожалуйста. Эдна спит первый раз за шесть дней, потому что младенец наконец тоже уснул. Кто сейчас постучит, тот будет качать его сам, и качать будет столько, сколько скажу я. Её муж."},{"id":"magma_158","kind":"note","title":"От тоски","text":"От тоски делай так. Встань до света, принеси воды и вымой кого-нибудь, кто сам не может. Если к вечеру не прошло, сходи и помоги Гвен месить. Если на другой день тоска всё равно осталась, приходи ко мне, у меня есть лавка и две кружки. Вылечить я тебя не вылечу, но мы посидим, у меня это тоже с самого прихода. Альда."},{"id":"magma_159","kind":"secret","title":"Письма Гилберту","text":"Сын Гилберта ушёл на старую стоянку, и вестей от него нет уже шестой год. Гилберт ослеп и просит меня читать ему письма. Я читаю с пустого сланца. Сегодня сын написал, что у него всё хорошо, что он купил двух коз и просит отца не волноваться. Гилберт сказал, что сын стал лучше писать. Потом он погладил сланец и сказал, что чистый камень хорошо ложится в руку, и я до сих пор не знаю, что он имел в виду."},{"id":"magma_160","kind":"secret","title":"На двадцать девятый день","text":"На двадцать девятый день мой брат Бэзил сел и сказал, что догонит. Я сел рядом и сказал, что тоже не тороплюсь. Всю ночь он ругал меня за то, как я увязал мешок, а под утро велел взять его нож, потому что нож хороший, и умер. Я положил ему камень с белой меткой. Матери я сказал, что последним его словом было её имя. На самом деле последнее слово было про мешок. Мешок я с тех пор увязываю так, как он велел."},{"id":"magma_161","kind":"secret","title":"Ближе всех","text":"Тридцать лет мой муж думает, что я выбрала его за то, что он поднял на спор бревно. Мать тогда сказала: выбирай, пока не стемнело, а он просто стоял ближе всех. Я никому этого не говорила и ему не скажу. Если бы я выбирала сейчас, я бы опять взяла того, кто стоит ближе. Он каждое утро стоит ближе всех. Бет."},{"id":"magma_162","kind":"secret","title":"Кора в лепёшках","text":"Вы все спрашиваете, почему у меня хватает лепёшек на всю улицу, хотя ячменя у меня столько же, сколько у вас. В муку я добавляю толчёную кору, в обычный год горсть, а в плохой две. Всем я говорю, что это мамин рецепт, и перед мамой мне стыдно. Мешок с корой я прячу здесь. Тобин хвалит мои лепёшки больше всех, и ему я кладу побольше, пусть крепнет. Гвен."},{"id":"magma_163","kind":"secret","title":"Клад","text":"это мой клад. тут мой зуб, сестрин зуб (она не знает), чёрное стекло и ухо от кружки. если ты нашёл положи обратно. если ты большой и нашёл то я тебя не знаю и клад всё равно мой. ухо от кружки не бери это бабушкино"},{"id":"magma_164","kind":"secret","title":"Под большим камнем","text":"Я не умею быть старшим. Каждый вечер я хожу к большому камню, сажусь и делаю вид, что думаю, а люди проходят мимо и говорят друг другу: думает. Днём я решаю так, как мне вечером сказала жена. Она всё знает, гладит меня по голове и велит никому не рассказывать. Я и не рассказываю, я только кладу это под камень, потому что писать она не запрещала. Орин."},{"id":"magma_165","kind":"secret","title":"Осберту","text":"Осберт, не говори моей дочери, что я уже два года хожу к тебе учиться и знаю все знаки. Она теперь показывает мне по вечерам, как пишется вода, и сердится, когда я путаю, и сердится точно так же, как я. В третьем знаке я каждый раз нарочно делаю ошибку. Мне нужно ещё хотя бы зим пять, пока она не вырастет. Вот тебе ячмень за молчание."},{"id":"magma_166","kind":"secret","title":"Сырые щепки","text":"Альда каждое утро ругает меня через стену за то, что я сложила ей щепки сырые. Это правда, сырые. Сухие у меня тоже есть, но, когда она ругается, к ней возвращается голос, а после смерти мужа она неделю ни с кем не говорила. Поэтому я хожу до света, кладу ей щепки посырее и стою во дворе, жду. Вчера щепки вышли почти сухие, случайно, и она сама пришла спросить, не заболела ли я."},{"id":"magma_167","kind":"secret","title":"Клятва","text":"мы клянёмся что когда вырастем пойдём дальше конца дороги и посмотрим что там. пип мейв и хэл. кто не пойдёт тот пепел. Ниже другой рукой: Мне сорок лет, я поправлял эту стену и нашёл. Дальше конца дороги мы так и не сходили, потому что у Мейв дети, а у Хэла колено. Мейв, ты всё ещё считаешься пеплом, и я тоже."},{"id":"magma_168","kind":"secret","title":"Под порогом","text":"Дочка, я пишу это и кладу под порог, чтобы ты нашла, когда меня не будет. Я ругала всех, кто ходит по моему месту, чтобы его никто не занял. Оттуда видно твою дверь. Другим не рассказывай, пусть обходят и боятся. И поставь уже наконец лавку так, чтобы я видела, как ты на ней сидишь. Мод."},{"id":"magma_169","kind":"boss","title":"Про куклу","text":"Каменщик сделал дочери куклу из камня. Кукла вышла очень похожей и весит как ягнёнок, и поднять её Нэн не может. Поэтому по вечерам он сам носит куклу по улице, а Нэн идёт рядом и велит ему, куда её поворачивать, чтобы кукле было видно. Сначала мы смеялись. Теперь здороваемся с ними обеими.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_170","kind":"boss","title":"Про балку","text":"Пока искали подпорку для балки у Хоба, каменщик подставил плечо и сказал: идите, я подержу. Мы пошли за подпоркой, по дороге зашли к Гвен поесть, и каждый думал, что подпорку несёт кто-то другой. Вспомнили только вечером. Он так и стоял и сказал, что ничего, он как раз думал про суп. Мне стыдно. Мы все принесли ему супу.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_171","kind":"boss","title":"За обедом","text":"Сегодня за обедом из каменщика выпал камень. Он греет их у трещины и носит за пазухой, потому что ему всегда холодно. Гвен спросила, сколько там ещё. Он посмотрел и сказал, что два. Один он отнёс Нэн, она у него мёрзнет, а второй отдал Гвен, потому что у неё холодные руки. Гвен потом весь день ходила и грела им всех подряд.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_172","kind":"boss","title":"Робин, на сланце","text":"Отец третий год показывает мне, как ставить угол. Я не вижу, чем этот угол лучше других. Я хочу к козам, козы хотя бы идут туда, куда им сказали. Ему я этого не говорю, потому что вечером он спрашивает меня, как угол, и так радуется, что я отвечаю: хорошо, папа. Нэн всё знает и молчит за лепёшку. Робин.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_173","kind":"boss","title":"Про заднюю стену","text":"Он клал мне заднюю стену и спросил, с какой стороны спит моя мать. Я сказал, что с северной, и подумал: какое ему дело? С этой стороны он положил стену в два камня толщиной и за второй камень ничего не взял. Сказал, что там дует. Там и правда дуло. Мать умерла той зимой, а стена осталась толстая. Теперь с этой стороны сплю я.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_174","kind":"boss","title":"Нэн, про камни","text":"папа лижет камни. он говорит хороший камень на вкус как вчерашний суп а плохой как мокрый уголь. я тоже лизнула и у меня болел язык. тётя ренна сказала что папа такой один и нам этого хватит. он лизнул наш порог и сказал порог будет стоять","boss":"boss_colossus","floors":[13,16]},{"id":"magma_175","kind":"boss","title":"Письмо Нэн","text":"Нэн, ты спрашивала, как мы с отцом поженились. Он пришёл к моей матери и принёс один камень, плоский и тяжёлый. Мать спросила, что это такое. Он сказал, что это порог, а дом он принесёт потом. Мы смеялись, а он всё не уходил и стоял с этим камнем в руках. Дом он принёс, ты в нём спишь. Порог он до сих пор каждую весну поправляет, хотя там нечего поправлять.","boss":"boss_colossus","floors":[13,16]},{"id":"magma_176","kind":"boss","title":"Про ступень","text":"Каждую весну каменщик приходит к колодцу с бечёвкой и снимает мерку с детей. Потом он говорит, что нижняя ступень осела, и перекладывает её. Ступень не оседала. Дети растут, и он делает так, чтобы самая маленькая дотягивалась до края. Младшей Гвен в этом году ступень уже не нужна, а он всё равно пришёл и постоял. Мы налили ему ячменной воды, и он сел с нами.","boss":"boss_colossus","floors":[13,16]},{"id":"pilot_001","kind":"note","title":"Список покупок","text":"Милый, купи соли и верёвки. Свечи бери, если дадут в долг. Верёвки возьми побольше, та, что ты принёс, оказалась короткая и не достала до дна. Мазь от укусов тоже не забудь. И скажи Тому, чтобы спал наверху. Меня он не слушает, а тебя, может быть, послушает, и я за него боюсь."},{"id":"pilot_002","kind":"note","title":"Жалоба соседу","text":"Господин Брейн! Ваши бочки стоят на моей половине подвала уже третий год. Если к воскресенью они не уедут, я напишу старосте, и не думайте, что не напишу, я вас двадцать лет терплю. Прошу также объяснить, почему одна из них ночью передвинулась. Если это вы сами ходите туда двигать её мне назло, я, так и быть, успокоюсь. Если не вы, зайдите, пожалуйста, мне страшно, а больше позвать некого."},{"id":"pilot_003","kind":"note","title":"Детской рукой","text":"я нашол дверцу за мешками. там ещё лестница вниз. мама сказала там ничего нет. а откуда она знает если она не ходила. я схожу посмотрю и ей расскажу чтобы она не боялась"},{"id":"pilot_004","kind":"note","title":"Рецепт","text":"Дорогая Элла, вот мамин рецепт капусты на зиму, ты просила. Сложи кочаны в кадку, всыпь четыре горсти соли и поставь сверху гнёт. Через месяц капуста будет готова. Гнёт не снимай, пока кадка шевелится. Мама всегда так говорила, и мы с тобой над ней смеялись, а зря. Поцелуй за меня детей."},{"id":"pilot_005","kind":"note","title":"Записка мужу","text":"Я ушла к сестре и детей забрала с собой. Тебе я оставила хлеб на полке и тёплую куртку. Ты опять скажешь, что копать осталось ещё один пролёт и мы разбогатеем. Я сама слышала, Мартин, как из твоей ямы кто-то зовёт тебя по имени. Я тебя люблю, поэтому и ухожу. Приходи к нам, когда перестанешь копать."},{"id":"pilot_006","kind":"note","title":"Расписка","text":"Я, Ольрик Панч, должен пекарю Хэлу четыре монеты и извинения. Монеты отдам к празднику. Извинения отдам, когда перестану злиться, то есть, зная нас обоих, к следующему. Мы с Хэлом дружим сорок лет, и он знает, что я отдам всё."},{"id":"pilot_007","kind":"note","title":"Табличка на стене","text":"Паутину не трогайте, она держит потолок. Когда Дженкинсы смахнули свою метлой, потолок сел им на шкаф. Это приказ старосты, а от себя прошу вас, соседи, поберегите детей."},{"id":"pilot_008","kind":"note","title":"Объявление","text":"Ищу кота. Он рыжий, с одним ухом и откликается на Судью. Кто его найдёт, пусть не берёт на руки и сразу идёт к лекарю, потому что с тех пор, как он пожил в подвале, у него ядовитый укус. Я вырастил его из котёнка, за ужином он сидит на моём стуле, и без него мне пусто в доме. За кота заплачу две монеты, за лекаря тоже."},{"id":"pilot_009","kind":"note","title":"Записка у ниши","text":"Элис, милая, я вырезал нам скамейку у колодца, как ты хотела. Сядем на неё, когда потеплеет. Плащ я оставил в нише за второй бочкой. Прошлый хлеб ты забрала, и я обрадовался. Мне всё равно, какая ты теперь. Ты так и не сказала, холодно ли тебе там внизу, скажи только это, и я принесу ещё один плащ."},{"id":"pilot_010","kind":"note","title":"Журнал сторожа","text":"Идёт первая неделя на складе. Платят хорошо, и работа простая: утром и вечером считать мешки. Утром их было сорок, а вечером оказался сорок один. Я спросил у хозяина, и он велел считать внимательнее. Журнал я веду, потому что сестра говорит, что память у меня дырявая. Мэй, если читаешь, со мной всё хорошо, деньги пришлю к концу месяца.","chain":"watchman","part":1},{"id":"pilot_011","kind":"note","title":"Журнал сторожа","text":"Сегодня мешков сорок семь, и один из них тёплый. Хозяин больше не спускается сюда, а деньги оставляет на лестнице. Мэй, я хотел отказаться от места, но эти деньги пойдут на твою свадьбу, так что потерплю. Ты не волнуйся, я сплю с лампой и в мешки не заглядываю.","chain":"watchman","part":2},{"id":"pilot_012","kind":"note","title":"Журнал сторожа","text":"Теперь я считаю вслух, чтобы не сбиться. Сегодня кто-то считает вместе со мной, и получается у него лучше. Голос у него вежливый, он меня поправляет. Деньги я сложил в жестянку за дверью склада. Мэй, если к празднику я не приду, забери их, выходи за своего Питера и не ходи сюда меня искать. Я очень по тебе скучаю.","chain":"watchman","part":3},{"id":"pilot_013","kind":"secret","title":"Записка из тайника","text":"Если ты это читаешь, значит, ты нашёл мой тайник, а денег тут больше нет, я их потратил. На жену, если тебе от этого легче: она всю жизнь хотела синюю шаль. Это моя третья такая записка. Мне нравится думать, что кто-то ищет, и тогда мы с тобой, дружище, вроде как знакомы."},{"id":"pilot_014","kind":"secret","title":"Записка из тайника","text":"Каменщик из соседнего квартала клянётся, что кладка под нашей улицей точно такая же, как наверху: те же клейма и та же рука. Я попросил его больше так не шутить, у меня дети. Он ответил, что не шутил, а потом долго молчал и налил нам обоим. Мы дружим с ученичества, и я ни разу не видел, чтобы у него так дрожала рука."}];
})(typeof window !== 'undefined' ? window : globalThis);
